\section{Missing proofs on root operators}

An extremely useful tool to obtain lower bounds on the state complexity of languages is the use of dividing sets. 

\begin{definition}

	Let $L \subseteq \Sigma^*$, then $\mathcal{F} = \{ x_1,...,x_n \}$ is a dividing set for $L$ if and only if for all $\ x_i \neq x_j$,  there exists $z_{i,j} \in \Sigma^*$ such that $\ x_iz_{i,j}\in L \ $ and $ \ x_jz_{i,j} \notin L $ or $\ x_iz_{i,j}\notin L \ $ and $ \ x_jz_{i,j} \in L $.

\end{definition}

The following fact explains why those dividing sets are useful when studying the state complexity of a language. 

\begin{fact}

Let $\mathcal{F}$ be a dividing set of $L$. Then any DFA recognizing $L$ must have at least $|\mathcal{F}|$ states.

\end{fact}

\begin{proposition}\label{quotient_diff_alph_sqrt}

Let $v,w$ be two words with different alphabets: $\Sigma(v)\neq\Sigma(w)$. Then $\sqrt{\upc(V_n)}/v \neq \sqrt{\upc(V_n)}/w$. 

\end{proposition}

\begin{proof}

    As $v$ and $w$ are based on different alphabets, there is a letter of $V_n$ that is either in $v$ and not in $w$ or in $w$ and not in $v$. Without loss of generality, let us assume the letter $a$ is in $v$ but not in $w$.

    Then let $x$ be $V_n$ with $a$ removed. 
    Thus, $V_n$ is a subword of $(vx)^k$ but not of $(wx)^k$. Thus, $vx \in \sqrt[k]{\upc (V_n)}$ but $wx \notin \sqrt[k]{\upc (V_n)}$. Hence, $\sqrt[k]{\upc (V_n)}/v \neq \sqrt[k]{\upc (V_n)}/w$ since one contains $x$ but not the other.
%
\qed        
\end{proof}

\begin{proposition}\label{better_dividing_set_sqrt_down}

	Let $\mathcal{F}_n$ be a dividing set of maximal size for $\sqrt{\upc(V_n)}$. 

	Then $\mathcal{F}_n \bigcup \mathcal{F}_n a_{n+1} \bigcup a_{n+1}(\mathcal{F}_{n-1} \setminus \{ V_{n-1} \}) a_n$ is a dividing set for $\sqrt{\upc(V_{n+1})}$.

\end{proposition}

\begin{proof}

Let $u,v$ in $\mathcal{F}_n \bigcup \mathcal{F}_n a_{n+1}$, 
    If they do not come from the same summand, then their alphabet is not the same as one uses $a_{n+1}$ while the
    other does not. Thus by \Cref{quotient_diff_alph_sqrt}, their quotients are different.\\ 

    If they come from the same summand, first let us assume they come from $\mathcal{F}_n$. Then there is a word $x \in \Sigma^*$ such that $ux \in L_n$ and $vx \notin L_n$. Thus $V_n$ is a subword of $uxux$ but not of $vxvx	$, hence $u_{n+1}$ is a subword of $uxa_{n+1}uxa_{n+1}$ and not of $vxa_{n+1}vxa_{n+1}$. Thus, $L_{n+1}/u \neq L_{n+1}/v$. \\

    If they both are from $\mathcal{F}_n a_{n+1}$. Let's write $u = u'a_{n+1}$ and $v = v'a_{n+1}$. There is $x'
    \in \Sigma^*$ such that $V_n$ is subword of $u'x'u'x'$ but not of $v'x'v'x'$ or the other way around. Thus $u_{n+1}$ is a subword of $u'x'a_{n+1}u'x'a_{n+1}$ but not of $v'x'a_{n+1}v'x'a_{n+1}$ as $V_n$ is not a subword of it and $V_n$ is a subword of $V_{n+1}$.\\

Let us consider $x\neq y \in a_{n+1}(\mathcal{F}_{n-1} \setminus \{ V_{n-1} \}) a_n$. Let us write $x$ and $y$ as $x = a_{n+1}x''a_n$ and $y = a_{n+1}y''a_n$. As $x'',y'' \in \mathcal{F}_{n-1}$, there exists $z \in \Sigma^*$ such that $x''zx''z \in \upc (V_{n-1})$ and $y''zy''z \notin \upc (V_{n-1})$. Thus $V_{n+1} \subword a_{n+1}x''a_nz a_n a_{n+1} a_{n+1}x''a_n z a_n a_{n+1}$ but $V_{n+1}$ is not a subword of $a_{n+1}y''a_n z a_n a_{n+1}a_{n+1}y''a_n za_n a_{n+1}$. Thus, $x$ and $y$ give different quotients. \\

If $x \in a_{n+1}(\mathcal{F}_{n-1} \setminus \{ V_{n-1} \}) a_n$ and $y \in \mathcal{F}_n $, as $x$ contains
$a_{n+1}$ but not $y$,  the proof of \Cref{prop-2-n-quotients} entails that their quotients are different. \\

If $x \in a_{n+1}(\mathcal{F}_{n-1} \setminus \{ V_{n-1} \}) a_n$ and $y \in \mathcal{F}_n a_{n+1}$, let us write $x = a_{n+1}x''a_n$ and $y = y'a_{n+1}$. 

As $x''a_n \in \mathcal{F}_n$, if $x''a_n \neq y'$, there exists $z \in \Sigma^*$ such that $x'zx'z \in \upc (V_n)$ and $y'zy'z \notin \upc (V_n)$ where $x' = x''a_n$, as $x'\neq y'$. Thus, $V_{n+1} \subword a_{n+1}x'za_{n+1} a_{n+1}x'za_{n+1} = (xza_{n+1})^2$ but $V_{n+1}$ is not a subword of $y'a_{n+1}za_{n+1}  y'a_{n+1}za_{n+1} = (yza_{n+1})^2$. Thus $x$ and $y$ give different quotients. \\

If $x' = y'$, then $x = a_{n+1}x''a_n$, the nice thing is that by taking $z = V_{n-1}$ we have $ V_n \subword x''a_n z x'' a_n = x' z x' $ which gives $V_{n+1} \subword x''a_n a_{n+1} z x'' a_n a_{n+1} = y z y $ but $V_{n+1}$ is not a subword of $xzx = a_{n+1} x''a_n  z a_{n+1} x'' a_n $, as long as $x'' \neq V_{n-1}$. Thus $x,y$ give different quotients. \\


Thus, $a_{n+1}(\mathcal{F}_{n-1}\setminus V_{n-1})a_n \bigcup \mathcal{F}_{n} \bigcup \mathcal{F}_{n}a_{n+1}$ is a dividing set for $\sqrt{\upc(V_{n+1})}$.
%
\qed    
\end{proof}

\begin{proposition}

	For $n \geq 1$,  $\kappa(\sqrt{\upc(V_{n})}) \geq (\frac{1}{\sqrt{2}}-\frac{1}{4})(\sqrt{2}+1)^n \approx 0.46 \times 2.41^n$.

\end{proposition}

\begin{proof}

Using \Cref{better_dividing_set_sqrt_down} we have that $a_{n+1}(\mathcal{F}_{n-1}\setminus V_{n-1})a_n \bigcup \mathcal{F}_{n} \bigcup \mathcal{F}_{n}a_{n+1}$ is a dividing set for $\sqrt{\upc(V_{n+1})}$. Thus for all $n \in \mathbb{N}_{>0}$ we can create dividing sets $\mathcal{F}_n$ of $\sqrt{\upc(V_{n})}$ verifying $|\mathcal{F}_{n+2}| \geq 2|\mathcal{F}_{n+1}| + |\mathcal{F}_{n}|-1$. \\

Let $v_n = |\mathcal{F}_n| - \frac{1}{2}$, we have the equation : $ v_{n+2} \geq 2v_{n+1} + v_n $. Thus $v_n \geq w_n$ where $w_0 = v_0=-\frac{1}{2}$, $w_1 = v_1=\frac{3}{2}$ and $ w_{n+2} = 2w_{n+1} + w_n  $. And using the formula for recurrent sequences of order $2$, we get $w_n = (\frac{1}{\sqrt{2}}-\frac{1}{4})(\sqrt{2}+1)^n - (\frac{1}{\sqrt{2}}+\frac{1}{4})(1 - \sqrt{2})^n$. Thus asymptotically, $w_n \sim (\frac{1}{\sqrt{2}}-\frac{1}{4})(\sqrt{2}+1)^n$ and  $|\mathcal{F}_n|\geq 0.46(2.41)^n$. In fact, by computing the first values and then using the asymptotic analysis, we get $|\mathcal{F}_n|\geq 0.46(2.41)^n$ for $n\geq 1$. 
%
\qed    
\end{proof}

\begin{definition}\label{cut_shuffle}
    For $w \in \Sigma^*$ we denote with $CS(w)$ the set $\bigcup_{w=tv} t \shuffle v$. This is the set of words obtained from $w$ by one ``cut and shuffle'' move. 
\end{definition}


\begin{proposition}\label{prop-minimal-sqrt-Ln}
    Let $V_n$ be a $n$-letter word of length $n$, $CS(V_n) = \{ \mbox{minimal words of } \sqrt{\upc (V_n)} \} $ and 
    $\upc (CS(V_n)) = \sqrt{\upc (V_n)}$.
\end{proposition}


\begin{proof}
    Let $u$ be a word that can be obtained by a cut and shuffle of $V_n$, $u \in t \shuffle v $ where $ V_n = tv$.

    Let us take $r = vt$, we have 
\[ 
u^2 \in ( t \shuffle v )( v \shuffle t ) \subseteq V_n \shuffle r \subseteq \upc(V_n)\:.
\] 

    Hence, $u \in \sqrt{\upc (V_n)}$, and as $\sqrt{\upc (V_n)}$ is upward closed,
    $\upc (CS(V_n)) \subseteq \sqrt{\upc (V_n)}$. \newline 

    Let $u \in \sqrt{\upc (V_n)}$ such that $|u| = n$, which implies that $u$ is minimal in $\sqrt{\upc (V_n)}$. We have $u^2 \in \upc (V_n)$. 
    Let us call $u_1$ the longest prefix of $V_n$ that is a subword of $u$. 
Then as $V_n$ us a subword of $u^2$, we have that the suffix $u_2$ such that $V_n = u_1u_2$ is a subword of $u$ too. Finally, as $|u| = |V_n| = |u_1| + |u_2|$ and $u_1,u_2$ have different letters, we have that $u \in u_1 \shuffle u_2$. 

Hence $u \in CS(V_n)$, and since any upward closed $L$ is $\bigcup_{u\text{ minimal in }L}\upc(u)$,
we get $ \upc (CS(V_n)) = \sqrt{\upc (V_n)}$.
%
\qed    
\end{proof}

\begin{proposition}\label{inversion_counting}
    Let $V_n=a_1a_2\cdots a_n$ be word of length $n$ where all letters are different. Then $|CS(V_n)| = 2^n -n$.
\end{proposition}

\begin{proof}
	It is quite easy to see that for $w = tv$ there are $\binom{|w|}{|t|}$ different words in $t \shuffle v$, but one of them is $w$. Thus $|CS(V_n)| = \sum_{0\leq |t| \leq n-1} \binom{n}{|t|} - (n-1) = 2^n -n$.
%
\qed    
\end{proof}



\section{Missing proofs on the substitution operator}

\begin{proposition}\label{substitution_automaton}

The substitution operator preserves regularity. 

\end{proposition}

\begin{proof}
We know this since we proved it preserves the closedness and upward closed/downward closed languages are regular languages, but this is an occasion to explain the classical construction of the automaton for the substitution, which might help to visualize better the situation.\\ 

Let us consider the classical construction for the substitution. Let us call $\mathcal{A}_L,\mathcal{A}_K$ the
automata for $L,K$. We modify $\mathcal{A}_L$ in the following way: For every transition $q \step{a} q'$ in
$\mathcal{A}_L$ that reads the
letter $a$, we insert a copy of $\mathcal{A}_K$ without final states, create an $\epsilon$-transition from $q$ to the
initial state of (that copy of) $\mathcal{A}_K$, and from each final state of  $\mathcal{A}_K$ we  add an
$\epsilon$-transitions to $q'$. Finally, we remove the original $q\step{a}q'$ transition,
determinize the resulting automaton, and obtain a DFA for the substitution $L^{a\leftarrow K}$. \\

In order to prove that the construction is correct, let us call $\mathcal{A}$ the automaton before the determinization, and let us show that $L(\mathcal{A}) =  L^{a \leftarrow K}$. Since the determinization process preserves the language, we would have the validity of the automaton. \\ 


Let $x \in L^{a \leftarrow K}$, there exists $x_L \in L$ such that  
$x_L = x_1 a x_2 ... x_{n-1} a x_n $ with $x_i \in \Sigma^*$ and $x = x_1 y1 x_2 ... x_{n-1} y_{n-1} x_n $ with $y_i \in K$. Let $q_0 , ... q_r $ be the path of $x_L$ in $\mathcal{A}_L$. Then by inserting the path for $y_i$ in $\mathcal{A}_K$ where there are transitions labeled $a$ we get a path for $x$ in $\mathcal{A}$ using the $\epsilon$-transitions. Thus $L^{a \leftarrow K} \subseteq L(\mathcal{A})$. \\

Let $x \in L(\mathcal{A})$ then by studying the path that $x$ follows in the automaton, we factorize $x$ under the form $x = x_1 y1 x_2 ... x_{n-1} y_{n-1} x_n $ with $x_i \in \Sigma^*$ and $y_i \in K$. Furthermore, the construction implies that $x_L = x_1 a x_2 ... x_{n-1} a x_n  \in L$ as we inserted $\mathcal{A}_K$ on edges labeled by $a$. Thus $L(\mathcal{A}) \subseteq L^{a \leftarrow K}$.  
%
\qed    
\end{proof}

\section{Missing proofs on iteration operator}

\begin{proposition}\label{borne_L_k}
In the case of $L$ upward closed, with state complexity $n$, the upper bound $k(n-1) + 1$ on the state complexity of $L^k$ is tight for $|\Sigma | \geq 1$.

\end{proposition}

\begin{proof}

First of all the bound $k(n-1) + 1$ corresponds to the concatenation upper bound applied $k$ times. Thus is it a valid upper bound for $L^k$. We now have to show that it is actually tight. \\

Let $L_n = \texttt{a}^{n-1} \texttt{a}^*$ be the language of words having at least $n-1$ \texttt{a}, this gives $L_n^k =\texttt{a}^{(n-1)k}\texttt{a}^*$. Let $w \in L_n$, and $x$ a word such that $w \subword x$, then $x$ has more \texttt{a}'s than $w$, implying $x \in L_n$. 
The quotients of $L_n$ are $\{ \texttt{a}^i\texttt{a}^* \ | \ 0 \leq i \leq n-1 \}$. Hence, $L_n$ has state complexity $n$. Finally, using the same idea, $L_n^k$ has state complexity $(n-1)k+1$. 
%
\qed    
\end{proof}





