%To obtain hash codes of users and items, we
\section{Model Optimization} \label{dsml-opt}
Due to the intractability of solving the objective \eqref{siml} with binary constraints imposed on $\mathbf{B}$ and $\mathbf{D}$, it's hard to find a closed form updates rule. Inspired by the new discrete optimization method \cite{zhang2018discrete}, we seek to minimize a variational quadratic upper bound of the objective of DSIML in Equation~\eqref{siml} based on \textit{JJ bound} \cite{jaakkola1997variational}. The upper bound of \textit{log-sum-exp} function is as follows
\begin{equation}\label{lse}
\log\big(1+e^{t}\big) \le \pi(\xi)(t^2 - \xi^2)+ \frac{1}{2} (t - \xi) + \log\big(1+e^{\xi}),
\end{equation}
where $\pi(\xi) = \frac{1}{2\xi}\big(\sigma(\xi) - \frac{1}{2}\big)$, $\sigma(x) = \frac{1}{1+e^{-x}}$ is a sigmoid function. we call $\xi$ as the variational parameter. It's evident that the upper bound is tight at $\xi=t$. By denoting $\hat{\ell}(t, \xi)=\pi(\xi)(t^2 - \xi^2)+ \frac{1}{2} (t - \xi) + \log\big(1+e^{\xi}\big)$, we derive the following upper bound of Equation~\eqref{siml},
\begin{equation}\label{scale_up}
\begin{aligned}
&\min_{\mathbf{B},\mathbf{D},\Phi,\mathcal{H}} \hat{\mathcal{L}}_{\tiny{dsiml}}=\sum_{(u,i,j)\in\Omega}\big(\hat{\ell}(x_{uij}, \varphi_{uij}) +\lambda \hat{\ell}(y_{uij}, \eta_{uij})\big),\\
&\text{s.t.} \ \ \mathbf{B}\in\{\pm 1\}^{n\times d},  \mathbf{D}\in\{\pm 1\}^{m\times d}, \Phi \in \mathbb{R}^{|\Omega|}, \mathcal{H} \in \mathbb{R}^{|\Omega|}.
\end{aligned}
\end{equation}
where $x_{uij}=\frac{1}{2d}(\mathbf{b}_{u}^{T}\mathbf{d}_{j} -\mathbf{b}_{u}^{T}\mathbf{d}_{i})$ is from Equation~\eqref{pair}, and $y_{uij}=2\gamma^{2}(\mathbf{b}_{u}^{T}\mathbf{d}_{j}+\mathbf{d}_{i}^{T}\mathbf{d}_{j})-(1+\gamma^2)\mathbf{b}_{u}^{T}\mathbf{d}_{i}$ is from Equation~\eqref{scale}. $\varphi_{uij}\in \Phi$ and $\eta_{uij}\in \mathcal{H}$ are the variational parameters.

To optimize the above mixed integer problem, we adopt an alternating optimization method, which is commonly applied in solving mixed integer problems \cite{zhang2016discrete, zhang2017discrete}. 
\paragraph{Updating users' hash codes $\mathbf{B}$.}
Given $\mathbf{D}$, $\Phi$, and $\mathcal{H}$, we update $\mathbf{b}_{u}$ of each user $u$ in parallel. By dropping irrelevant items to $\mathbf{b}_{u}$, the sub-problem is a binary quadratic problem (BQP) with respect to $\mathbf{b}_{u}$,
\begin{equation}\label{u-obj}
\min_{\mathbf{b}_{u}\{\pm 1\}^{d}} \mathbf{b}_{u}^{T}\mathbf{A}_{u} \mathbf{b}_{u}+ \mathbf{c}_{u}^{T}\mathbf{b}_{u},
\end{equation}
where  $\mathbf{A}_{u} = \mathbf{A}_{xu} + 4\lambda d^2 \mathbf{A}_{yu}$,  $\mathbf{c}_{u} = \mathbf{c}_{xu} + 4\lambda d^2 \mathbf{c}_{yu}$. $\mathbf{A}_{xu}$ and $\mathbf{c}_{xu}$ come from the loss $\hat{\ell}(x_{uij}, \varphi_{uij})$, and $\mathbf{A}_{yu}$ and $\mathbf{c}_{yu}$ come from the loss $\hat{\ell}(y_{uij}, \eta_{uij})$, and
\begin{align}\label{cdu}
\begin{cases}
\mathbf{A}_{xu}=&\sum_{(i,j)}\big( \mathbf{d}_{i}\mathbf{d}_{i}^{T}\pi(\varphi_{uij})+\mathbf{d}_{j}\mathbf{d}_{j}^{T}\pi(\varphi_{uij})-2\mathbf{d}_{j}\mathbf{d}_{i}^{T}\pi(\varphi_{uij})\big);  \\
\mathbf{A}_{yu}=&4\gamma^4\sum_{(i,j)}\big( 4(1+\gamma^2)^2\mathbf{d}_{i}\mathbf{d}_{i}^{T}\pi(\eta_{uij}) + \mathbf{d}_{j}\mathbf{d}_{j}^{T}\pi(\eta_{uij})- \\
&(1+\gamma^2)\mathbf{d}_{j}\mathbf{d}_{i}^{T}\pi(\eta_{uij})\big).  \\
\mathbf{c}_{xu}=&\sum_{(i,j)} d(\mathbf{d}_{j}-\mathbf{d}_{i}); \\
\mathbf{c}_{yu}=&\sum_{(i,j)} \big(4\gamma^4(\mathbf{d}_{i}^{T}\mathbf{d}_{j})\mathbf{d}_{j}\pi(\eta_{uij})- 8\gamma^4(1+\gamma^2)(\mathbf{d}_{i}^T\mathbf{d}_{j})\mathbf{d}_{i} + \\
&2\gamma^2\mathbf{d}_{j} - (1+\gamma^2)\mathbf{d}_{i}\big).
%\vspace{-10pt}
\end{cases}
\end{align}
Previous studies mainly apply the Discrete coordinate descent(DCD) \cite{Shen_2015_CVPR} method to learn hash codes in a bitwise way. As analyzed in DRMF  \cite{zhang2018discrete}, the discrete coordinate descent method easily falls into local optima and is very sensitive to the initialization of parameters. In contrast to discrete coordinate descent, we update the entire hash code ${{\mathbf{b}}_{u}}$ in each iteration by directly optimizing the BQP problem with the BQP solver \footnote{https://www.cvxpy.org}. In this paper, we choose the Xpress optimizer to optimize the above BQP problem by transferring hash codes $\mathbf{b}_{u} \in \{\pm 1\}^{d}$ to boolean vectors $\frac{1}{2}(\mathbf{b}_{u}+\mathbf{1}_{d})\in \{0,1\}^{d}$.

\paragraph{Updating items' hash codes $\mathbf{D}$.}
Similarly, given $\mathbf{B}$, $\Phi$, and $\mathcal{H}$, we update $\mathbf{d}_{j}$ of each item $j$ in parallel. By dropping irrelevant items to $\mathbf{d}_{j}$, the sub-problem is a binary quadratic problem (BQP) with respect to $\mathbf{d}_{j}$,
\begin{equation}\label{v-obj}
\min_{\mathbf{d}_{i}\{\pm 1\}^{d}} \mathbf{d}_{i}^{T}\mathbf{A}_{i} \mathbf{d}_{i}+ \mathbf{c}_{i}^{T}\mathbf{d}_{i},
\end{equation}
where  $\mathbf{A}_{i} = \mathbf{A}_{xi} + 4\lambda d^2 \mathbf{A}_{yi}$,  $\mathbf{c}_{i} = \mathbf{c}_{xi} + 4\lambda d^2 \mathbf{c}_{yi}$. Similarly, $\mathbf{A}_{xu}$ and $\mathbf{c}_{xu}$ come from the loss $\hat{\ell}(x_{uij}, \varphi_{uij})$, and $\mathbf{A}_{yu}$ and $\mathbf{c}_{yu}$ come from the loss $\hat{\ell}(y_{uij}, \eta_{uij})$, and 
\begin{align}\label{cdj}
\begin{cases}
\mathbf{A}_{xu}=&\sum_(u,j) \mathbf{b}_{u}\mathbf{b}_{u}^{T}\pi(\varphi_{uij}); \\
\mathbf{A}_{yj} = &\sum_(u,j)  \big(4\gamma^4\mathbf{d}_{j}\mathbf{d}_{j}^{T}\pi(\eta_{uij})+ (1+\gamma^2)^2 \mathbf{b}_{u}\mathbf{b}_{u}^{T}\pi(\eta_{uij}) - \\
&4\gamma^2(1+\gamma^2) \mathbf{d}_{j}\mathbf{b}_{u}^{T}\pi(\eta_{uij})  \big).\\
\mathbf{c}_{xi}=&\sum_{(u,i)} \big(-2(\mathbf{b}_{u}^{T}\mathbf{d}_{j})\mathbf{b}_{u}\pi(\varphi_{uij}) - d\mathbf{b}_{u} \big); \\
\mathbf{c}_{yu}=&\sum_{(u,j)} \big(4\gamma^4(\mathbf{b}_{u}^{T}\mathbf{d}_{j})\mathbf{d}_{j}\pi(\eta_{uij}) - \\ &2\gamma^2(1+\gamma^2)(\mathbf{b}_{u}^{T}\mathbf{d}_{j})\mathbf{b}_{u}\pi(\eta_{uij}) + 
2\gamma^2 \mathbf{d}_{j} - (1+\gamma^2) \mathbf{b}_{u} \big).
\end{cases}
\end{align}
Similarly, we optimize the above BQP with the assist of Xpress solver by transferring hash codes $\mathbf{d}_{i} \in \{\pm 1\}^{d}$ to boolean vectors $\frac{1}{2}(\mathbf{d}_{i}+\mathbf{1}_{d})\in \{0,1\}^{d}$.

\paragraph{Updating variational parameters $\Phi$.}
Given $\mathbf{B}$, $\mathbf{D}$, and $\mathcal{H}$, we obtain the following sub-objective of $\varphi_{uij}$ by discarding irrespective terms of $\varphi_{uij}$,
\begin{equation}\label{phi_obj}
\min_{\varphi_{uij}\in \mathbb{R}} \pi(\varphi_{uij})(x_{uij}^2 - \varphi_{uij}^2)+ \frac{1}{2} (x_{uij} - \varphi_{uij}) + \log\big(1+e^{\varphi_{uij}})
\end{equation}
The sub-problem \eqref{phi_obj} is convex since its second derivative is greater than zero. Hence, the optimal value is achieved when the derivation of Equation~\eqref{phi_obj} equals zero. For each user, the derivation of Equation~\eqref{phi_obj} equals zero at
\begin{equation}\label{phi}
{{\varphi}_{uij}}=x_{uij}=\frac{1}{2d}(\mathbf{b}_{u}^{T}\mathbf{d}_{j} -\mathbf{b}_{u}^{T}\mathbf{d}_{i})  
\end{equation}
In practical, we don't need store $\{{\varphi}_{uij}: \forall (u,i,j)\in \Omega\}$ in the training procedure. we only need to store all expressions $x_{uij}$ and then update ${{\varphi}_{uij}}$. we do also not need to store $\pi({{\varphi}_{uij}})$, since it can be computed on-the-fly in constant time when we cache these $x_{uij}$.

\paragraph{Updating variational parameters $\mathcal{H}$.}
Similarly, given $\mathbf{B}$, $\mathbf{D}$, and $\Phi$, we derive the following sub-problem of $\eta_{uij}$ by dropping irrelevant terms of $\eta_{uij}$ in Equation\eqref{phi_obj},
\begin{equation}\label{eta_obj}
\min_{\eta_{uij}\in \mathbb{R}} \pi(\eta_{uij})(y_{uij}^2 - \eta_{uij}^2)+ \frac{1}{2} (y_{uij} - \eta_{uij}) + \log\big(1+e^{\eta_{uij}})
\end{equation}
Similarly, the sub-objective \eqref{eta_obj} is convex and the optimal value is achieved when the derivation of Equation~ \eqref{eta_obj} equals to zero. For each user, the derivation of Equation~ \eqref{eta_obj} equals to zero at
\begin{equation}\label{eta}
{{\eta}_{uij}}=y_{uij}=2\gamma^{2}(\mathbf{b}_{u}^{T}\mathbf{d}_{i}+\mathbf{d}_{i}^{T}\mathbf{d}_{j})-(1+\gamma^2)\mathbf{b}_{u}^{T}\mathbf{d}_{i} 
\end{equation}
Similarly, we don't need store ${\eta}_{uij}$ and $\pi({{\eta}_{uij}})$, and we only need to store all expressions $y_{uij}$ and then update ${{\eta}_{uij}}$ and $\pi({{\eta}_{uij}})$ with these $y_{uij}$. Finally, we summarize the optimization steps in Algorithm \ref{alg:dsml}. 

\begin{algorithm}
	\KwIn{User-item implicit feedback $\mathcal{S}$, dimension $d=20$, $\gamma=1$, $\lambda=1$.}
	\KwOut{Hash codes of users and items $\mathbf{B}$ and $\mathbf{D}$.}
	%\caption{Discrete Ranking-based Matrix Factorization (DRMF)\label{alg:drmf}} % $\mathbf{P},{Q}\leftarrow$DRMF($\mathbf{R}, \mathbf{w}, \mathbf{P}_0,\mathbf{Q}_0$)}
	\caption{$\text{DSIML}$}\label{alg:dsml} % $\mathbf{P},\mathbf{Q}\leftarrow$DRMF($\mathbf{R}, \mathbf{w}, \mathbf{P}_0,\mathbf{Q}_0$)}
	\textbf{Initialize:} Firstly we learn continuous vectors $\mathbf{U}$ and $\mathbf{V}$ by solving Equation~ \eqref{siml} without binary constraints, then we initialize $\mathbf{B}\leftarrow sign(\mathbf{U})$, $\mathbf{D}\leftarrow sign(\mathbf{V})$,
	$\Phi \leftarrow Equation~\eqref{phi}$, $\mathcal{H} \leftarrow Equation~\eqref{eta}$\;
	%$\mathbf{w} = \mathbf{1}^{|S|}$\;
	\Repeat{$\mathcal{L}_{dsml}$ is convergent}	
	{	
		\For{$i \in \{1,\cdots, n\}$}
		{
			\For{$j \in \mathcal{I}_{u}^{+}$ and $k \in I_{u}^{-}$}{
				Compute $\varphi_{uij}$ by Equation~\eqref{phi} \; 
			}
			Update $\mathbf{b}_u$ by sloving the objective \eqref{u-obj} by Xpress solver\;
		}

		\For{$i\in \{1,\cdots,m\}$}
		{
			\For{$u \in \mathcal{U}_{i}^{+}$ and $k \in I_{u}^{-}$}{
				Compute $\eta_{uij}$ by Equation~\eqref{eta}  \; 
			}
			Update $\mathbf{d}_i$ by sloving the objective \eqref{v-obj} by Xpress solver\;
		}
	}
\end{algorithm}

In the training stage, we optimize the objective \eqref{siml} by a mini-batch containing multiple triplets from the same users. Specifically, we divide triplets, w.r.t users. Suppose the batch size is 16, we train the proposed model on all triplets of 16 users. In training, we optimize user by user, i.e., we train the proposed model in the way of N-pair sampling \cite{sohn2016improved}. It considers an ($N+1$)-tuplet of training examples $\{u, i, j_{1}, j_{2}, \dots, j_{N-1}\}$ by sampling $N-1$ negative samples for each positive feedback $s_{ij}=1$. As evaluated in NCF \cite{he2017neural}, the recommender system can achieve good performance when we randomly sample four to eight negative samples for each positive feedback. So in this Chapter, we sample five negative samples for each positive item to train the proposed model.
