  \arrow[d] \arrow[u] & \Hdiv \arrow[r, "\div"] \arrow[u] \arrow[d] & \Ltwo \arrow[u] \arrow[d] \\
   \CG_p \arrow[r, "\grad"] & \NedTwo_{p-1} \arrow[r, "\curl"] & 
