		\CG_p \arrow[r, "\grad"] & \Ned_p \arrow[r, "\curl"] & 
		\BDM_{p-1} \arrow[r, "\div"] & \DG_{p-2} \\
		%
		\CG_p \arrow[r, "\grad"] & \NedTwo_{p-1} \arrow[r, "\curl"] & 
