\section{Properties of the global basis functions}

Continuing with the notation from the previous sections, we let $X^k$ denote the 
global discrete space $X^{k}_{p, D}(\mesh)$.
The global basis for $X^k$ is constructed from the local basis on $X^k(\That)$ as 
in \cite{Rognes2010efficient}. In particular, for each element $T \in \mesh$, the 
bijective mapping $F_T : \That \to T$  is chosen to preserve fixed global 
orientations of 
subsimplices, and each global basis function supported on $T$ is of the form 
$\pullback_T^k(\hat{\phi})$, where $\{ \hat{\phi} \}$ is a basis for $X^k(\That)$ and 
$\pullback_T^k$ is defined in \cref{eq:pullback-3d-def}. For the remainder of the 
manuscript, we will assume that $F_T$ is chosen in this way. Boundary conditions 
are then enforced by removing all functions associated to subsimplices $S \in 
\Delta_{l}(\mesh)$, $l \in k:d-1$, laying on $\Gamma_D$.



\subsection{Key subspaces}



For $k \in 0:d-1$ and each subsimplex $S \in \Delta_l(\mesh)$, $l \in k:d$, let 
$\{ \phi_{S, j}^{k, \rmone} \}$ and $\{ \phi_{S, n}^{k, \rmtwo} \}$ denote the 
corresponding global basis functions associated to $S$. We collect a number of 
subspaces related to the basis functions. First, we separate the subspaces 
corresponding to the type-$\rmone$ basis functions into the Whitney forms, the 
high-order interface bubble functions, and the interior functions supported on 
one element: 
\begin{subequations}
	\label{eq:global-spaces-typeI}
	\begin{align}
		W^k &:= \spn\left\{ \phi_{S, 1}^{k, \rmone} : \ S \in 
		\Delta_k(\mesh), \ \tr_{\Gamma_D}^k \phi_{S, 1}^{k, \rmone} = 0 \right\}, 
		\\
		%
		\mathring{X}^{k, \rmone}_{\interface} &:= \spn\left\{ \phi_{S, 
			j}^{k, 
			\rmone} : S \in \bigcup_{l=k+1}^{d-1} 
			\Delta_l(\mesh), \ j \in 1:N^k_{S}, \ \tr_{\Gamma_D}^k \phi_{S, 
			j}^{k, \rmone} = 0 	\right\}, \\
		%
		\mathring{X}^{k, \rmone}_{\interior} &:= \spn\left\{ \phi_{T, 
		j}^{k, 
			\rmone} : \ \forall T \in \Delta_d(\mesh), \ j \in 1:N^k_{T} 
		\right\}, \\
		%
		\label{eq:global-space-typeI}
		X^{k, \rmone} &:= W^k \oplus \mathring{X}^{k, \rmone}_{\interface} \oplus 
		\mathring{X}^{k, \rmone}_{\interior},
	\end{align}
\end{subequations}
where spaces with the ``$\mathring{\phantom{n}}$" overset vanish on $S \in \Delta_k(\mesh)$.
Similarly, we separate the type-$\rmtwo$ subspaces:
\begin{subequations}
	\label{eq:global-spaces-typeII}
	\begin{align}
		X^{k, \rmtwo}_{\interface} &:= \spn\left\{ \phi_{S, 
		j}^{k, \rmtwo} : S \in \bigcup_{l=k}^{d-1} \Delta_l(\mesh), \ j \in 
		1:N^{k-1}_{S}, \tr_{\Gamma_D}^k \phi_{S, j}^{k, \rmtwo} = 0 \right\}, \\
		%
		\mathring{X}^{k, \rmtwo}_{\interior} &:= \spn\left\{ \phi_{T, 
			j}^{k, \rmtwo} : \forall T \in \Delta_d(\mesh), \ j \in 1:N^{k-1}_{T} 
		\right\}, \\
		%
		X^{k, \rmtwo} &:= X^{k, \rmtwo}_{\interface} \oplus 
		\mathring{X}^{k, \rmtwo}_{\interior}.
	\end{align}
\end{subequations}


By construction, the type-$\rmone$ and type-$\rmtwo$ spaces decompose $X^k$:
\begin{align} \label{eq:typeI-typeII-direct-sum}
	X^{k} = X^{k, \rmone} \oplus X^{k, \rmtwo}.
\end{align}
% TODO change k to k-1
Moreover, since $\d^k \mathcal{F}_T^k(\phi) = \mathcal{F}_T^{k+1}(\d^k \phi)$, we 
also have the global analogue of \cref{lem:d-preserves-basis-functions} for 
$k \in 1:d-1$:
\begin{align}
	\label{eq:d-preserves-basis-functions-global}
	\phi_{S, n}^{k, \rmtwo} = \d^{k-1} \phi_{S, n}^{k-1, \rmone} \qquad 
	\Forall S \in \bigcup_{l=k}^{d} \Delta_l(\mesh), \ \Forall n \in 
	1:N_S^{k-1}.
\end{align}



\subsection{Decomposing the range and kernel of $\d^k$}

We now decompose the range of kernel of $\d^k$ using the subspaces defined above. 
The first result shows that the image of $\d^k$ acting on the high-order 
type-$\rmone$ spaces is disjoint from $\d^k W^k$.

\begin{lemma}
	\label{lem:image-type-one-bubble-disjoint-whitney}
	For $k \in 0:d-1$, if $u \in \mathring{X}^{k, \rmone}_{\interface} \oplus 
	\mathring{X}^{k, \rmone}_{\interior}$ satisfies $\d^k u \in \d^k 
	W^k$, then $u \equiv 0$. Consequently, $\d^k (\mathring{X}^{k, 
	\rmone}_{\interface} \oplus \mathring{X}^{k, \rmone}_{\interior}) \cap \d^k 
	W^k 
	= \{0\}$.
\end{lemma}
\begin{proof}
	Let $v \in \mathring{X}^{k, \rmone}_{\interface} \oplus \mathring{X}^{k, 
	\rmone}_{\interior}$ and $w \in W^k$ satisfy $\d^k v = \d^k w$.
	%	
	Let $T \in \mesh$, $\hat{v} \in \mathring{X}^{k, 
	\rmone}_{\interface}(\That)$, and 
	$\hat{w} \in W^{k}(\That)$ be such that $v|_{T} = \pullback^k_T(\hat{v})$
	and $w|_{T} = \pullback^k_T(\hat{w})$, where $\mathring{X}^{k, 
	\rmone}_{\interface}(\That)$, etc. denotes the spans of the corresponding 
	basis functions on the reference element. 
	%
	Since 
	\begin{align*}
 	\pullback^{k+1}_T (\d^k \hat{w}) = \d^k w|_{T} = \d^k v|_{T} =  
 	\pullback^{k+1}_T (\d^k \hat{v})
	\end{align*}
	and $\pullback^{k+1}_T$ is invertible, there holds $\d^k \hat{w} = \d^k 
	\hat{v}$.
	%
	However, for $S \in \Delta_l(\That)$, $l \in k+1:d$, and $j \in 1:N_S^k$, 
	there holds
	\begin{align*}
		(\d^k_S, \psi_{S, j}, \d^k_S \tr_S^k \hat{v})_S = (\d^k_S, \psi_{S, j}, 
		\tr_S^{k+1} \d^k \hat{v})_S &= (\d^k_S, \psi_{S, j}, \tr_S^{k+1} \d^k 
		\hat{w})_S \\
		&= (\d^k_S, \psi_{S, j}, \d^k_S \tr_S^k \hat{w})_S = 0
	\end{align*}
	by \cref{lem:basis-contains-whitney}. Thus,	
	\begin{align*}
		\hat{v} &= \sum_{l=k+1}^{d} \sum_{S \in \Delta_l(\That)} 
		\sum_{j=1}^{N_S^k} (\d^k_S, \psi_{S, j}, \d^k_S \tr_S^k \hat{v})_S 
		\phi_{S, 
		j}^{k, \rmone} = 0 \implies v \equiv 0.
	\end{align*}
\end{proof}

The next result shows the kernel of $\d^k$ consists of a low-order 
component from the Whitney forms plus the (high-order) type-$\rmtwo$ space, while 
the image of $\d^k$ also contains a low-order component from the Whitney forms 
and a component from the high-order type-$\rmone$ space.
\begin{lemma} \label{lem:kernel-image-dk-global-splitting}
	For $k \in 0:d-1$, there holds
	\begin{align}
		\label{eq:dk-kernel-decomp}
		\begin{aligned}
				\ker(\d^k; X^k) &= X^{k, \rmtwo}_{\interface} \oplus 
			\mathring{X}^{k, \rmtwo}_{\interior} \oplus 
			\ker(\d^k; W^k) \\
			&= \d^{k-1} \mathring{X}^{k-1, \rmone}_{\interface} 
			\oplus 
			\d^{k-1} \mathring{X}^{k-1, \rmone}_{\interior} \oplus \d^{k-1} 
			W^{k-1} \oplus \mathfrak{H}^{k},
		\end{aligned}
	\end{align}
	where $\mathfrak{H}^{k}$ denote the space of lowest-order harmonic forms:
	\begin{align} \label{eq:harmonic-forms}
		\mathfrak{H}^{k} := \{ \mathfrak{h} \in \ker(\d^k; W^k) : (\mathfrak{h}, 
		\d^{k-1} w) = 0 \ \Forall w \in W^{k-1} \}.
	\end{align}
	Moreover, there holds
	\begin{align} \label{eq:dk-image-decomp}
		\d^k X^k &= \d^k \mathring{X}^{k, \rmone}_{\interface} \oplus \d^k 
		\mathring{X}^{k, \rmone}_{\interior} \oplus \d^k W^k.
	\end{align}
\end{lemma}
\begin{proof}
	\noindent \textbf{Step 1: \cref{eq:dk-kernel-decomp}. } Thanks to 
	\cref{eq:d-preserves-basis-functions-global}, $X^{k, 
      \rmtwo}_{\interface} = \d^{k-1} \mathring{X}^{k-1, \rmone}_{\interface}$ 
		and $\mathring{X}^{k, \rmtwo}_{\interior} = \d^{k-1} \mathring{X}^{k-1, 
		\rmone}_{\interior}$, and so $X^{k, \rmtwo}_{\interface} 
		\oplus 
	\mathring{X}^{k, \rmtwo}_{\interior} \subset \ker(\d^k; X^k)$. 

	Now suppose that $u \in 
	\ker(\d^k; X^k)$. Then, $u = u_{\rmone} + u_{\rmtwo} + w$, where 
	$u_{\rmone} \in \mathring{X}^{k, \rmone}_{\interface} \oplus 
	\mathring{X}^{k, \rmone}_{\interior}$, 
	$u_{\rmtwo} \in X^{k, \rmtwo}_{\interface} \oplus 
	\mathring{X}^{k, \rmtwo}_{\interior}$, and $w \in W^k$. 
	Then,
	\begin{align*}
		0 = \d^k u = \d^k u_{\rmone} + \d^k u_{\rmtwo} + 
		\d^k w = \d^k u_{\rmone} + \d^k w,
	\end{align*}
	and so $\d^k u_{\rmone} \in \d^k W^k$.  By 
	\cref{lem:image-type-one-bubble-disjoint-whitney}, $u_{\rmone} \equiv 0$, 
	and so $\d^k w \equiv 0$. \Cref{eq:dk-kernel-decomp} now follows.

	 \noindent \textbf{Step 2: \cref{eq:dk-image-decomp}. } Thanks to Step 1 and 
	 \cref{lem:image-type-one-bubble-disjoint-whitney}, we have $\d^k X^k = \d^k 
	 \mathring{X}^{k, \rmone}_{\interface} \oplus \d^k \mathring{X}^{k, 
	 \rmone}_{\interior} \oplus \d^k W^k$, and so it suffices to show that $\d^k 
	 \mathring{X}^{k, \rmone}_{\interface} \cap \d^k \mathring{X}^{k, 
	 \rmone}_{\interior} 
	 = \{0\}$. 
	 Let  $u_{\interface} \in \mathring{X}^{k, \rmone}_{\interface}$ and 
	 $u_{\mathcal{I}} \in   
	 \mathring{X}^{k, \rmone}_{\interior}$ satisfy $\d^k (u_{\interface} -
	 u_{\mathcal{I}}) = 0$. By \cref{lem:image-type-one-bubble-disjoint-whitney}, 
	 $u_{\interface} = u_{\mathcal{I}}$, and so $u_{\interface} = u_{\mathcal{I}} = 0$.
\end{proof}


\subsection{Matrix properties on a physical cell}


Let $T \in \mesh$ and consider the local matrix $A$ corresponding to the 
restriction of $a^k(\cdot,\cdot)$ \cref{eq:weak-form} to the cell $T$:
\begin{align*}
	A_{ij} = (\phi_i, \beta \phi_j)_T + (\d^k \phi_i, \alpha \d^k \phi_j)_T, 
	\qquad i, j \in 1:\dim X^k(T),
\end{align*}
where $\{ \phi_i \}$ consists of all global basis functions supported on $T$. As 
in \cref{sec:reference-matrix-properties}, we partition $A$ into the contribution 
from interior and interface basis functions:
\begin{align*}
	A = \begin{bmatrix}
		A_{\interior \interior} & A_{\interior \interface} \\
		A_{\interface \interior} & A_{\interface \interface}
	\end{bmatrix}.
\end{align*}
If $T$ is an equilateral simplex, then \cref{lem:ref-element-matrix-properties} 
shows that $A_{\interior \interior}$ is diagonal and that the $A_{\interior 
\interface}$ and $A_{\interface \interior}$ blocks only contain a mass term. This 
structure is lost if $T$ is not an equilateral simplex due to the mapping 
$\pullback_T^k$. However, both the coupling and the mass terms only introduce 
weak coupling in the sense that if we define
\begin{align*}
	P := \begin{bmatrix}
		\diag(A_{\interior \interior}) & 0 \\
		0 & A_{\interface \interface}
	\end{bmatrix},
\end{align*} 
then $P$ is spectrally equivalent to $A$, as the following 
result quantifies.
\begin{lemma} \label{lem:physical-element-decouple}
	For $k \in 0:d-1$ and $T \in \mesh$, there exists a constant $C > 0$ 
	depending only on shape regularity, $d$, $k$, and $\mathrm{diam}(\Omega)$ 
	such that
	\begin{align}
		\label{eq:physical-element-decouple}
		\kappa_2\left(P^{-1} A \right) \leq C \max\left\{ 1, 
		\frac{\beta}{\alpha} h_T^2\right\}
	\end{align}
	where $\kappa_2(\cdot)$ denotes the condition number with respect to the 
	2-norm.
\end{lemma}
The proof of \cref{lem:physical-element-decouple} appears in 
\cref{sec:proof-physical-element-decouple}.

Provided that $\beta/\alpha$ is not too large, 
\cref{eq:physical-element-decouple} suggests that we may construct efficient 
preconditioners from existing ones by dropping the interior-interface coupling 
and by using a point-Jacobi (diagonal scaling) preconditioner on the interior 
basis functions. We combine this strategy with space decomposition 
preconditioners in the next section.



\section{Preconditioning} \label{sec:preconditioning}


In this section, we propose preconditioners for the Riesz maps  
\cref{eq:hgrad,eq:hcurl,eq:hdiv}. We describe our preconditioners in terms of 
space decompositions~\cite{ToWi06,xu92}. To capitalize on the weak coupling 
between 
interior and interface functions described in 
\cref{lem:physical-element-decouple}, we group the global interior and global 
interface functions together in their own subspaces:
\begin{align}
	\label{eq:global-space-interior-interface}
	X^{k}_{\interior} &:= \mathring{X}^{k, \rmone}_{\interior} 
	\oplus \mathring{X}^{k, \rmtwo}_{\interior} \quad \text{and} \quad 	
	X^k_{\interface} := W^k \oplus \mathring{X}^{k, \rmone}_{\interface} \oplus 
	X^{k, \rmtwo}_{\interface}.
\end{align}
\noindent We also collect all $N^k_{\interior} := \dim 
X^k_{\interior}$ interior basis functions $\{ 
\phi_{\interior, \ell}^{k} :  \ell \in 1:N^k_{\interior} \}$.


To illustrate how the interior/interface decoupling strategy 
in \cref{lem:physical-element-decouple} may be applied to arbitrary space 
decompositions of $X^k$, we present the corresponding result for Schwarz 
methods with exact solvers. To this end, let $\{X_m^k\}_{m=1}^{M}$ be a subspace 
decomposition of $X^k$:
\begin{align} \label{eq:abstract-space-decomp}
	X^k = \sum_{m=1}^{M} X_m^k, \qquad \text{where} \quad  X_m \subseteq X^k 
	\quad 
	\forall m \in 1:M,
\end{align}
where each space is equipped with the $a^k(\cdot,\cdot)$ inner product. 
Then, we may decouple the interior and interface functions to arrive at the finer 
decomposition
\begin{align} \label{eq:abstract-space-decomp-split-all-interior}
	X^k = \sum_{m=1}^{M} X^k_m \cap X^k_{\interface} + X^k_{\interior},
\end{align}
where $X^k_m \cap X^k_{\interface}$ is equipped with $a^k(\cdot,\cdot)$ for $m 
\in 1:M$ and $X^k_{\interior}$ is equipped with a point-Jacobi solver
\begin{align*}
	a_{\interior}^k(u,v) := \sum_{\ell=1}^{N^k_{\interior}} a^k( u_{\ell}, 
	v_{\ell} ) 
	\qquad \forall u, v \in X^k_{\interior},
\end{align*}
where $u = \sum_{\ell=1}^{N^k_{\ell}} u_{\ell}$ with $u_{\ell} \in \spn\{ 
\phi^k_{\ell} \}$ and similar notation for $v$. Note that the decomposition 
\cref{eq:abstract-space-decomp-split-all-interior} and associated bilinear forms 
is equivalent to the decomposition
\begin{align} \label{eq:abstract-space-decomp-split}
	X^k = \sum_{m=1}^{M} X^k_m \cap X^k_{\interface} + 
	\sum_{\ell=1}^{N^k_{\interior}} \spn\{ \phi^k_{\ell} \},
\end{align}
where each space is equipped with $a^k(\cdot,\cdot)$; we will use 
\cref{eq:abstract-space-decomp-split-all-interior} and 
\cref{eq:abstract-space-decomp-split} interchangeably. Then, the following 
result shows that the interior/interface splitting is, up to a constant 
independent of $h$, $p$, $\alpha$, and $\beta$, as stable as the original 
decomposition \cref{eq:abstract-space-decomp} provided that $\beta h^2 / \alpha 
\leq 1$:
\begin{theorem} \label{thm:generic-subspace-decomp-interface-interior-split}
	Suppose that the decomposition \cref{eq:abstract-space-decomp} is energy 
	stable: For every $u \in X^k$, 
	there exists $u_m \in X^k_m$, $m \in 1:M$ such that
	\begin{align} \label{eq:stable-decomposition-assumption}
		\sum_{m=1}^{M} u_m = u \quad \text{and} \quad \sum_{m=1}^{M} 
		a^k(u_m, u_m) 
		&\leq C_{\mathrm{stable}}(\alpha, \beta) a^k(u,u),
	\end{align}
	where $C_{\mathrm{stable}}(\alpha, \beta) \geq 1$ is independent of $u$.
	Then, the decomposition \cref{eq:abstract-space-decomp-split} is also energy 
	stable: For every $u \in X^k$, there exists $u_m 
	\in X^k_m \cap X^k_{\interface}$, $m \in 1:M$, and $u_{\interior} \in 
	X^k_{\interior}$, such that
	\begin{subequations} \label{eq:abstract-space-decomp-split-stable}
		\begin{align}
			\sum_{m=1}^{M} u_m + u_{\interior} &= u, \\
			%
			\sum_{m=1}^{M} 
			a^k(u_m, u_m) + a^k_{\interior}(u_{\interior}, u_{\interior})  
			&\leq C C_{\mathrm{stable}}(\alpha, \beta) \max\left\{ 1, 
			\frac{\beta}{\alpha} h^2 \right\} a(u, u),
		\end{align}
	\end{subequations}
	where $C$ depends only on shape regularity, $d$, and $k$. Moreover, 
	$a^k_{\interior}(\cdot,\cdot)$ is locally stable:
	\begin{align} \label{eq:abstract-space-decomp-interior-stability}
		a^k(v, v) \leq C a_{\interior}^k(v, v)  \qquad \forall v \in 
		X^k_{\interior}.
	\end{align}
\end{theorem}
The proof of \cref{thm:generic-subspace-decomp-interface-interior-split} appears 
in \cref{sec:proof-generic-subspace-decomp-interface-interior-split}. 


One can apply \cref{thm:generic-subspace-decomp-interface-interior-split} to 
obtain condition number bounds on Schwarz methods associated to the subspace 
decomposition \cref{eq:abstract-space-decomp-split}, where the spaces are 
equipped with the solvers described above. For example, if the subspaces 
$\{X_m^k\}_{m=1}^{M}$ can be colored with $N_{\mathrm{color}}$ 
colors, then $\{X_m^k \cap X^k_{\interface}\}_{m=1}^{M}$ and 
$X^k_{\interior}$ can be be colored with $N_{\mathrm{color}}+1$ 
colors. Thanks to \cref{eq:abstract-space-decomp-split-stable}, 
\cref{eq:abstract-space-decomp-interior-stability}, and standard theory 
\cite[Theorem 2.7]{ToWi06}, the additive Schwarz preconditioner $P^{-1}$ 
associated to the subspace decomposition 
\cref{eq:abstract-space-decomp-split} satisfies
\begin{align*} %\label{eq:generic-subspace-decomp-interface-interior-split-cn}
	\kappa_2( P^{-1} A ) \leq C C_{\mathrm{stable}}(\alpha, \beta) 
	(N_{\mathrm{color}} + 1) 
	\max\left\{1, \frac{\beta}{\alpha} h^2 \right\},
\end{align*}
where $C$ depends only on shape regularity, $d$, and $k$. Similar results can be 
obtained for multiplicative and hybrid methods.




Note that a Schwarz method associated to the decomposition 
\cref{eq:abstract-space-decomp-split} is computationally cheaper than the Schwarz 
method associated to the original decomposition \cref{eq:abstract-space-decomp}, 
as the interior and interface functions are completely decoupled and a 
point-Jacobi preconditioner is employed on the interior basis functions. 
Decoupling the interior and interface functions is reminiscent of static 
condensation in which the $\mathcal{O}(p^3)$ interior degrees of freedom are 
exactly eliminated from the global system at a cost of $\mathcal{O}(p^9)$ 
operations, and problem is reformulated only on the interface degrees of freedom. 
The key advantage of the decomposition \cref{eq:abstract-space-decomp-split} is 
that we retain the decoupling of the interior and interface functions 
\textit{without actually performing static condensation}, and we only require a 
point-Jacobi preconditioner for the interior degrees of freedom. We now turn to 
specific space decompositions.

\subsection{Pavarino--Arnold--Falk--Winther decompositions} 

% TODO PAFW_0

To start, we consider the Pavarino--Arnold--Falk--Winther (PAFW) 
decomposition~\cite{pavarino93,arnold00,zaglmayr06,Schoberl08,brubeck24}. The
decomposition for $k$-forms is given by
\begin{equation} \label{eq:pafw}
	X^k = W^k
	+ \sum_{V\in \Delta_0(\mesh)} \left. X^k \right|_{\star V},
\end{equation}
which consists of two components. The first summand is the lowest-degree 
space and plays the role of the coarse grid, propagating coarse-scale information 
globally. The second summand restricts the fine space to small subspaces, each 
supported on the \emph{star} of a vertex $\star V$, where $V \in \Delta_0(\mesh)$ 
is a vertex of the mesh. The star operation is well-known in algebraic 
topology~\cite[\S 2]{munkres84}\cite{egorova09,pcpatch}; it gathers all entities 
that contain the given entity as a subentity. In particular, the star of a vertex 
returns all cells, faces, and edges that are adjacent to this vertex, as well as 
the vertex itself, and functions in $\left. X^k \right|_{\star V}$ have vanishing 
trace on $\partial (\star V)$. This second summand plays the role of a multigrid 
relaxation, or the subdomain solves in a domain decomposition solver. 

We denote the decomposition \cref{eq:pafw} by $\pafw{0}{X^k}$ to indicate that 
the 
space in the summation is $X^k$ restricted to the star of a 0-dimensional 
subsimplex. The decomposition satisfies the hypothesis of 
\cref{thm:generic-subspace-decomp-interface-interior-split} with 
$C_{\mathrm{stable}}$ independent of $\alpha$, $\beta$, 
$h$, and $p$ \cite{Falk2025local}. However, on a regular (Freudenthal 
\cite{Bey00}) mesh, an interior vertex star contains 14 edges, 36 faces, and  
24 cells, and the vertex-star patch problems become very expensive to solve, 
particularly at high order. Thus, we employ 
the subspace splitting in \cref{eq:abstract-space-decomp-split}:
\begin{align}\label{eq:approx-sc-pafw}
	X^k = W^k + \sum_{V\in \Delta_0(\mesh)} \left. X^k_{\interface} \right|_{\star V} 
	+   
	\sum_{\ell=1}^{N^k_{\interior}} \spn\left\{ \phi_{\ell}^{k} 
	\right\},
\end{align}
which we refer to as $\pafw{0}{X^k_{\interface}}+\jacobi{X^k_{\interior}}$, where 
$\jacobi{X^k_{\interior}}$ indicates that a point-Jacobi preconditioner is 
employed on 
the space of interior forms.
\cref{thm:generic-subspace-decomp-interface-interior-split} shows that the decomposition \cref{eq:approx-sc-pafw} is also uniformly stable with respect to $h$ and $p$ 
and stable in $\alpha$ and $\beta$ provided that the ratio $\beta h^2/\alpha$ is bounded. 
Crucially, the dimension of the vertex-star problems scales like 
$\mathcal{O}(p^{d-1})$ for \cref{eq:approx-sc-pafw}, while it scales like  
$\mathcal{O}(p^d)$ for \cref{eq:pafw}. 
In particular, at degree $p=4$ and $p=10$, 
the vertex star $\left. X^{0}\right|_{\star V}$ has dimension 175 and 3439, 
respectively, while $\left. X_{\interface}^{0}\right|_{\star V}$ has dimension 
151 and 1423, respectively. 





\subsection{Pavarino--Hiptmair space decompositions}


For $k > 0$, finer space decompositions are possible and more efficient. Arnold, 
Falk \& Winther \cite{arnold00} prove that one can employ stars over entities of 
dimension $k-1$ 
instead of dimension 0~, with the resulting patches being much 
smaller for $k > 1$. Furthermore, as observed by Hiptmair and 
Toselli~\cite{hiptmair97,hiptmair98,hiptmair00}, one can even use stars over 
entities of dimension $k$ by 
introducing a potential space. This approach splits $X^k$ as the sum of 
the 
image of the exterior derivative $\d^{k-1}$ on a potential space $Y^{k-1}$, and 
some other space $Z^k \subset X^k$:
\begin{equation} \label{eq:hiptmair-abstract}
	X^k = \d^{k-1} Y^{k-1} + Z^k.
\end{equation}
The challenge here is to choose $Y^{k-1}$ and $Z^k$ 
as small as possible;
e.g. excluding as much of the kernel of $\d^{k-1}$ as possible from $Y^{k-1}$ and 
as much of the kernel of $\d^k$ from $Z^k$. 

\subsubsection{Standard Pavarino--Hiptmair decomposition}

The largest choice $Y^{k-1} = X^{k-1}$ and $Z^k = X^k$ motivates
the Pavarino--Hiptmair space decomposition
\begin{equation} \label{eq:pavarino_hiptmair}
	X^k = W^k + \sum_{J \in \Delta_{k-1}(\mesh)} \left.\d^{k-1} 
	X^{k-1}\right|_{\star J} + \sum_{L \in \Delta_{k}(\mesh)} \left. 
	X^{k} \right|_{\star L},
\end{equation}
where introducing the potential space in \cref{eq:hiptmair-abstract} enables the 
splitting over stars of dimension $k-1$ and $k$, respectively. We denote this 
decomposition by $\ph{X^{k-1}}{X^k}$ to indicate that potential space is 
$X^{k-1}$ and that the $k$-dimensional stars are taken over $X^k$. As shown in \cite{hiptmair97,hiptmair98,hiptmair00}, the $\ph{X^{k-1}}{X^k}$ decomposition satisfies the 
hypothesis of \cref{thm:generic-subspace-decomp-interface-interior-split} with 
$C_{\mathrm{stable}}$ independent of $h$, $\alpha$, and $\beta$. As before, the 
$\ph{X^{k-1}}{X^k}$  
decomposition can be combined with 
\cref{thm:generic-subspace-decomp-interface-interior-split}, 
yielding the 
$\ph{X^{k-1}_{\interface}}{X^k_{\interface}}+\jacobi{X^k_{\interior}}$ 
decomposition. 


Note that the $\ph{X^{k-1}}{X^k}$ decomposition involves an auxiliary
problem on the local potential space $X^{k-1}|_{\star J}$:
find $\psi \in X^{k-1}|_{\star J}$ such that
\begin{equation} \label{eq:local-potential-problem}
	a^k(\d^{k-1} \phi, \d^{k-1} \psi) = 
	(\d^{k-1} \phi, \beta\d^{k-1} \psi)_{\star J} = F(\d^{k-1} \phi) 
	\quad \Forall \phi \in \left.X^{k-1}\right|_{\star J},
\end{equation}
since $\d^k \circ \d^{k-1} = 0$. For $k > 1$, \cref{eq:local-potential-problem} 
is singular since $\d^{k-2} X^{k-2} \subset \ker(\d^{k-1}; X^{k-1})$. To address this,
a pragmatic choice is to solve the regularized problem
\begin{equation} \label{eq:local-potential-problem-added-mass}
	 (\phi, \epsilon \psi)_{\star J} +
	(\d^{k-1} \phi, \beta\d^{k-1} \psi)_{\star J} = F(\d^{k-1} \phi) 
	\quad \Forall \phi \in \left.X^{k-1}\right|_{\star J},
\end{equation}
for small $\epsilon$; in this work $\epsilon = 10^{-8} \beta$ is used. 
This regularization can be avoided by posing \cref{eq:local-potential-problem} on a reduced space, 
as discussed in the next section.



\subsubsection{Type-$\rmone$ based decomposition}

The finest possible choice for $Y^{k-1}$ and $Z^k$ in 
\cref{eq:hiptmair-abstract} is to ensure
\begin{align*}
Y^{k-1} \cap \ker(\d^{k-1}; X^{k-1}) = \{0\} \quad \text{and} \quad Z^k \cap 
\d^{k-1} X^{k-1} = 
\{0\}.
\end{align*}
However, this is not practical. As shown in \cref{eq:dk-kernel-decomp},
one component of $\ker(\d^{k-1}, X^{k-1})$ is the space of low-order harmonic 
forms $\mathfrak{H}^k$ \cref{eq:harmonic-forms} which depends on the topology of 
$\Omega$, and forms in $\mathfrak{H}^k$ have global support owing to the 
orthogonality condition in \cref{eq:harmonic-forms}.
Instead, a pragmatic intermediate choice motivated by 
\cref{lem:kernel-image-dk-global-splitting} is to employ
\begin{equation} \label{eq:hiptmair-reduction}
	Y^{k-1} = X^{k-1, \rmone} \quad \text{and} \quad Z^k = X^{k, \rmone}, 
	%\coloneqq X^k_p(\mesh) \setminus 
	%\left(\d^{k-1} \left(X^{k-1}_{h,p}\setminus X^{k-1}_{h,1}\right)\right).
\end{equation}
i.e.~to use only the span of the type-I basis functions. This choice excludes all 
type-$\rmtwo$ basis functions in the potential space $Y^{k-1}$ and in the space 
$Z^{k}$, and
this choice is simple to construct because our basis is already split in this 
fashion. Since $X^{0, \rmone} = X^0$, we only obtain a 
reduction compared to the largest choice of the potential space $Y^{k-1} = 
X^{k-1}$ if $k > 1$. We then arrive at the
$\ph{X^{k-1, \rmone}}{X^{k, \rmone}}$ decomposition:
\begin{equation} \label{eq:pavarino_hiptmair-novel}
	X^k = W^k + \sum_{J \in \Delta_{k-1}(\mesh)} \left.\d^{k-1} 
	X^{k-1, \rmone} \right|_{\star J} + \sum_{L \in \Delta_{k}(\mesh)} \left. 
	X^{k, \rmone} \right|_{\star L},
\end{equation}
which we believe to be novel.  

The local potential problems for the $\ph{X^{k-1, \rmone}}{X^{k, \rmone}}$ 
decomposition take the following form for $J \in \Delta_{k-1}(\mesh)$: Find $\psi 
\in X^{k-1, \rmone}|_{\star J}$ such that
\begin{equation} \label{eq:local-potential-problem-type-I}
	a^k(\d^{k-1} \phi, \d^{k-1} \psi) = 
	(\d^{k-1} \phi, \beta\d^{k-1} \psi)_{\star J} = F(\d^{k-1} \phi) 
	\quad \Forall \phi \in \left.X^{k-1, \rmone}\right|_{\star J}.
\end{equation}
Note that if $w \in W^{k-1}|_{\star J}$ satisfies $\d^{k-1} w = 0$, then $w 
\equiv 0$, and so problem \cref{eq:local-potential-problem-type-I} is invertible
thanks to 
\cref{lem:image-type-one-bubble-disjoint-whitney,%
lem:kernel-image-dk-global-splitting}. In particular, problem 
\cref{eq:local-potential-problem-type-I} involves fewer degrees of freedom than 
problem \cref{eq:local-potential-problem-added-mass}. A similar approach was used 
by Zaglmayr 
\cite[\S 6.3]{zaglmayr06} to solve 
the curl-curl problem on the whole domain $\Omega$ by posing the problem only 
the type-$\rmone$ space $X^{1, \rmone}$.

\begin{remark}
	Since the type-$\rmone$ space $X^{k-1, \rmone}$ captures the image of the 
	exterior derivative $\d^{k-1}$ (i.e. $\d^{k-1} X^{k-1} = \d^{k-1} X^{k-1, 
	\rmone}$), the space decompositions $\ph{X^{k-1}}{X^{k}}$ and $\ph{X^{k-1, 
	\rmone}}{X^{k}}$ are identical and thus satisfy the hypotheses of 
	\cref{thm:generic-subspace-decomp-interface-interior-split} with the same 
	stability constant. The only distinction we make in the 
	notation is the form of the potential problems 
	\cref{eq:local-potential-problem-added-mass} and 
	\cref{eq:local-potential-problem-type-I}. So, one could always use the 
	type-$\rmone$ space in the potential space and avoid solving the 
	singular problem \cref{eq:local-potential-problem}.
\end{remark}


Combining \cref{eq:pavarino_hiptmair-novel} with 
\cref{thm:generic-subspace-decomp-interface-interior-split} yields the 
$\ph{X^{k-1, \rmone}_{\interface}}{X^{k, 
\rmone}_{\interface}}+\jacobi{X^k_{\interior}}$ decomposition:
\begin{equation} \label{eq:hcurl-decomp}
	X^k =  W^k 
	+ \sum_{J\in \Delta_{k-1}(\mesh)} \left. \d^{k-1} X^{k-1, \rmone}_{\interface} 
	\right|_{\star J}
	%
	+ \sum_{L\in \Delta_k(\mesh)} \left. X^{k, \rmone}_{\interface} \right|_{\star 
	L} 
	%
	+ 
	\sum_{\ell=1}^{N^k_{\interior}} \spn\left\{ \phi_{ 
	\ell}^{k} 
	\right\}.
\end{equation}




