\section{Bubble complexes and trace decomposition}

\begin{lemma}
	\label{lem:bubble-subcomplex-exact}
	The complex \cref{eq:bubble-subcomplex} is exact for all $S \in 
	\Delta_l(\That)$ with $l \in k+1:d$.
\end{lemma}
\begin{proof}
	The case that $S = \That$ follows from the exactness of the usual finite 
	element de Rham complex with homogeneous boundary conditions (see e.g. 
	\cite[Corollary 2]{Licht2017complexes}).

	The only remaining complex to verify is the case that $S \in 
	\Delta_2(\That)$. One can readily verify that $\mathring{X}_p^0(S) = \P_p(S) 
	\cap 
	H^1_0(S)$ and
	\begin{align}
		\label{eq:proof:2d-hcurl}
		\mathring{X}_p^1(S) = \begin{cases}
			(\P_{p-1}(S)^2 + \P_{p-1}(S) (\Pi_S \bx)^{\perp}) \cap H_0(\curl{}; 
			S) & 
			\text{if } X^1_p(\That) = \Ned_p(\That), \\   
			\P_p(S)^2 \cap H_0(\curl{}; S) & \text{if } X^1_p(\That) = 
			\NedTwo_p(\That),
		\end{cases}
	\end{align}
	which is the usual 2D \Nedelec{} space of first or second kind with vanishing
	tangential trace. The exactness of \cref{eq:bubble-subcomplex} again follows 
	from \cite[Corollary 2]{Licht2017complexes}.
\end{proof}

\begin{lemma}
	\label{lem:trace-decomposition}
	The decomposition \cref{eq:ktrace-decomp} holds.
\end{lemma}
\begin{proof}
	Let $S \in \Delta_k(\That)$. Direct calculation revels that $\tr^k_S 
	W^k(\That) = \mathbb{R}$. Define $\tau \in \{0, 1\}$ as follows: Let 
	$\tau = 1$ if $k=0$ or $X^k(\That)$ is of the first kind and $\tau = 0$ 
	otherwise. Then, direct calculation shows that
	\begin{align*}
		\tr^k_S X^{k}(\That) = \P_{p-\tau}(S) \qquad \Forall S \in 
		\Delta_k(\That).
	\end{align*}
	If $k = 1$, then $\mathring{X}^{0}(S) = 
	\mathcal{P}_{p+1-\tau}(S) \cap H^1_0(S)$, while if $k = 2$, then
	$\mathring{X}^{1}(S)$ is given by \cref{eq:proof:2d-hcurl} with $p$ 
	replaced by $p + 1 - \tau$. \cite[Corollary 2]{Licht2017complexes} then 
	implies that the following sequence is exact
	\begin{equation*}
		\begin{tikzcd}[ampersand replacement=\&]
			\mathring{X}^{k-1}(S) \arrow[r, "\d^{k-1}_S"] \& 
			\P_{p-\tau}(S) \cap L^2_0(S) \arrow[r] \& 0,
		\end{tikzcd}
	\end{equation*}
	and the result now follows.
\end{proof}

