\section{Energy stable splittings}

By construction, the space $X^k$ admits direct sum decompositions based on 
splitting the interior and interface basis functions and based on splitting the 
type-$\rmone$ and type-$\rmtwo$ basis functions:
\begin{align} \label{eq:xk-interior-interface-typeI-typeII-split}
	X^k = X^{k}_{\interface} \oplus 
	X^k_{\interior} \quad \text{and} \quad 
	X^{k} = X^{k, \rmone} \oplus X^{k, \rmtwo}.
\end{align}
We now examine the energy stability of these two decompositions. Given a domain 
$\omega$, let
\begin{align*}
	(u, v)_{H(\d^k; \omega)} := (u, v)_{\omega} + (\d^k u, \d^k v)_{\omega} \quad 
	\text{and} \quad \|u\|_{H(\d^k; \omega)}^2 := (u, u)_{H(\d^k; \omega)}.
\end{align*}


\subsection{$H(\d^k)$-stability on the reference cell}

We begin by analyzing the stability of the decompositions on the reference cell:
\begin{align}
	X^k(\That) = X^{k}_{\interface}(\That) \oplus 
	X^k_{\interior}(\That) \quad \text{and} \quad 
	X^{k}(\That) = X^{k, \rmone}(\That) \oplus X^{k, \rmtwo}(\That),
\end{align}
where $X^{k}_{\interface}(\That)$, etc.~denotes the space analogous to 
\cref{eq:global-spaces-typeI,eq:global-spaces-typeII,%
eq:global-space-interior-interface} on the reference cell. In particular, given 
$u \in X^k(\That)$, there exist unique $u_{\interface} \in  
X^{k}_{\interface}(\That)$, $u_{\interior} \in  X^{k}_{\interior}(\That)$, 
$u_{\rmone} \in X^{k, \rmone}(\That)$, and $u_{\rmtwo} \in X^{k, \rmtwo}(\That)$ 
such that
\begin{align}
	u = u_{\interface} + u_{\interior} \quad \text{and} \quad u = u_{\rmone} + 
	u_{\rmtwo},
\end{align}
and the mappings $u \mapsto (u_{\interface}, u_{\interior})$ and $u \mapsto 
(u_{\rmone}, u_{\rmtwo})$ are linear. The first result shows that the 
interior/interface decomposition is uniformly 
stable with respect to the polynomial degree.
\begin{theorem}	
	\label{thm:spectral-equiv-reference-stiffness}
	There exists a constant $C$ depending only on the dimension $d$ such that for 
	all $u \in X^k(\That)$, there holds
	\begin{align}
		\label{eq:stable-decomp-reference-mass}
		\frac{1}{2} \|u\|_{\That}^2 \leq \| u_{\interface} \|_{\That}^2 
		+ \| u_{\interior} \|_{\That}^2 \leq  C \|u\|_{H(\d^k; \That)}^2
	\end{align}
	and
	\begin{align}
		\label{eq:stable-decomp-reference-dk}
		\|\d^k u\|_{\That}^2 = \| \d^k u_{\interface} \|_{\That}^2 
		+ \| \d^k u_{\interior} \|_{\That}^2. 
	\end{align}
\end{theorem}
\begin{proof}
	We prove the case $d=3$; the case $d=2$ follows from analogous arguments.

	\noindent \textbf{Step 1: $\d^k$ stability. } The degrees of freedom 
	\cref{eq:type-I-dofs,eq:type-II-dofs} show that
	$u_{\interior}$ satisfies
	\begin{subequations}
		\label{proof:eq:interior-orthog-conditions}
		\begin{alignat}{2}
			\label{proof:eq:interior-orthog-conditions-1}
			(u_{\interior}, \d^{k-1} y)_{\That} &= (u, \d^{k-1} y)_{\That} \qquad 
			& &\Forall y 
			\in 
			\mathring{X}^{k-1}(\That), \\
			%
			\label{proof:eq:interior-orthog-conditions-2}
			(\d^{k} u_{\interior}, \d^k v)_{\That} &= (\d^k u, \d^k v)_{\That} 
			\qquad & &\Forall 
			v 
			\in 
			\mathring{X}^k(\That),
		\end{alignat}
	\end{subequations}
	and in particular $\d^k u_{\interior}$ is the $L^2(\That)$-projection of 
	$\d^k u$ 
	onto 
	$\d^k \mathring{X}^k(\That)$. \Cref{eq:stable-decomp-reference-dk} 
	immediately 
	follows.

	\noindent \textbf{Step 2: $L^2$-stability. } Suppose first that $k = 0$. 
	Then, 
	Poincar\'{e}'s inequality gives $\|u_{\interior}\|_{\That} \leq C 
	\|u\|_{H(\d^k; \That)}$. Now suppose that $k \in \{1,2\}$. Then, conditions 
	\cref{proof:eq:interior-orthog-conditions} ensure that there exists $q \in 
	\d^k 
	\mathring{X}^k(\That)$ such that
	\begin{subequations}
		\begin{alignat}{2}
			(u_{\interior}, v)_{\That} + (\d^k v, q)_{\That} &= (u, v)_{\That} 
			\qquad & &\Forall v \in 
			\mathring{X}^k(\That), \\
			%
			(\d^k u_{\interior}, r)_{\That} &= (\d^k u, r)_{\That} \qquad & 
			&\Forall r \in \d^k 
			\mathring{X}^k(\That).
		\end{alignat}
	\end{subequations}
	Applying standard estimates for saddle point systems gives
	\begin{align*}
		\| u_{\interior} \|_{H(\d^k; \That)} \leq C (\beta^k)^{-2} \|u\|_{H(\d^k; 
		\That)},
	\end{align*}
	where $\beta^k$ is the inf-sup constant
	\begin{align*}
		\beta^k := \inf_{0 \neq r \in \d^k \mathring{X}^k(\That) } \sup_{0 \neq v 
			\in 
			\mathring{X}^k(\That) } \frac{ (\d^k v, r)_{\That} }{ \|v\|_{H(\d^k, 
			\That)} 
			\|r\| }.
	\end{align*}

	We now show that $\beta^k \geq \beta_0 > 0$ for some $\beta_0$ independent of 
	$p$. Let $r \in \d^k \mathring{X}^k(\That)$ be given. Thanks to \cite[Theorem 
	5.1]{Ern2024}, there exists $v \in \mathring{X}^k(\That)$ such that $\d^k v = 
	r$ and $\|v\|_{\That} \leq C \|r\|_{\That}$, where $C$ is independent of $p$ 
	and 
	$r$. Then, $\|v\|_{H(\d^k, \That)} \leq C \|r\|_{\That}$, and so $\beta^k 
	\geq 
	C^{-1} > 0$. Consequently, for $k \in 0:2$, there holds $\|u_{\interior} 
	\|_{H(\d^k, 
		\That)} \leq C \|u\|_{H(\d^k, \That)}$. Inequality 
	\cref{eq:stable-decomp-reference-mass} then follows.
\end{proof}

We now turn to the type-$\rmone$/type-$\rmtwo$ decomposition. Let $\{ u_j^k,
\omega_{j, p}^{k, \rmone/\rmtwo} : j \in 1:\dim X^k(\That) \} \subset X^k(\That) 
\times \mathbb{R}$ denote the eigenfunctions and eigenvalues 
(in increasing order) of the following 
eigenvalue problem: 
\begin{subequations}
	\label{eq:typeI-typeII-eigenproblem}
	\begin{alignat}{2}
		(u_i^k, u_j^k)_{\That} &= \omega_{i, p}^{k, \rmone/\rmtwo} \delta_{ij} 
		\qquad & &\Forall i, j \in 1:\dim 
			X^k(\That), \\
			%
			(u_{i, \rmone}^k, u^k_{j, \rmone})_{\That} + (u_{i, 
			\rmtwo}^k, u_{j, \rmtwo}^{k})_{\That} &= \delta_{ij} 
		\qquad & &\Forall i, j \in 1:\dim X^k(\That).
	\end{alignat}
\end{subequations}

\noindent Then, the following result shows that the $L^2(\Khat)$ stability of 
the 	 
type-$\rmone$/type-$\rmtwo$ decomposition is determined by the minimal eigenvalue 
$\omega_{1, p}^{k, \rmone/\rmtwo}$.
\begin{lemma} \label{lem:stable-decomp-one-two-ref}
	For all $u \in X^k(\That)$, $\d^k u = \d^k u_{\rmone}$ and there holds
	\begin{align} \label{eq:stable-decomp-one-two-ref}
		\frac{1}{2} \|u\|_{\That}^2 \leq \|u_{\rmone}\|_{\That}^2 + 
		\|u_{\rmtwo}\|_{\That}^2 \leq \frac{1}{\omega_{1, p}^{k, \rmone/\rmtwo}} 
		\|u\|_{\That}^2.
	\end{align}
\end{lemma}
\begin{proof}
	Since $X^{k , \rmtwo}(\That) \subset \ker(\d^k; X^k(\That))$ thanks to 
	\cref{lem:d-preserves-basis-functions}, $\d^k u = \d^k u_{\rmone}$. Moreover, 
	let $c_j \in \mathbb{R}$ be such that $u = \sum_{j=1}^{\dim X^k(\That)} c_j 
	u_j^k$. Then, applying \cref{eq:typeI-typeII-eigenproblem} gives
	\begin{align*}
		\|u_{\rmone}\|_{\That}^2 + \|u_{\rmtwo}\|_{\That}^2 = 
		\sum_{j=1}^{\dim X^k(\That)} c_j^2 \leq \frac{1}{\omega_{1, p}^{k, 
		\rmone/\rmtwo}} \sum_{j=1}^{\dim X^k(\That)} c_j^2 \omega_{j, p}^{k, 
		\rmone/\rmtwo} = \|u\|_{\That}^2.
	\end{align*}
\end{proof}

\subsection{Energy stability on physical cell}

Given an element in $T \in \mesh$ and $u \in X^k$, define
\begin{align*}
	a_{T}^k(u, v) := (u, \beta v)_{T} + (\d^k u, \alpha \d^k v)_T \quad 
	\text{and} 
	\quad \|u\|_{a, T}^2 := a_T^k(u, u) \qquad \Forall u, 
	v \in X^k(T).
\end{align*}
We again use the notation $u_{\interface}$, $u_{\interior}$, $u_{\rmone}$, and 
$u_{\rmtwo}$ to denote the decomposition of $u \in X^k$ into its components in 
the decompositions \cref{eq:xk-interior-interface-typeI-typeII-split}. The next 
result shows that these decompositions are energy stable.


\begin{corollary} \label{cor:stable-decomp-interior-interface}
	% TODO fix this
	There exist constants $C_1, C_2 > 0$ depending only on shape 
	regularity, 
	$d$, and $k$ such that for all $u \in X^k_p(\mesh)$ 
	and $T \in \mesh$, there holds 
	\begin{alignat}{2}
		\label{eq:stable-decomp-physical-stiffness}
		\frac{1}{2} \|u\|_{a, T}^2 &\leq \| u_{\interface} \|_{a, T}^2 + 
		\| 		
		u_{\interior} \|_{a, T}^2 & &\leq C_1 \max\left\{ 1, 
		\frac{\beta}{\alpha} h_T^2 \right\}  \|u\|_{a, T}^2, \\
		%
		\label{eq:stable-decomp-one-two-physical-stiffness}
		\frac{1}{2} \|u\|_{a, T}^2 &\leq \| u_{\rmone} \|_{a, T}^2 + \| 		
		u_{\rmtwo} \|_{a, T}^2 & &\leq \frac{C_2}{\omega_{1, p}^{k, 
				\rmone/\rmtwo}}   \|u\|_{a, T}^2,
	\end{alignat}
	where $\omega_{1, p}^{k, \rmone/\rmtwo}$ is defined in 
	\cref{eq:typeI-typeII-eigenproblem}. 
\end{corollary}
\begin{proof}	
	Let $T \in \mesh$ and $\hat{u} := (\pullback_T^k)^{-1} 
	u$ so that $\d^k u = \pullback_T^{k+1} (\d^k \hat{u})$. 

	\noindent \textbf{Step 1: $H(\d^k; T)$-stability of $u_{\interior}$. } Note 
	that 
	$\pullback^k_T$ is of the form  $\pullback^k_T \hat{v} = G_T^k \hat{v} \circ 
	F_T^{-1}$ for some constant or matrix $G^k_T$. Thus, there holds
	\begin{align*}
		\|u_{\interior}\|_{T}^2 = |\det J_T| \cdot \| G^k_T \Pi_{\That, 
		\interior}^k 
		\hat{u} 
		\|_{\That}^2 &\leq |\det J_T| \cdot
		|G^k_T|^2  \|\Pi_{\That, \interior}^k \hat{u} \|_{\That}^2 \\
		%
		&\leq   |\det J_T| \cdot |G^k_T|^2  \left( \|\hat{u}\|_{\That}^2 + 
		\|\d^k 
		\hat{u} \|_{\That}\|^2 \right),
	\end{align*}
	where $|G^k_T|$ also denotes the spectral norm on matrices. Now,
	\begin{align*}
		\|\hat{u}\|_{\That}^2 = |\det J_T^{-1}| \cdot \| (G^k_T)^{-1} u\|_{T}^2 
		\leq 
		|\det J_T|^{-1} |(G^k_T)^{-1}|^2 \|u\|_{T}^2
	\end{align*}
	and
	\begin{align*}
		\|\d^k \hat{u} \|_{\That}^2 = |\det J_T^{-1}| \cdot \| (G^{k+1}_T)^{-1} 
		\d^k 
		u\|_{T}^2 \leq  |\det J_T|^{-1} |(G^{k+1}_T)^{-1}|^2 \| \d^k u\|_{T}^2,
	\end{align*}
	and so
	\begin{align*}
		\|u_{\interior}\|_{T}^2 \leq |G^k_T|^2 \left( |(G^k_T)^{-1}|^2 
		\|u\|_{T}^2 +  |(G^{k+1}_T)^{-1}|^2 \| \d^k u\|_{T}^2 \right).
	\end{align*}
	One may then verify that $|G^k_T| \cdot |(G^k_T)^{-1}| \leq C$ and $|G^k_T| 
	\cdot 
	|(G^{k+1}_T)^{-1}| \leq C h_T$ for some $C > 0$ 
	depending only on shape regularity, $d$, and $k$. Thus,
	\begin{align*}
		% TODO fix
		\| u_{\interior} \|_{T}^2 \leq C \left( \|u\|_{T}^2 + h_T^2 \|\d^k 
		u\|_{T}^2 \right).
	\end{align*}
	Similar scaling arguments applied to \cref{eq:stable-decomp-reference-dk} 
	show that
	\begin{align}
		\label{proof:eq:interior-dk-bound}
		\|\d^k u_{\interior} \|_{T} \leq C \| \d^k u\|_{T}.
	\end{align}

	\noindent \textbf{Step 2: \cref{eq:stable-decomp-physical-stiffness}. } We 
	then obtain
	\begin{align*}
		(u_{\interior}, \beta u_{\interior})_{T} \leq C \beta \left\{  
		 (u, u)_{T} + h_T^2 (\d^k u, 
		\d^k u)_{T} \right\} &\leq C \left\{  (u, \beta u)_{T} + 
		\frac{\beta}{\alpha} h_T^2 (\d^k u, \alpha \d^k u)_{T} \right\} \\
		%
		&\leq C \max\left\{ 1, \frac{\beta}{\alpha} h_T^2 \right\} a^k_{T}(u, u),
	\end{align*}
	and so \cref{proof:eq:interior-dk-bound} gives 
	\begin{align*}
		a^k_{T}(u_{\interior}, u_{\interior}) \leq C \max\left\{ 1, 
		\frac{\beta}{\alpha} h_T^2 \right\} 
		a^k_{T}(u, u).
	\end{align*}
	Inequality \cref{eq:stable-decomp-physical-stiffness} now follows from the 
	bound $\|u_{\interface}\|_{a, T}^2 \leq 2 \left( \|u\|_{a, T}^2 + 
	\|u_{\interior}\|_{a, T}^2 	\right)$.


	\noindent \textbf{Step 3: \cref{eq:stable-decomp-one-two-physical-stiffness}. 
	} Inequality \cref{eq:stable-decomp-one-two-physical-stiffness} follows from 
	\cref{lem:stable-decomp-one-two-ref} using analogous arguments from Steps 1 
	and 2 on noting that $\omega_{1, p}^{k, \rmone/\rmtwo} \leq 2$ by 
	\cref{eq:stable-decomp-one-two-ref}.
\end{proof}

We may further decompose the interior component into individual basis functions, 
and this decomposition is stable for any choice of $\alpha$ and $\beta$.
\begin{lemma}
	Let $N_{K, \interior} := \dim \mathring{X}^k(T)$ and let $\{ \phi_{T, i}^k : 
	i \in 1:N_{K, \interior} \}$ denote interior basis functions supported on $T$.
	Then, there exists a constant $C > 0$ depending only on shape regularity such 
	that if $u_{\interior} = \sum_{i=1}^{N_{K, \interior}} u_{\interior, i} 
	\phi_{T, i}^k$, 
	then 
	\begin{align}
		\label{eq:stable-decomp-physical-interior}
		C^{-1} \| u_{\interior}\|_{a, T}^2 \leq  \sum_{i=1}^{N_{K, \interior}}
		|u_{\interior, i}|^2 \| \phi_{T, i}^{k}\|_{a, T}^2 \leq C 
		\|u_{\interior}\|_{a, T}^2.
	\end{align}
\end{lemma}
\begin{proof}
	Thanks to \cref{lem:ref-element-matrix-properties}, 
	\cref{eq:stable-decomp-physical-interior} holds in the case that $T = \That$ 
	is the reference element and $(\alpha, \beta) \in \{  (0, 1), (1, 0) \}$. A 
	standard scaling argument similar to the one in Step 1 of the 
	proof of \cref{cor:stable-decomp-interior-interface} shows that 
	\cref{eq:stable-decomp-physical-interior} holds for all $T \in \mesh$ and 
	$(\alpha, \beta) \in \{  (0, 1), (1, 0) \}$, where 
	$C$ only depend on shape regularity. The case of general $\alpha$ and $\beta$ 
	follows from linearity.	
\end{proof}

