\section{Proof of \cref{thm:generic-subspace-decomp-interface-interior-split}}
\label{sec:proof-generic-subspace-decomp-interface-interior-split}

\noindent \textbf{Step 1: Stable decomposition 
\cref{eq:abstract-space-decomp-split-stable}. } Let $u \in X^k$ and let 
$\Pi^k_{\interior} : X^k \to X^k_{\interior}$ be defined by the rule
\begin{align*}
	\Pi^k_{\interior} v := v_{\interior} \qquad \forall v \in X^k.
\end{align*}
Note that $\Pi^k_{\interior}$ is a projection operator. Thanks to 
\cref{eq:stable-decomposition-assumption}, there 
exist $u_m \in X_m$, $m \in 1:M$, satisfying
\begin{align*} 
	\sum_{m=1}^{M} u_m = u 
	%
	\quad \text{and} \quad 
	%
	\sum_{m=1}^{M} \|u_m\|_a^2 \leq C_{\mathrm{stable}}(\alpha, \beta) 
	\|u\|_a^2,
\end{align*}
where let $\|\cdot\|_a$ denotes the energy norm: $\|\cdot\|_a^2 := a^k(\cdot, 
\cdot)$. Let $u_{m, \interface} := (I - \Pi_{\interior}^k) u_m$ and 
$u_{\interior} := 
\Pi_{\interior}^k u$. Since $\Pi^k_{\interior}$ is a projection, there holds
\begin{align*}
	\sum_{i=1}^{M} u_{m, \interface} + u_{\interior} = (I - \Pi_{\interior}^k) 
	\sum_{i=1}^{M} u_{m} + \Pi_{\interior}^k u = (I - \Pi_{\interior}^k) u + 
	\Pi_{\interior}^k u = u,
\end{align*}
and applying 
\cref{eq:stable-decomp-physical-stiffness} 
element-by-element gives
\begin{align*}
	\sum_{m=1}^M \|u_{m, \interface}\|_a^2 \leq C \max\left\{ 1, 
	\frac{\beta}{\alpha} h^2 \right\} \sum_{m=1}^M \|u_m\|_a^2  \leq C 
	C_{\mathrm{stable}}(\alpha, \beta) \max\left\{ 1, 
	\frac{\beta}{\alpha} h^2 \right\} \|u\|_a^2.
\end{align*}
Consequently, there holds
\begin{align*}
	\|u_{\interior}\|_a^2 \leq C \max\left\{ 1, 
	\frac{\beta}{\alpha} h^2 \right\} \|u\|_a^2.
\end{align*}
Summing \cref{eq:stable-decomp-physical-interior} 
over the elements then gives 
\begin{align*}
	a_{\interior}^k(u_{\interior}, u_{\interior}) + \sum_{m=0}^{M} \| u_{m, 
		\interface} \|_{a}^2 \leq C C_{\mathrm{stable}}(\alpha, \beta) 
		\max\left\{ 1, 
	\frac{\beta}{\alpha} h^2 \right\} \|u\|_{a}^2,
\end{align*}
which completes the proof of \cref{eq:abstract-space-decomp-split-stable}. 

