\subsection{Proof of \cref{lem:ph-typeI-typeII-stable}}
\label{sec:proof-ph-typeI-typeII-stable}

Let $u \in X^k$ and let $u_0 \in W^k$, $u_{J} \in \left. \d^{k-1} X^{k-1} 
\right|_{\star J}$, $J \in \Delta_{k-1}(\mesh)$, and $u_{L} \in \left. X^k 
\right|_{\star L}$, $L \in \Delta_k(\mesh)$, be such that
\begin{align*}
	u_0 + \sum_{J \in \Delta_{k-1}(\mesh)} u_J + \sum_{L \in 
		\Delta_{k}(\mesh)} u_L &= u, \\
	%
	\|u_0\|_{a}^2 + \sum_{J \in \Delta_{k-1}(\mesh)} \|u_J\|_{a}^2 + \sum_{L \in 
		\Delta_{k}(\mesh)} \|u_L\|_{a}^2 &\leq C_{\mathrm{PH}} \|u\|_{a}^2,
	%
	%\|\d^k u_0\|^2 + 
	%\sum_{L \in \Delta_{k}(\mesh)} \|\d^k u_L\|^2 &\leq C_{\mathrm{PH}} 
	%\|\d^k u\|^2,
\end{align*}
where $\|\cdot\|_{a}$ again denotes the energy norm.
%where we used that $\d^k u_{J} = 0$. 
Thanks to \cref{eq:dk-image-decomp}, $\left. 
\d^{k-1} X^{k-1} \right|_{\star J} = \left. \d^{k-1} X^{k-1, \rmone} 
\right|_{\star J}$, and so $u_{J} \in \left. \d^{k-1} X^{k-1, \rmone} 
\right|_{\star J}$ for all $J \in \Delta_{k-1}(\mesh)$.

For each $L \in \Delta_k(\mesh)$, there exist unique $u_{L, \rmone} \in \left. 
X^{k, \rmone} \right|_{\star L}$ and $u_{L, \rmtwo} \in \left. X^{k, \rmtwo}  
\right|_{\star L}$ such that $u_{L} = u_{L, \rmone} + u_{L, \rmtwo}$ thanks to 
\cref{eq:typeI-typeII-direct-sum} restricted to $\star L$. Moreover, summing 
\cref{eq:stable-decomp-one-two-physical-stiffness} over the cells in $\star L$, 
we obtain
\begin{align}\label{eq:proof:typI-typeII-patch-stability}
	\| u_{L, \rmone} \|_{a, \star L}^2 + \|u_{L, \rmtwo} \|_{a, \star L}^2 &\leq 
	\frac{C}{\omega_{1, p}^{k, \rmone/\rmtwo}} 
	\|u_L\|_{a, \star L}^2.
\end{align}
\begin{comment}
\begin{subequations}
	\label{eq:proof:typI-typeII-patch-stability}
	\begin{align}
		\| u_{L, \rmone} \|_{\star L}^2 + \|u_{L, \rmtwo} \|_{\star L}^2 &\leq 
		C \max\left\{1, \frac{1}{\omega_{1, p}^{k, \rmone/\rmtwo}} \right\} 
		\|u_L\|_{H(\d^k, \star L)}^2 \\
		%
		\|\d^k u_{L, \rmone}\|_{\star L}^2 &= \|\d^k u_{L}\|_{\star 
			L}^2.
	\end{align}	
\end{subequations}
\end{comment}
Thanks to \cite[Corollary 2]{Licht2017complexes}, the complex 
\begin{equation*}
	\begin{tikzcd}[ampersand replacement=\&]
		\left. X^{k-1} \right|_{\star L} \arrow[r, "\d^{k-1}"] \& \left. X^{k} 
		\right|_{\star L} 
		\arrow[r, "\d^k"] \& 
		\d^k \left. X^{k} \right|_{\star L} \arrow[r] \& 0
	\end{tikzcd}
\end{equation*}
is exact  since $\star L$ is contractible, and so $u_{L, \rmtwo} \in \d^{k-1} 
\left. X^{k-1} \right|_{\star L} = \d^{k-1}	\left. X^{k-1, \rmone} 
\right|_{\star L}$.


For $J \in \Delta_{k-1}(\mesh)$, let $\Delta_{k}(J)$ denote that subsimplices of 
$J$ of dimension $k$ and define
\begin{align*}
	\tilde{u}_J = u_J + \frac{1}{|\Delta_k(J)|} \sum_{L \in \Delta_k(J)} u_{L, 
	\rmtwo}.
\end{align*}
Then, $\tilde{u}_J \in \d^{k-1}	\left. X^{k-1, \rmone} 
\right|_{\star L}$ and
\begin{align*}
	\| \tilde{u}_J \|_a^2 \leq 2 \left( \|u_J\|_a^2 + \frac{1}{|\Delta_k(J)|} 
	\sum_{L 
	\in \Delta_k(J)} \| u_{L,\rmtwo}\|_a^2 \right).
\end{align*}
Consequently, there holds
\begin{align*}
	u_0 +  \sum_{J \in \Delta_{k-1}(\mesh)} \tilde{u}_J + \sum_{L \in 
		\Delta_{k}(\mesh)} u_{L, \rmone} = u_0 + \sum_{J \in \Delta_{k-1}(\mesh)} 
		u_J + \sum_{L \in \Delta_{k}(\mesh)} u_L = u,
\end{align*}
and applying \cref{eq:proof:typI-typeII-patch-stability} gives
\begin{align*}
	&\|u_0\|_a^2 + \sum_{J \in \Delta_{k-1}(\mesh)} \|\tilde{u}_J\|_a^2 + \sum_{L 
	\in 
		\Delta_{k}(\mesh)} \|u_{L, \rmone}\|_a^2 \\
		%
		&\qquad \leq 2 \left( \|u_0\|_a^2 + \sum_{J 
		\in \Delta_{k-1}(\mesh)} \|\tilde{u}_J\|_a^2 + \sum_{L \in 
		\Delta_{k}(\mesh)} \left( \|u_{L, \rmone}\|_a^2 + \|u_{L, 
		\rmtwo}\|_a^2\right) \right) \\
		%
		&\qquad \leq C_{\mathrm{PH}} \frac{C}{\omega_{1, p}^{k, \rmone/\rmtwo}}   
		\|u\|_{a}^2,
\end{align*}
which completes the proof with $C_{\rmone/\rmtwo} = C/\omega_{1, p}^{k, 
\rmone/\rmtwo}$. \hfill \proofbox

\subsection{The $p$-dependence of $C_{\rmone/\rmtwo}$}
\label{sec:typeI-typeII-constant-p}

The previous section shows that we may take $C_{\rmone/\rmtwo} = C/\omega_{1, 
p}^{k, \rmone/\rmtwo}$ in 
\cref{lem:ph-typeI-typeII-stable}. We show the values of $\omega_{1, p}^{k, \rmone/\rmtwo}$ for $\Ned_p$ and $\RT_p$ with $p \in 1:10$ in \cref{fig:decoupling}. It appears that $\omega_{1, p}^{1, \rmone/\rmtwo} \sim \mathcal{O}(p^{-3})$, while $\omega_{1, p}^{2, \rmone/\rmtwo} \sim \mathcal{O}(p^{-2})$. Thus, the type-I/type-II splitting approach may incur an algebraic factor of $p$ in the condition number estimate for the Riesz map problems. However, we only observed such a drastic growth in terms of iteration counts for the solvers $\ph{X^0}{X^{1, \rmone}}$ and $\ph{X_{\interface}^0}{X_{\interface}^{1, \rmone}}+\jacobi{X^1_{\interior}}$ when $\alpha = 10^{-3}$ and $\beta = 1$, as shown in \cref{tab:hcurl-unit-cube}.

