\section{Augmented Lagrangian preconditioning for Hodge Laplacians}

We first recall a few properties of Hilbert complexes from \cite{Arnold2010}. Let 
$(\{W^k\}, \{\d^k\})$ be a Hilbert complex with inner-product $\langle \cdot, 
\cdot \rangle$ inducing the norm $\|\cdot\|$.  Let $(\{V^k\}, \{\d^k\})$ be the 
associated domain complex:
\begin{equation}\label{eq:abstract-short-sequence}
	\begin{tikzcd}[ampersand replacement=\&]
		\cdots \arrow[r, "\d^{k-2}"] \& V^{k-1} \arrow[r, "\d^{k-1}"] \& V^{k} 
		\arrow[r, "\d^k"] \& V^{k+1} \arrow[r, "\d^{k+1}"] \& \cdots,
	\end{tikzcd}
\end{equation}
where the inner-product on $V^k$ is $\langle \cdot, \cdot \rangle + 
\langle \d^k \cdot, \d^k \cdot \rangle$. 
The complex induces the Hodge decomposition
\begin{align} \label{eq:abstract-hodge}
	V^k = \mathfrak{B}^k \oplus \mathfrak{H}^k \oplus \mathfrak{Z}^{k, \perp},
\end{align}
where $\mathfrak{B}^k$ is the image of $\d^{k-1}$, $\mathfrak{H}^k$ is the space 
of harmonic forms, and $\mathfrak{Z}^{k, 
\perp}$ is the orthogonal complement of the kernel of $\d^k$:
\begin{align*}
	\mathfrak{B}^k &:= \d^{k-1} V^{k-1} = \d^{k-1} \mathfrak{Z}^{k-1,\perp}, \\
	\mathfrak{H}^k &:= \{ \mathfrak{h} \in V^k : \d^{k} \mathfrak{h} = 0 \text{ and } \langle \mathfrak{h}, \d^{k-1} 
	\sigma \rangle = 0 \ \forall \sigma \in V^{k-1} \}, \\
	%
	\mathfrak{Z}^{k, \perp} &:= \{ v \in V^{k} : \langle v, z \rangle = 0 \ 
	\forall z \in V^k \text{ with } \d^k z = 0 \}.
\end{align*}
Note that the Hodge decomposition is orthogonal with respect to the inner-product 
on $W^k$ and on $V^k$. Moreover, given $v \in V^k$, we write $v = 
v_{\mathfrak{B}} + v_{\mathfrak{H}} + v_{\perp}$ to denote the Hodge 
decomposition of $v$.


The mixed formulation of the Hodge Laplace problem associated to 
\cref{eq:abstract-short-sequence} reads as follows:
Find $(\sigma, u, p) \in V^{k-1} \times V^k \times \mathfrak{H}^{k}$ such that
\begin{subequations}\label{eq:abstract-hodge-laplace}
	\begin{alignat}{2}
		-\langle \sigma, \tau \rangle + \langle u, \d^{k-1} \tau \rangle &= 0 
		\qquad & &\forall \tau \in V^{k-1}, \\
		%
		\langle \d^{k-1} \sigma, v \rangle + \langle p, v \rangle + \langle 
		\d^k u, \d^k v \rangle &= \langle f, v \rangle \qquad & &\forall v \in 
		V^{k}, \\
		%
		\langle u, q \rangle &= 0 \qquad & &\forall q \in \mathfrak{H}^{k}.
	\end{alignat}
\end{subequations}
We may combine the bilinear forms in \cref{eq:abstract-hodge-laplace} into one 
large symmetric bilinear form
\begin{align*}
	A(\sigma, u, p; \tau, v, q) := \langle \d^k u, \d^k v \rangle + \langle 
	\d^{k-1} \sigma, v \rangle + \langle u, \d^{k-1} \tau \rangle - \langle 
	\sigma, \tau \rangle + \langle p, v \rangle + \langle u, q \rangle.
\end{align*} 
Given $\gamma > 0$, we also introduce the following weighted inner-product on 
$V^{k-1} \times V^k \times \mathfrak{H}^{k}$:
\begin{align*}
	B_{\gamma}(\sigma, u, p; \tau, v, q) &:= \gamma^{-1} \langle u - 
	u_{\mathfrak{H}}, v - v_{\mathfrak{H}} \rangle + \langle u_{\mathfrak{H}}, 
	v_{\mathfrak{H}} \rangle + \langle \d^k u, \d^k v \rangle
	\\
	&\qquad + \langle \sigma, \tau \rangle + \gamma \langle \d^{k-1} \sigma, 
	\d^{k-1} \tau \rangle + \langle p, q \rangle.
\end{align*}


\begin{theorem} \label{thm:augmented-lagrangian-hl}
	Let $\gamma > 0$ and suppose that $V^{k-1}$ and $V^{k}$ are finite 
	dimensional. Consider the 
	following symmetric eigenvalue problem: Find $(\sigma, u, p) \in V^{k-1} 
	\times V^k \times \mathfrak{H}^{k}$ and $\lambda \in \mathbb{R}$ such that
	\begin{align} \label{eq:hodge-laplace-evals}
		A(\sigma, u, p; \tau, v, q) = \lambda B_{\gamma}(\sigma, u, p; \tau, v, 
		q) \qquad 
		\forall (\tau, v, q) \in V^{k-1} \times V^k \times \mathfrak{H}^{k}.
	\end{align}
	All of the eigenpairs of \cref{eq:hodge-laplace-evals} are classified as 
	follows.
	\begin{enumerate}
		\item[(i)] For any $\sigma \in V^{k-1}$, $(\sigma, -\gamma \d^{k-1} 
		\sigma, 0)$ and $\lambda = -1$ is an eigenpair of 
		\cref{eq:hodge-laplace-evals}.

		\item[(ii)] For any $p \in \mathfrak{H}^k$, $(0, \lambda p, p)$ and 
		$\lambda = \pm 1$ is an eigenpair of \cref{eq:hodge-laplace-evals}.

		\item[(iii)] Let $u_{\perp} \in \mathfrak{Z}^{k, \perp}$ and $\mu > 
		0$ be an eigenpair of the following eigenvalue problem:
		\begin{align} \label{eq:hodge-laplace-u-evals-aux}
			\langle \d^k u_{\perp}, \d^k v_{\perp} \rangle = \mu \langle 
			u_{\perp}, v_{\perp} \rangle \qquad 
			\forall v_{\perp} \in \mathfrak{Z}^{k, \perp}.
		\end{align}
		Then, $(0, u_{\perp}, 0)$ and $\lambda = \frac{\mu \gamma}{\mu \gamma + 
		1}$ is an eignpair of \cref{eq:hodge-laplace-evals}.

		\item[(iv)] Let $\sigma_{\perp} \in \mathfrak{Z}^{k-1, \perp}$ and 
		$\nu > 0$ be an eigenpair of the following eigenvalue problem: 
		\begin{align} \label{eq:hodge-laplace-sigma-evals-aux}
			\langle \d^{k-1} \sigma_{\perp}, \d^{k-1} \tau_{\perp} \rangle = \nu 
			\langle \sigma_{\perp}, \tau_{\perp} \rangle \qquad \forall 
			\tau_{\perp} \in 
			\mathfrak{Z}^{k-1, \perp}.
		\end{align}
		Then, the following is an eigenpair of \cref{eq:hodge-laplace-evals}:
		\begin{align*}
			(\sigma, \gamma \lambda^{-1} \d^{k-1} \sigma, 0) \quad \text{and} 
			\quad \lambda = \frac{\nu \gamma }{\nu \gamma + 1}.	
		\end{align*}
	\end{enumerate}
\end{theorem}
\begin{proof}
	(i-iv) may be verified by direct computation. We only show the details for 
	(iii) and (iv). Let $u_{\perp}$, $\mu$, and $\lambda$ be as in 
	(iii) and $(\tau, v, q) \in V^{k-1} \times V^k \times \mathfrak{H}^k$. Then,
	\begin{align*}
		A(0, u_{\perp}, 0; \tau, v, p) &= \langle \d^k u_{\perp}, \d^k v \rangle 
		+ \langle u_{\perp}, \d^{k-1} \tau \rangle + \langle u_{\perp}, q 
		\rangle, 
		%
		=  \langle \d^k u_{\perp}, \d^k v_{\perp} \rangle \\
		%
		B_{\gamma}(0, u_{\perp}, 0; \tau, v, p) &= \gamma^{-1} \langle 
		u_{\perp}, v - 
		v_{\mathfrak{H}} \rangle + \langle \d^k u_{\perp}, \d^k v \rangle = 
		\gamma^{-1} \langle u_{\perp}, v_{\perp} \rangle + \langle \d^k 
		u_{\perp}, \d^k v_{\perp} \rangle.
	\end{align*}
	Consequently, there holds
	\begin{align*}
		\lambda B_{\gamma}(0, u_{\perp}, 0; \tau, v, p) = \frac{\mu \gamma}{\mu 
		\gamma + 1} \left( \gamma^{-1} + \mu \right) \langle u_{\perp}, 
		v_{\perp} \rangle = \mu \langle u_{\perp}, v_{\perp} \rangle = A(0, 
		u_{\perp}, 0; \tau, v, p).
	\end{align*}
	Now let $\sigma_{\perp}$, $\nu$, and $\lambda$ be as in (iv). Then,
	\begin{align*}
		A(\sigma, \gamma \lambda^{-1} \d^{k-1} \sigma, 0; \tau, v, q) &= \langle 
		\d^{k-1} \sigma, v \rangle + \gamma \lambda^{-1} \langle \d^{k-1} \sigma, 
		\d^{k-1} \tau \rangle - \langle \sigma, \tau \rangle \\
		%
		&= \langle \d^{k-1} \sigma, v_{\perp} \rangle + \gamma \lambda^{-1} 
		\langle \d^{k-1} \sigma, \d^{k-1} \tau \rangle - \langle \sigma, \tau 
		\rangle, \\
		%
		 B_{\gamma}(\sigma, \gamma \lambda^{-1} \d^{k-1}\sigma, 0; \tau, v, q) &= 
		 \lambda^{-1} \langle \d^{k-1} \sigma, v - v_{\mathfrak{H}} \rangle + 
		 \langle \sigma, \tau \rangle +  \gamma \langle \d^{k-1} \sigma, 
		 \d^{k-1} \tau \rangle \\
		 %
		 &= \lambda^{-1} \langle \d^{k-1} \sigma, v_{\perp} \rangle + 
		 \langle \sigma, \tau \rangle +  \gamma \langle \d^{k-1} \sigma, 
		 \d^{k-1} \tau \rangle.
	\end{align*}
	Consequently, there holds
	\begin{align*}review
		\lambda B_{\gamma}(\sigma, \gamma \lambda^{-1} \d^{k-1}\sigma, 0; \tau, 
		v, q) &= \langle \d^{k-1} \sigma, v_{\perp} \rangle + 
		\lambda \left( \langle \sigma, \tau \rangle +  \gamma \langle \d^{k-1} 
		\sigma, \d^{k-1} \tau \rangle \right) \\
		%
		&= \langle \d^{k-1} \sigma, v_{\perp} \rangle + 
		\lambda \left(1 + \nu \gamma \right) \langle \sigma, \tau \rangle \\
		&= \langle \d^{k-1} \sigma, v_{\perp} \rangle + 
		\nu \gamma \langle \sigma, \tau \rangle \\
		&= \langle \d^{k-1} \sigma, v_{\perp} \rangle +  (\nu \gamma  
		\lambda^{-1} 
		- 1) \langle \sigma, \tau \rangle \\
		&= A(\sigma, \gamma \lambda^{-1} \d^{k-1} \sigma, 0; \tau, v, q).
	\end{align*}

	We now verify that (i-iv) contain $\dim V^{k-1} + \dim V^{k} + \dim 
	\mathfrak{H}^k$ linearly independent (L.I.) eigenvectors, and so (i-iv) 
	classify all eigenpairs of \cref{eq:hodge-laplace-evals}. It is immediate 
	that (i) contains $\dim V^{k-1}$ L.I. eigenfunctions and (ii) contains $\dim 
	\mathfrak{H}^k$ L.I. eigenfunctions for each value of $\lambda \in \{-1, 
	1\}$. Since 
	\cref{eq:hodge-laplace-u-evals-aux,eq:hodge-laplace-sigma-evals-aux} are 
	well-defined, SPD eigenvalue problems, there are $\dim \mathfrak{Z}^{k, 
	\perp}$ L.I. eigenfunctions in (iii) and $\dim \mathfrak{Z}^{k-1, \perp}$ 
	L.I. eigenfunctions in (iv). Thus, there are
	\begin{align*}
		\dim V^{k-1} + \dim \mathfrak{H}^k + \dim \mathfrak{Z}^{k, \perp} + \dim 
		\mathfrak{Z}^{k-1, \perp} + \dim \mathfrak{H}^k = \dim V^{k-1} + \dim 
		V^{k} + \dim \mathfrak{H}^k
	\end{align*}
	L.I. eigenfunctions, which completes the proof.
\end{proof}




