\section*{Appendix 4}

\textbf{Expected value of the $\mathcal{CB}$}

\begin{equation}
\mathbb{E}_{\mathcal{CB}(b)}[\sigma] = \int \sigma \frac{ e^{b \sigma} }{ 2sinh(b) } d \sigma
= \frac{ b \left( \frac{(b-1)e^b}{b^2} + \frac{(b+1)e^-b}{b^2} \right) }{ 2sinh(b) } \\
= \coth(b) - \frac{1}{b}
\end{equation}

