\section{Ollivier–Ricci curvature of hypergraphs}\label{basic}

Let $\Gamma=(V,H,\bm{w})$ be a weighted undirected hypergraph, where $V=(x_1,x_2,\cdots,x_n)$ is vertex set, $H=(h_1,h_2,\cdots,h_m)$ is the hyperedge set, and $\bm{w}=(w_{h_1},w_{h_2},\cdots,w_{h_m})\in\mathbb{R}^m_+$ is the vector of weights on hyperedges. When referring to generic vertices without specification, we omit subscripts and denote nodes by $u$ and $v$. For two vertices $u, v\in V$, if there exists a hyperedge $h_l\in H$ such that both of them are contained within $h_l$, we say that $u$ and $v$ are adjacent and denote this relationship as $u\sim v$. Furthermore, if there is a sequence of hyperedges $\{h_{l_1},h_{l_2},\cdots,h_{l_s}\}$ ($s\leq m$) such that $u\in h_{l_1}$, $v\in h_{l_s}$ and $h_{l_k}\cap h_{l_{k+1}}\neq\emptyset$ for $1\leq k\leq s-1$, then vertices $u$ and $v$ are connected by the hyperpath $\gamma=\{h_{l_1},h_{l_2},\cdots,h_{l_s}\}$. If each pair of two different vertices in a hypergraph $\Gamma$ can be connected by a hyperpath, we call $\Gamma$ a connected hypergraph. Unless otherwise specified, any mention of hypergraphs refers to undirected, connected hypergraphs so that we can provide a definition of distance. The distance between two vertices $u, v\in V$ is given by
\begin{equation}\label{distance def}
	d(u,v):=\inf_\gamma\sum_{h\in\gamma}w_h,
\end{equation}
where the infimum is taken over all paths $\gamma$ connecting $u$ and $v$. Since hyperedges can connect multiple vertices, we need to establish a definition of length for a hyperedge $h_l=\{x_{l_1},x_{l_2},\cdots,x_{l_s}\}\in H$ as follow
\begin{equation}\label{distance hyperedge}
	d(h):=\sum_{1\leq i<j\leq s}d(x_{l_i},x_{l_j}).
\end{equation}
For the case $k=2$, which indicates that the (hyper)edge contains only two vertices, the length of $h=\{u,v\}$ is $d(h)=d(u,v)$. By \cite[Lemma 2.1.]{Ma2024modified}, we have the following lemma concerning distance.
\begin{lemma}\label{distence lem}
	For any two fixed vertices $u, v\in V$, the distance $d(u,v)$ is locally Lipschitz in $\mathbb{R}^m_+$ with respect to $\bm{w}=(w_{h_1},w_{h_2},\cdots,w_{h_m})$, i.e., for any $\bm{w},  \widetilde{\bm{w}}\in\mathbb{R}^m_+$, if $d$ and $\widetilde{d}$ are two distance functions determined by $\bm{w}$ and
	$\widetilde{\bm{w}}$ respectively, then there holds
	\begin{equation*}
		\vert d(u,v)-\widetilde{d}(u,v)\vert\leq\sqrt{m}\vert\bm{w}-\widetilde{\bm{w}}\vert.
	\end{equation*}
\end{lemma}
As the foundation for developing curvature flows on hypergraphs, we first present a rigorous definition of the Ollivier-Ricci curvature of hyperedges, which will serve as the key geometric quantity in subsequent evolutionary equations.
\begin{definition}\label{curvature def}
	For a weighted hypergraph $\Gamma=(V,H,\bm{w})$, $\forall h_l=\{x_{l_1},x_{l_2},\cdots,x_{l_s}\}\in H$, we define the Ollivier-Ricci curvature of the hyperedge $h_l$ as
	\begin{equation}\label{curvature eq}
		\kappa_\alpha(h_l):=1-\frac{W_{h_l}}{d(h_l)},
	\end{equation}
	where $\alpha\in[0, 1]$, the probability measure $\mu_{x_{l_i}}^\alpha$ of $x_{l_i}\in h_l$ is defined on $V$ as follows
	\begin{equation}\label{measure eq}
		\mu_{x_{l_i}}^\alpha(z):=\left\{
		\begin{aligned}
			&\  \alpha, &&\text{if } z=x_{l_i},\\
			&\  (1-\alpha)\sum_{h': x_{l_i},z\in h'}\frac{1}{\vert h'\vert-1}\frac{w_{h'}}{\sum\limits_{h'':x_{l_i}\in h''}w_{h''}}, &&\text{if } z\neq x_{l_i} \text{ and } z\sim x_{l_i},\\
			&\  0, &&\text{otherwise},
		\end{aligned} \qquad \forall z\in V,
		\right.
	\end{equation}
	$W_{h_l}:=\sum_{1\leq i<j\leq s}W(\mu_{x_{l_i}}^\alpha,\mu_{x_{l_j}}^\alpha)$ and $W(\mu_{x_{l_i}}^\alpha,\mu_{x_{l_j}}^\alpha)$ is the $1$-Wasserstein distance between these two discrete measures defined as follows
	\begin{equation}\label{Wasserstein def}
		W(\mu_{x_{l_i}}^\alpha,\mu_{x_{l_j}}^\alpha):=\inf_{A}\sum_{u,v\in V}A(u,v)d(u,v),
	\end{equation}
	where $A: V\times V\to [0,1]$ runs over all maps satisfying
	\begin{equation*}
		\left\{
		\begin{aligned}
			&\  \sum_{v\in V}A(u,v)=\mu_{x_{l_i}}^\alpha(u),\\
			&\  \sum_{u\in V}A(u,v)=\mu_{x_{l_j}}^\alpha(v).
		\end{aligned}
		\right.
	\end{equation*}
\end{definition}

\begin{remark}\label{graph Lip re}
	For a weighted hypergraph $\Gamma=(V,H,\bm{w})$, we note that:

	(i) If $k=2$, i.e., there is a hyperedge has exactly two vertices $h=\{u,v\}$, the Ollivier-Ricci curvature (\ref{curvature eq}) formally coincides with the graph edge curvature as follows
	\begin{equation*}
		\kappa_\alpha(h):=1-\frac{W(\mu_u^\alpha,\mu_v^\alpha)}{d(u,v)}.
	\end{equation*}
	However, the probability measure (\ref{measure eq}) may differ from those in the graph case unless all hyperedges contain exactly two vertices.

	(ii) By Definition \ref{curvature def} and \cite{Ma2024evolution}, it is clear that the probability measure $\mu_{x_i}^\alpha$ is locally Lipschitz in $\mathbb{R}^m_+$ with respect to $\bm{w}$ for any $x_i\in V$.
\end{remark}
We next introduce the concept of $1$-Lipschitz functions on hypergraphs and a fundamental principle in optimal transport theory, namely the Kantorovich-Rubinstein duality.
\begin{definition}
	Let $\Gamma=(V,H,\bm{w})$ be a weighted hypergraph. A function $f: V\to\mathbb{R}$ is said to be $1$-Lipschitz if
	\begin{equation*}
		\vert f(u)-f(v)\vert\leq d(u, v),
	\end{equation*}
	for all $u,v\in V$. The set of all $1$-Lipschitz functions on $V$ is denoted by $1$-Lip.
\end{definition}

\begin{proposition}\label{Kantorovich duality}
	\emph{(Kantorovich-Rubinstein duality, \cite{Bourne2018ollivier, Villani2021topics})} Let $\Gamma=(V,H,\bm{w})$ be a weighted hypergraph and  $\mu_{x_i}^\alpha, \mu_{x_j}^\alpha$ be two probability measures on $V$. Then
	\begin{equation*}
		W(\mu_{x_i}^\alpha,\mu_{x_j}^\alpha)=\sup_{\phi\in 1\text{-Lip}}\sum_{z\in V}\phi(z)\left(\mu_{x_i}^\alpha(z)-\mu_{x_j}^\alpha(z)\right).
	\end{equation*}
\end{proposition}

