\section{Ricci flow on hypergraphs}\label{result}

In this section, we study a flow governing the evolution of weight $\bm{w}=(w_{h_1},w_{h_2},\cdots,w_{h_m})$ over time. To begin with, for any $h\in H$, we note that since both $W_h$ and $d_h$ depend on $\bm{w}$, they can be treated as functions of $\bm{w}$, denoted by $W_h(\bm{w})$ and $d_h(\bm{w})$, respectively. The Ricci flow on hypergraphs is
\begin{equation}\label{flow eq}
	\left\{
	\begin{aligned}
		&\  w_{h_l}'(t)=-d(h_l)\kappa_\alpha(h_l),\\
		&\  h_l=\{x_{l_1},x_{l_2},\cdots,x_{l_s}\}\in H,\\
		&\  w_{h_l}(0)=w_{0,l},
	\end{aligned}
	\right.
\end{equation}
where $t\geq0$ and $l=1,2,\cdots,m$. The right-hand side of the above Ricci flow depends on $\bm{w}$, specifically given by
$$-d(h_l)\kappa_\alpha(h_l)=W_{h_l}(\bm{w})-d(h_l)(\bm{w})=\sum_{1\leq i<j\leq s}\left(W(\mu_{x_{l_i}}^\alpha, \mu_{x_{l_j}}^\alpha)(\bm{w})-d(x_{l_i},x_{l_j})(\bm{w})\right).$$
To prove the long-time existence of the flow, we first introduce the following lemma.
\begin{lemma}\label{Wasserstein lem}
	Let $\Gamma=(V,H,\bm{w})$ be a weighted hypergraph and $h_l=\{x_{l_1},x_{l_2},\cdots,x_{l_s}\}\in H$. For any two different vertices $x_{l_i}, x_{l_j} \in h_l$, the $1$-Wasserstein distance $W(\mu_{x_{l_i}}^\alpha, \mu_{x_{l_j}}^\alpha)(\bm{w})$ is locally Lipschitz in $\mathbb{R}^m_+$ with respect to $\bm{w}$. In addition, we have that $W_{h_l}(\bm{w})-d(h_l)(\bm{w})$ is also locally Lipschitz in $\mathbb{R}^m_+$ with respect to $\bm{w}$.
\end{lemma}

\begin{proof}
	For any two fixed vertices $x_{l_i}, x_{l_j} \in h_l$ and two vector of weights  $\bm{w}=(w_{h_1},w_{h_2},\cdots,w_{h_m})$, $\widetilde{\bm{w}}=(\widetilde{w}_{h_1},\widetilde{w}_{h_2},\cdots,\widetilde{w}_{h_m})$ in $\mathbb{R}^m_+$, assume that $W(\mu_{x_{l_i}}^\alpha, \mu_{x_{l_j}}^\alpha)$ and $W(\widetilde{\mu}_{x_{l_i}}^\alpha, \widetilde{\mu}_{x_{l_j}}^\alpha)$ are the Wasserstein distances determined by $\bm{w}$ and $\widetilde{\bm{w}}$, respectively, as well as the probability measures $\mu, \widetilde{\mu}$ and the distances $d,\widetilde{d}$. Since the cardinality of the hyperedge set $H$ is finite, there exist some constants $M>0$ and $\delta>0$ such that for each $l=1,2,\cdots,m$, we have
	\begin{equation*}
		M^{-1}\leq w_{h_l}\leq M,\  M^{-1}\leq \widetilde{w}_{h_l}\leq M,\  \vert w_{h_l}-\widetilde{w}_{h_l}\vert\leq\delta^{-1}.
	\end{equation*}
	On the other hand, 	
	since the cardinality of the vertices set $V$ is finite, by Proposition \ref{Kantorovich duality}, there exists some $f\in1\text{-Lip}$ such that
	\begin{equation*}
		W(\mu_{x_{l_i}}^\alpha, \mu_{x_{l_j}}^\alpha)(\bm{w})=\sum_{z\in V}f(z)\left(\mu_{x_{l_i}}^\alpha(z,\bm{w})-\mu_{x_{l_j}}^\alpha(z,\bm{w})\right).
	\end{equation*}
	It follows from Lemma \ref{distence lem} that for any $u,v\in V$, we have
	\begin{equation*}
		\frac{\widetilde{d}(u,v)}{d(u,v)-\widetilde{d}(u,v)}\leq\sqrt{m}M\vert\bm{w}-\widetilde{\bm{w}}\vert.
	\end{equation*}
	Therefore, the function
	\begin{equation*}
		\widetilde{f}(u)=\frac{f(u)}{1+\sqrt{m}M\vert\bm{w}-\widetilde{\bm{w}}\vert}, \quad \forall u\in V,
	\end{equation*}
	satisfies
	\begin{equation*}
		\vert \widetilde{f}(u)-\widetilde{f}(v)\vert=\frac{\vert f(u)-f(v)\vert}{1+\sqrt{m}M\vert\bm{w}-\widetilde{\bm{w}}\vert}\leq\widetilde{d}(u,v).
	\end{equation*}
	i.e. $\widetilde{f}\in1\text{-}\widetilde{\text{Lip}}$.
	By Remark \ref{graph Lip re}(ii), there exists a constant $C>0$, which only depends on the constants $M$ and $\delta$, such that
	\begin{equation*}
		\vert\mu_{x_{l_i}}^\alpha(u,\bm{w})-\widetilde{\mu}_{x_{l_i}}^\alpha(u,\widetilde{\bm{w}})\vert\leq C\vert\bm{w}-\widetilde{\bm{w}}\vert, \quad \forall x_{l_i}\in h_l, u\in V.
	\end{equation*}
	Without loss of generality, assume that $W(\mu_{x_{l_i}}^\alpha, \mu_{x_{l_j}}^\alpha)(\bm{w})\geq W(\widetilde{\mu}_{x_{l_i}}^\alpha, \widetilde{\mu}_{x_{l_j}}^\alpha)(\widetilde{\bm{w}})$, and we have
	\begin{equation*}
		\begin{aligned}
			&W(\mu_{x_{l_i}}^\alpha, \mu_{x_{l_j}}^\alpha)(\bm{w})- W(\widetilde{\mu}_{x_{l_i}}^\alpha, \widetilde{\mu}_{x_{l_j}}^\alpha)(\widetilde{\bm{w}})\\
			\leq\ &\sum_{z\in V}f(z)\left(\mu_{x_{l_i}}^\alpha(z,\bm{w})-\mu_{x_{l_j}}^\alpha(z,\bm{w})\right)-\sum_{z\in V}\widetilde{f}(z)\left(\widetilde{\mu}_{x_{l_i}}^\alpha(z,\widetilde{\bm{w}})-\widetilde{\mu}_{x_{l_j}}^\alpha(z,\widetilde{\bm{w}})\right)\\
			\leq\ &\sum_{z\in V}\vert f(z)\vert\left(\vert\mu_{x_{l_i}}^\alpha(z,\bm{w})-\widetilde{\mu}_{x_{l_i}}^\alpha(z,\widetilde{\bm{w}})\vert+\vert\mu_{x_{l_j}}^\alpha(z,\bm{w})-\widetilde{\mu}_{x_{l_j}}^\alpha(z,\widetilde{\bm{w}})\vert\right)\\
			&+\sum_{z\in V}\vert f(z)-\widetilde{f}(z)\vert\vert\widetilde{\mu}_{x_{l_i}}^\alpha(z,\widetilde{\bm{w}})-\widetilde{\mu}_{x_{l_j}}^\alpha(z,\widetilde{\bm{w}})\vert\\
			\leq\ &\sum_{z\in V}2C\vert\bm{w}-\widetilde{\bm{w}}\vert\vert f(z)\vert+\sum_{z\in V}\frac{\sqrt{m}M\vert\bm{w}-\widetilde{\bm{w}}\vert}{1+\sqrt{m}M\vert\bm{w}-\widetilde{\bm{w}}\vert}\vert f(z)\vert\left(\widetilde{\mu}_{x_{l_i}}^\alpha(z,\widetilde{\bm{w}})+\widetilde{\mu}_{x_{l_j}}^\alpha(z,\widetilde{\bm{w}})\right)\\
			\leq\ &2n(C+\sqrt{m}M)\Vert f\Vert_{L^\infty(V)}\vert\bm{w}-\widetilde{\bm{w}}\vert.
		\end{aligned}
	\end{equation*}
	This completes the proof of the Lemma.
\end{proof}

Next, we present the main theorem of this section, which guarantees the long-time existence of solutions to the flow (\ref{flow eq}).
\begin{theorem}
	Let $\Gamma=(V,H,\bm{w}_0)$ be a weighted hypergraph with an initial weight $\bm{w}_0\in \mathbb{R}^m_+$. Then there exists a unique solution $\bm{w}(t)$ of the flow (\ref{flow eq}) for all time $t\in[0,\infty)$, where $\bm{w_0}=(w_{0,1},w_{0,2},\cdots,w_{0,m})$, and $\bm{w}(t)=(w_{h_1}(t),w_{h_2}(t),\cdots,w_{h_m}(t))$.
\end{theorem}

\begin{proof}
	We first note that for any $\bm{w}_0\in\mathbb{R}^m_+$, the evolution of weights (\ref{flow eq}) is a system of ordinary differential equations as follows
	\begin{equation}\label{system eq}
		\left\{
		\begin{aligned}
			&\  \bm{w}'(t)=\bm{W}_H(t)-\bm{d}_H(t),\\
			&\  \bm{w}(0)=\bm{w}_0,
		\end{aligned}
		\right.
	\end{equation}
	where for simplicity, we denote $\left(W_{h_1}(t)-d(h_1)(t),W_{h_2}(t)-d(h_2)(t),\cdots,W_{h_m}(t)-d(h_m)(t)\right)$ by $\bm{W}_H(t)-\bm{d}_H(t)$. By Lemma \ref{Wasserstein lem}, it is clear that $\bm{W}_H-\bm{d}_H$ is locally Lipschitz with respect to $\bm{w}$. Through the classical theorem on the existence and uniqueness of solutions to ordinary differential systems, there exists a constant $T>0$ such that the system (\ref{system eq}) has a unique solution $\bm{w}(t)$ on $[0,T]$.

	Let
	\begin{equation*}
		T^*:=\sup\left\{T>0: (\ref{system eq}) \text{ has a unique solution on } [0,T]\right\}
	\end{equation*}
	and define
	\begin{equation*}
		\psi(t):=\min\{w_{h_1}(t),w_{h_2}(t),\cdots,w_{h_m}(t)\}, \quad \Psi(t):=\max\{w_{h_1}(t),w_{h_2}(t),\cdots,w_{h_m}(t)\}.
	\end{equation*}
	Next, we prove that $T^*$ must be infinite. Suppose not, then according to the ODE theory, we have
	\begin{equation}\label{contradiction eq}
		\liminf\limits_{t\to T^*}\psi(t)=0, \quad\text{or}\quad \limsup\limits_{t\to T^*}\psi(t)=\infty.
	\end{equation}
	For any hyperedge $h_l=(x_{l_1},x_{l_2},\cdots,x_{l_s})\in H$, by the definition (\ref{distance hyperedge}), the system (\ref{system eq}) can be rewritten as follows.
	\begin{equation*}
		\begin{aligned}
			w_{h_l}'(t)&=\sum_{1\leq i<j\leq s}\left(W(\mu_{x_{l_i}}^\alpha, \mu_{x_{l_j}}^\alpha)-d(x_{l_i},x_{l_j})\right)\\
			&\geq-\sum_{1\leq i<j\leq s}d(x_{l_i},x_{l_j})\\
			&\geq-\frac{s(s-1)}{2}w_{h_l}(t).
		\end{aligned}
	\end{equation*}
	Thus, we have
	\begin{equation}\label{weight leq}
		w_{h_l}(t)\geq w_{h_l}(0)e^{-\frac{s(s-1)}{2}T^*}, \quad \forall t\in[0,T^*).
	\end{equation}

	On the other hand, by definitions (\ref{distance def}) and (\ref{Wasserstein def}), for the two probability measures $\mu_{x_{l_i}}^\alpha$ and $\mu_{x_{l_j}}^\alpha$, we have
	\begin{equation}\label{Ww neq}
		\begin{aligned}
			W(\mu_{x_{l_i}}^\alpha, \mu_{x_{l_j}}^\alpha)&=\inf_{A}\sum_{u,v\in V}A(u,v)d(u,v)\\
			&\leq\left(\sum_{u,v\in V}B(u,v)\right)\left(\sum_{h\in\gamma}w_h\right)\\
			&=\sum_{h\in H}w_h,
		\end{aligned}
	\end{equation}
	where $B(u,v)$ is a coupling between $\mu_{x_i}^\alpha$ and $\mu_{x_j}^\alpha$ satisfying $\sum_{u,v\in V}B(u,v)=1$. It follows from (\ref{Ww neq}) that
	\begin{equation*}
		\begin{aligned}
			\frac{d}{dt}\sum_{h_l\in H}w_{h_l} &=\sum_{h_l\in H}\sum_{1\leq i<j\leq s}\left(W(\mu_{x_{l_i}}^\alpha, \mu_{x_{l_j}}^\alpha)-d(x_{l_i},x_{l_j})\right)\\
			&\leq\sum_{h_l\in H}\sum_{1\leq i<j\leq s}W(\mu_{x_{l_i}}^\alpha, \mu_{x_{l_j}}^\alpha)\\
			&\leq nm \sum_{h_l\in H}w_{h_l}.
		\end{aligned}
	\end{equation*}
	Hence, we have
	\begin{equation}\label{weight req}
		\sum_{h_l\in H}w_{h_l}(t)\leq e^{nmT^*}\sum_{h_l\in H}w_{h_l}(0), \quad \forall t\in[0,T^*).
	\end{equation}
	Combining (\ref{weight leq}) and (\ref{weight req}), we have
	\begin{equation}\label{contradiction weight}
		\psi(0)e^{-\frac{s(s-1)}{2}T^*}\leq\psi(t)\leq\Psi(t)\leq\sum_{h_l\in H}w_{h_l}(t)\leq e^{nmT^*}\sum_{h_l\in H}w_{h_l}(0), \quad \forall t\in[0,T^*),
	\end{equation}
	which contradicts (\ref{contradiction eq}). Throughout this paper, we use $s$ to denote a generic constant representing the cardinality of a hyperedge (i.e., the number of vertices it contains). Here in (\ref{contradiction weight}), it specifically refers to the vertex count of the minimally weighted hyperedge. Now the contradiction implies that $T^*$ can be extended to infinity, and consequently, we prove that there exists a unique solution $\bm{w}(t)$ of the flow (\ref{flow eq}) for all time $t\in[0,\infty)$.
\end{proof}

