\section{Numerical implementation}
\label{app:Implementation}
For the finite element discretisation, concentrations and the electrolyte potential are discretised throughout the concrete as:
\begin{equation}
    C_\pi = \sum_{el} \mathbf{N}^{el} \mathbf{C}_\pi^{el} \qquad \qquad \varphi = \sum_{el} \mathbf{N}^{el} \mathbf{\upvarphi}^{el}
\end{equation}
using quadratic Bernstein shape functions $\mathbf{N}^{el}$ for the tetrahedral elements. In addition to these $7+1$ nodal degrees of freedom for the concentrations and electrolyte potential, the metal potential is added as a singular degree of freedom $E_\text{m}$.

Using this discretisation, the discretised weak form of the Nernst-Planck equation from \cref{eq:massconserv} is given as:
\begin{equation} \begin{split}
    \mathbf{f}_{\text{c}\pi} = &\int_{\Omega} \frac{\phi S^*}{\Delta t}\mathbf{N}^T \mathbf{N} \left(\mathbf{C}_\pi^{t+\Delta t} - \mathbf{C}_\pi^t\right)\;\text{d}\Omega \\ &+ \int_{\Omega} D_\pi^\text{eff} \left(\bm{\nabla}\mathbf{N}\right)^T\bm{\nabla}\mathbf{N}\mathbf{C}_\pi^{t+\Delta t} \; \text{d}\Omega \\
    &+ \int_{\Omega} \frac{D_\pi^\text{eff} z_\pi F}{RT} \left(\bm{\nabla}\mathbf{N}\right)^T \left(\mathbf{N} \mathbf{C}_\pi^{t+\Delta t}\right) \bm{\nabla}\mathbf{N} \bm{\upvarphi}^{t+\Delta t}\;\text{d}\Omega \\ & - \phi S^* \mathbf{R}_{\pi} + \mathbf{\upnu}_{\pi} - \int_{\Gamma} \mathbf{N} j_\pi \; \text{d}\Gamma = \mathbf{0}
\end{split} \label{eq:f_c} \end{equation} 
where the boundary flux $j_\pi$ and the reaction flux $\bm{\nu}_\pi$ interact with the full boundary (in contrast to these being corrected for the porosity). The volume reactions are integrated using a lumped integration scheme \citep{Schellekens1993, Hageman2020a, Hageman2023}, using lumped integration weights $W^{nd}$ associated with each node, providing the reaction terms as:
\begin{subequations}
\begin{align}
    \begin{split}
    \mathbf{R}_{\text{H}^+} &= \sum_{nd} W^{nd} \bm{i}^{nd} \Big(k_{\text{eq}}\left(K_\text{w}-\frac{\mathbf{C}_{\text{H}^+}^{t+\Delta t}\mathbf{C}_{\text{OH}^-}^{t+\Delta t}}{C_\text{ref}^2}\right) \\ &+ \left( k_{\text{fe}}\frac{\mathbf{C}_{\text{Fe}^{2+}}^{t+\Delta t}}{C_\text{ref}}-k'_{\text{fe}}\frac{\mathbf{C}_{\text{FeOH}^+}^{t+\Delta t}\mathbf{C}_{\text{H}^+}^{t+\Delta t}}{C_\text{ref}^2} + k_{\text{feoh}} \frac{\mathbf{C}_{\text{FeOH}^+}}{C_\text{ref}} \right) \Big) 
    \end{split}\label{eq:RH} \\
    \mathbf{R}_{\text{OH}^-} &= \sum_{nd} W^{nd} \bm{i}^{nd} k_{\text{eq}} \left(K_\text{w}-\frac{\mathbf{C}_{\text{H}^+}^{t+\Delta t}\mathbf{C}_{\text{OH}^-}^{t+\Delta t}}{C_\text{ref}^2}\right) \label{eq:ROH} \\
    \mathbf{R}_{\text{Fe}^{2+}} &= \sum_{nd} W^{nd} \bm{i}^{nd} \left(-k_{\text{fe}} \frac{\mathbf{C}_{\text{Fe}^{2+}}}{C_\text{ref}} + k_{\text{fe}}' \frac{\mathbf{C}_{\text{FeOH}^+}^{t+\Delta t}\mathbf{C}_{\text{H}^+}^{t+\Delta t}}{C_\text{ref}^2}\right) \label{eq:RFE} \\
    \begin{split}
    \mathbf{R}_{\text{FeOH}^+} &=\sum_{nd} W^{nd} \bm{i}^{nd} \Big( k_{\text{fe}}\frac{\mathbf{C}_{\text{Fe}^{2+}}^{t+\Delta t}}{C_\text{ref}} \\ &-k'_{\text{fe}} \frac{\mathbf{C}_{\text{FeOH}^+}^{t+\Delta t}\mathbf{C}_{\text{H}^+}^{t+\Delta t}}{C_\text{ref}^2} - k_{\text{feoh}} \frac{\mathbf{C}_{\text{FeOH}^+}}{C_\text{ref}}  \Big) \end{split}  \label{eq:RFEOH} \\
    \mathbf{R}_{\text{O}_2}&=\mathbf{R}_{\text{Na}^+} = \mathbf{R}_{\text{Cl}^-} = \mathbf{0} \label{eq:RNACL}
\end{align}
\end{subequations}
where the used concentrations correspond to the nodal values. The allocation vectors $\mathbf{i}^{nd}$ are used to allocate the contributions to the corresponding nodes. The weight vectors for the bulk and surface reactions are determined in a standard manner as:
\begin{equation}
    \mathbf{W} = [W^{nd_1}\; W^{nd_2} \; ... ] = \int_{\Omega} \mathbf{N}\;\text{d}\Omega \qquad \mathbf{W}^{\text{surf}} = \int_{\Gamma} \mathbf{N}\;\text{d}\Gamma
\end{equation}
and the surface reaction rates are integrated in a similar manner, 
\begin{equation}
    \mathbf{\upnu}_{\pi} = \sum_{nd} W^{\text{surf},nd} \mathbf{i}^{nd} \nu_\pi (C^{t+\Delta t})
\end{equation}

The discretised weak form of the electroneutrality condition, \cref{eq:electroneutrality}, is given by:
\begin{equation}
    \bm{f}_\varphi = \int_{\Omega} \sum_\pi z_\pi  \mathbf{N}_\varphi^T\mathbf{N}_\text{C}\mathbf{C}_\pi^{t+\Delta t} \; \text{d}\Omega = \mathbf{0} \label{eq:f_phi}
\end{equation}

Finally, the current conservation condition imposed to emulate natural corrosion, \cref{eq:current_conservation}, is discretised and integrated using a lumped scheme as:
\begin{equation}
    f_{E_\text{m}} = \sum_{nd} W^{\text{surf},nd} \left(2F\nu_\text{c}+ 2F\nu_\text{h} + 4F\nu_\text{o}  \right) = 0 
\end{equation}

These three discretised equations are solved in a monolithic manner using an iterative scheme:
\begin{equation}
    \begin{bmatrix} \frac{\partial \mathbf{f}_{\text{c}\pi}}{\partial \mathbf{C}_{\pi}}  &  \frac{\partial \mathbf{f}_{\text{c}\pi}}{\partial E_\text{m}} & \frac{\partial \mathbf{f}_{\text{c}\pi}}{\partial \mathbf{\upvarphi}} \\ 
    \frac{\partial f_{E_\text{m}}}{\partial \mathbf{C}_{\pi}} & \frac{\partial f_{E_\text{m}}}{\partial E_\text{m}} & \frac{\partial f_{E_\text{m}}}{\partial \mathbf{\upvarphi}} \\ 
    \frac{\partial \mathbf{f}_{\varphi}}{\partial \mathbf{C}_{\pi}} & 0 & 0\end{bmatrix}_i
    \begin{bmatrix} \text{d} \mathbf{C}_{\pi}  \\ \text{d} E_\text{m} \\ \text{d} \bm{\upvarphi} \end{bmatrix}_{i+1} 
    = - \begin{bmatrix} \mathbf{f}_{\text{c}\pi}  \\ f_{E_\text{m}} \\ \mathbf{f}_\varphi \end{bmatrix}_{i}
\end{equation}
which is iterated until a solution is obtained that satisfies the convergence criteria:
\begin{equation}
\begin{split}
     &\frac{\epsilon}{\epsilon_0}<10^{-12} \qquad \text{or} \qquad \epsilon_i<10^{-15} \qquad \\ &\text{where} \qquad \epsilon_i = \left| \begin{bmatrix} \text{d} \mathbf{C}_{\pi}  & \text{d} E_\text{m} & \text{d} \bm{\upvarphi} \end{bmatrix}_{i+1} \cdot \begin{bmatrix} \mathbf{f}_{c\pi}  & f_{E_\text{m}} & \mathbf{f}_\varphi \end{bmatrix}_{i+1} \right|
\end{split}
\end{equation}

\section{Effect of beam length}
\label{App:Geo}
Throughout this work, we have focused on variations in the saturation, conductivity, and porosity of the concrete, considering a single corrosion pit on a concrete beam with a set length. One of the findings of this research is that the oxygen reaction occurs over the complete surface of the rebar, while the hydrogen reaction is more localised. In this appendix, we present results for a range of beam lengths (ranging from $0.05-0.3\;\text{m}$), confirming that this conclusion holds for other geometries as well. In these studies, the porosity of the concrete is kept constant at $5\%$, the $\text{Cl}^\text{-}$ concentration at $C_{\text{Cl}^-}=10\;\text{mol}/\text{m}^3$, and the concrete is considered to be fully water-saturated. 

