\title{Proportional Representation in Practice:\\
Quantifying Proportionality in Ordinal Elections
} 


\author{
Tuva Bardal\footnote{University of Warwick, Coventry, UK; email: tuva.bardal@warwick.ac.uk}
\and Markus Brill\footnote{University of Warwick, UK; email: markus.brill@warwick.ac.uk} 
