\subsection{Main Results}
Let $N(t), t \geq 0$ denote  the stochastic process of the number of active updates at time $t$. 
When each update has a fixed size in memory,  $N(t)$ is proportional to the memory footprint of the RCU updating process. 
% We now state the main results of our RCU analysis of a memoryless updating system.  
Theorem \ref{thm:en-ub1} desribes the memory footprint $\E{N}$ and the average age $\E{\age}$ of an update in memory in terms of the system parameters $\lambda$, $\mu$ and $\alpha$.
% (a) an exact expression for the memory footprint $\E{N}$, (b) a pair of simple upper bounds to $\E{N}$, and (c)   
% the average age $\E{\age_1}$ of updates stored in shared memory.
\begin{theorem}\label{thm:RCU}
For the memoryless RCU model in which updates are written as a rate $\alpha$ Poisson process, and read requests arrive as a rate $\lambda$ Poisson process with independent exponential $(\mu)$ service times: 
\begin{enumerate}
\item[(a)] The memory footprint $\E{N}$ satisfies
\begin{align}
    \E{N} &=
     1 + \sum_{k = 1}^{\infty}
    \sum_{j=0}^\infty \frac{b_k^j e^{-b_k}}{j!}\parfrac{j}{\alpha/\mu + j}.\eqnlabel{EN2}
\end{align}
where $ b_k = \lambda q^k/\mu$ with $q =\alpha/(\alpha+\mu)$.
    %and the lower incomplete gamma function is defined as  
%$\gamma(s,x) = \int_{0}^{x} t^{s-1} e^{-t}\,dt$.
\item[(b)] \label{thm:en-ub1} 
\begin{align}
    \E{N} 
    &\leq 1 +  \sum_{k =1}^\infty \frac{q^k}{q^k+\alpha/\lambda}\eqnlabel{en-ub1}\\
&\le 1 + {\lambda}/{\mu}. \eqnlabel{en-ub2}
\end{align}

\item[(c)] \label{thm:avg-age} 
The average age of the current update in memory is
\begin{equation}
    \E{\age} = {2}/{\alpha}. \label{eq:avg-age}
\end{equation}
\end{enumerate}
\end{theorem}


