    \frac{\E{J_k}}{\alpha/\mu +\E{J_k}}
    =1 + \sum_{k = 1}^{\infty}
    \frac{b_k}{\alpha/\mu +b_k}, \nn
    &=1 + \sum_{k = 1}^{\infty}
    \frac{q^k}{\alpha/\lambda +q^k}.\eqnlabel{ENUB1}
\end{align}
Since $q^k\ge 0$, it follows from \eqnref{ENUB1} that 
\begin{align}
    \E{N}\le 1+\sum_{k=1}^\infty \frac{\lambda}{\alpha}q^k
    =1+\frac{\lambda q}{\alpha(1-q)}
    =1+\frac{\lambda}{\mu}.
    \eqnlabel{ENUB2}
\end{align}

\subsection{Proof of Theorem~\ref{thm:RCU}(c)}
Fig.~\ref{fig:age} represents a sample age evolution in the unconstrained write model with $W_n$ denoting the exponential $(\alpha)$ write time of the $n$th update. We represent the area under sawtooth waveform as the concatenation of the polygon areas $\tilde{Q_{1}}, Q_{2}, \ldots, Q_{n}, \ldots$. The average age is
\begin{align}\eqnlabel{EQoverEW}
    \age = \frac{\E{Q_n}}{\E{W_n}}
\end{align}
where
\begin{align}
    Q_{n} &= \frac{(W_{n-1} + W_{n})^{2}}{2} - \frac{W^{2}_{n}}{2}
 = \frac{W_{n-1}^2 + W_{n-1}W_{n}}{2}.
\end{align}
Since $\E{W_n}=1/\alpha$ and $\E{W_n^2}=2/\alpha^2$, %independence of the $W_n$ implies 
%the average area is
\begin{align}
    \E{Q_{n}} &= \frac{1}{2}\E{W_{n-1}^2} + \E{W_{n-1}}\E{W_n}
%= \frac{1}{\alpha^2} + \frac{1}{\alpha^2}
    = \frac{2}{\alpha^2}\eqnlabel{EQn}
\end{align}
 and the claim follows from \eqnref{EQoverEW} and \eqnref{EQn}.


