\hline
$1024$ & $\mathbf{201.85}$ & $1538.34$ & $39118.61$ \\
\hline
$2048$ & $\mathbf{1302.52}$ & $6228.26$ & $97033.69$ \\
\hline
$3076$ & $\mathbf{4119.65}$ & $14851.10$ & $225846.22$ \\
\hline
$4096$ & $\mathbf{7253.46}$ & $26724.95$ & $389627.86$ \\
