\section{Asymptotic analysis of symmetric periodic solution}\label{S:4}
We now present asymptotic analysis of symmetric periodic solution of the problem in~\eqref{E:basic system}. Under the assumption of sufficiently small $A$, $\eta$, and $\omega$, let us define a small parameter $0<\varepsilon=A\eta\omega^2\ll1$. Thus, we assume the following expansions
\begin{equation}\label{E:asymptotic expansions}
	\begin{aligned}
		&\phi(t)=\phi_0(t)+\varepsilon \phi_1(t)+O(\varepsilon^2),\\
		&\sigma(t)=\sigma_0(t)+\varepsilon \sigma_1(t)+O(\varepsilon^2),\\
		&v(t)=v_0(t)+\varepsilon v_1(t)+\varepsilon^2 v_2(t)+O(\varepsilon^3).
	\end{aligned}
\end{equation} 
Note that $\phi_0(t)=\sigma_0(t)=v_0(t)=0$, because when there is no actuation the solution is identically zero. 
%(This may be proven e.g., by expanding the system in~\eqref{E:basic system} about $\phi=0$ up to order $O(\varepsilon)$, then using that $\bar{\phi}_0=0$ by definition of symmetry and thus $\dot{\phi}_0=1/\beta(-\beta+1)\sigma_0$ yielding that $\bar{\sigma}_0=\bar{v}_0=0$, and then harmonic balance at any order implies that $\sigma_0(t)=v_0(t)=0$ and hence $\phi_0(t)=0$).

To find the first-order correction, we start from the second equation in~\eqref{E:basic system}, which leads at order $O(\varepsilon)$, to
\begin{equation}\label{E:eq first order sigma}
	\dot{\sigma}_1=\frac{\sin{(\omega t)}}{\delta^2+\eta}-q\sigma_1, \quad \text{where} \quad q=\frac{2\alpha^2}{\delta^2+\eta}.
\end{equation}
%where we denote for brevity
%Equation~\eqref{E:eq first order sigma} may be expressed as 
%\begin{equation}
%	\frac{\partial}{\partial t}\left(e^{qt}\sigma_1\right)=e^{qt}  \frac{\sin{(\omega t)}}{\delta^2+\eta},
%\end{equation}
%whose integration with respect to $t$, yields the following general solution
The general solution of~\eqref{E:eq first order sigma} is given by
\begin{equation}\label{E:gen sol sig}
	\begin{aligned}
	\sigma_1(t)&=e^{-qt}\left[\frac{\omega}{(\delta^2+\eta)(q^2+\omega^2)}+C\right]\\
	&+\frac{\omega \cos{(\omega t)}-q\sin{(\omega t)}}{(\delta^2+\eta)(q^2+\omega^2)}. 
	\end{aligned}
\end{equation}
%where $C$ is an arbitrary constant of integration. Now we use periodicity requirement which implies that
%\begin{equation}
%	C=-\frac{\omega}{(\delta^2+\eta)(q^2+\omega^2)},
%\end{equation}
The first term in~\eqref{E:gen sol sig} decays exponentially in time and thus in steady-state the periodic solution may be expressed as,
%leading that the periodic and steady-state solution, which is obtained after the exponential decay, is given by
\begin{equation}\label{E:sol sigma_1 symm}
	\sigma_1(t)=b_1\sin{(\omega t)}+b_2\cos{(\omega t)},
\end{equation}
where we define for brevity
\begin{equation}\label{E:b1 and b2}
	b_1=\frac{q}{(\delta^2+\eta)(q^2+\omega^2)}, \quad b_2=-\frac{\omega}{(\delta^2+\eta)(q^2+\omega^2)}. 
\end{equation}

Substituting the solution in~\eqref{E:sol sigma_1 symm} into the first equation in~\eqref{E:basic system}, we obtain:
\begin{equation}
	\dot{\phi}_1(t)=\frac{1-\beta}{\beta}\sigma_1(t),
\end{equation}
which yields that the steady-state symmetric solution is given by,
\begin{equation}\label{E:sol phi sym}
		\phi_1(t)=a_1\sin{(\omega t)}+a_2\cos{(\omega t)},
\end{equation}
where we define for brevity
\begin{equation}\label{E:a1 and a2}
	a_1=\frac{(\beta-1)}{\beta(q^2+\omega^2)(\delta^2+\eta)}, \quad 	a_2=\frac{q(\beta-1)}{\beta\omega(q^2+\omega^2)(\delta^2+\eta)}.
\end{equation}

The expressions for $\phi_1(t)$ and $\sigma_1(t)$ are then substituted into the third equation in~\eqref{E:basic system}, and we obtain at order 
$O(\varepsilon)$ that $\dot{v}_1(t)=-3v_1(t)$. Hence, $v_1(t)=0$ in steady-state after the transient response has decayed. 
Thus, expanding up to order $O(\varepsilon^2)$, we obtain that
\begin{equation}\label{E:v1 and v2}
	v_1(t)=0, \quad \dot{v}_2=\delta\sigma_1^2-\sigma_1\phi_1-3v_2. 
\end{equation}

Solving this equation we obtain that, in steady-state after the transient response has decayed, the solution is given by
\begin{equation}\label{E:sol v sym}
	v_2(t)=c_0+c_1\sin{(2\omega t)}+c_2\cos{(2\omega t)},
\end{equation}
where we define for brevity
\begin{equation}
	 c_1=\frac{3q_1+2q_2\omega}{9+4\omega^2}, \quad c_2=\frac{3q_2-2q_1\omega}{9+4\omega^2},
\end{equation}
where
\[
\begin{aligned}
	&c_0=(\delta b_1^2  -a_1 b_1  +\delta b_2^2  -a_2 b_2)/6,\\
	&q_1=\delta b_1 b_2 -0.5(a_2 b_1+a_1 b_2),\\
	&q_2= 0.5(\delta b_2^2  -a_2 b_2  +a_1 b_1 -\delta b_1^2).
\end{aligned}
\]

It is easy to verify by substituting $a_i$ from~\eqref{E:a1 and a2} and $b_i$ from~\eqref{E:b1 and b2}, that that $c_0$ may be expressed as
\begin{equation}
	c_0=\frac{\delta}{6\bigl[4\alpha^4+(\delta^2+\eta)^2\omega^2\bigr]}.
\end{equation}
Note that from~\eqref{E:sol v sym} it follows that $\bar{v}_2=c_0$, and hence the leading-order approximation for the mean speed is given by
\begin{equation}\label{E:bar v}
	\begin{aligned}
		\bar{v}&=\varepsilon^2 c_0 +O(\varepsilon^3) \\
		&=\frac{A^2\eta^2\omega^4\delta}{6\bigl[4\alpha^4+(\delta^2+\eta)^2\omega^2\bigr]}+O(\varepsilon^3).
	\end{aligned}
\end{equation}
When considering this expression as a function of $\delta$, it is possible to conclude that $\bar{v}$ attains at most one maximum (in the physically meaningful range $0<\delta<1$), which is located at
\begin{equation}\label{E:delta opt}
	\delta_{\text{opt}}=\sqrt{\frac{\sqrt{12\alpha^4+4\eta^2\omega^2}}{3\omega}-\frac{\eta}{3}}.
\end{equation}
Thus, the maximal mean speed is
\begin{equation}\label{E:v_mean_opt}
	\bar{v}_{\text{max}}=\frac{A^2\eta^2\omega^4\delta_{\text{opt}}}{6\bigl[4\alpha^4+(\delta_{\text{opt}}^2+\eta)^2\omega^2\bigr]}.
\end{equation}

