Classically, using a channel multiple times may increase the capacity; see~\cite[Example~56]{ravagnani2018}. In~\cite[Theorem~8.9]{beemer2023network}, the authors proved that the one-shot capacity of $\mathcal{B}$ is~$\log_{|\alp|}(|\alp|-1)$ with the help of the Double Cut-Set Bound in~\cite[Theorem 8.6]{beemer2023network}. We extend~\cite[Theorem 8.6]{beemer2023network} to the multishot setting in Theorem \ref{dcsb}. In Theorem~\ref{lbn} we compute the capacity of $\mathcal{B}$ over multiple times in the setting where the adversary is more restricted, meaning, it cannot change the edges attacked each transmission round. The \textit{$i$-shot capacity of $\mathcal{B}$} shown in Theorem~\ref{lbn} is \begin{equation*}
\frac{\log_{|\alp|}(|\alp|^i-1)}{i}.
\end{equation*}

In this restricted adversarial model, there is a gain in using $\mathcal{B}$ multiple times for communication. In contrast, when the adversary is free to change the edges attacked each transmission round, we show in Theorem~\ref{cbn}, that the \textit{$i$-shot capacity of $\mathcal{B}$} is
\begin{equation*}
\log_{|\alp|}(|\alp|-1),
\end{equation*} the same as the one-shot capacity. When the adversary is more free, there is no gain in using $\mathcal{B}$ multiple times for communication. This contrast and determining whether there is a gain in capacity over multiple uses of a network motivates our work.

\section{Network Decoding}\label{prelim}
Throughout the paper, we let $q$ be a prime power, $\Fq$ be the finite field with $q$ elements, and $d_{H}(x,y)$ denote the Hamming distance between $x$ and $y$, where $x$ and $y$ are codewords in a code $C$. In this section, we recall some definitions and notation from network decoding for the convenience of the reader and also point the reader to Appendix~\ref{sec:app} and additional references such as~\cite{beemer2023network,ravagnani2018}.

\begin{definition} A (single source) \textbf{network} is a 4-tuple $\mN = (\mV,\mE,S,\mathbf{T})$ where:
\begin{enumerate}
\item $(\mV,\mE)$ is a directed, acyclic and finite multigraph;\vspace{-2ex}
\item $S \in \mV$ is the  \textbf{source};\vspace{-2ex}
\item $\bold{T} \subseteq \mV$ is the set of \textbf{terminals}.
\end{enumerate}
We also assume the following:
\begin{enumerate}[resume]
\item $|\bold{T}| \geq 1$ and $S \notin \bold{T}$.\vspace{-2ex}
\item The source does not have incoming edges and the terminals do not have outgoing edges.\vspace{-2ex}
\item There exists a directed path from $S$ to any $T \in \bold{T}$.\vspace{-2ex}
\item For every $V \in \mathcal{V}\setminus (\{S\} \cup \bold{T}),$ there exists a directed path from $S$ to $V$ and from $V$ to $T$ for some $T \in \bold{T}$.
\end{enumerate}
\end{definition}

The elements $V \in \mathcal{V}\setminus (\{S\}\cup \bold{T})$ are called \textbf{intermediate nodes}. We denote the sets of incident edges as $\textup{in}(V)$ and $\textup{out}(V)$ with their cardinalities defined as the \textbf{indegree}~$\deg^{-}(V)$ and \textbf{outdegree} $\deg^{+}(V)$. Each edge of the network~$\mN$ carries at most one element from an \textbf{alphabet} $\mA$, with $|\alp| \geq 2$. The intermediate vertices $V$ in the network~$\mN$ receive symbols from $\mA$ over the incoming edges, process them according to a chosen set of functions, and then output the information over the outgoing edges. We model errors in transmission as presented by an omniscient adversary $\ad_{\mN}$ who can change the symbol sent on up to $t$ edges from a fixed subset $\mathcal{U} \subseteq \mathcal{E}$ to any other symbol of $\alp$. The pair $(\mN, \ad_{\mN})$, where $\ad_{\mN}$ is the adversary, is called an \textbf{adversarial network}.

The edges $\mE$ of a network $\mN = (\mV, \mE, S, \bold{T})$ can be partially ordered as follows. Given~$e, e' \in \mE$, we say that $e$ precedes $e'$, denoted $e \preceq e'$, if there exists a directed path in~$\mN$ from $e$ to $e'$. Notice that the partial order $\preceq$ on $\mE$ can be extended to a total order~$\leq$. The total order extension satisfies the property $e \preceq e'$ implies $e \leq e'$. We assume a fixed total order, indicated by the labeling of the edges.

\begin{definition} [{\cite[Definition 40]{ravagnani2018}}] Let $\mN=(\mV, \mE, S, \bold{T})$ be a network. A \textbf{network code} $\mathcal{F}$ for $\mN$ is a set of functions 
$\{\mathcal{F}_V\,:\, \mA^{\textup{deg}^{-}(V)} \to \mA^{\textup{deg}^{+}(V)} \mid  V \in 
  \mathcal{V} \setminus (\{S\} \cup \bold{T})\}.$ 
\end{definition} 

The functions in $\mF$ describe how $\mN$ processes the information at each intermediate node input from the incoming edges. These functions are unique due to the choice of the total order $\leq$.





\begin{definition}\label{notC}
Let $(\mN,\ad)$ be an adversarial network with $\mN=(\mV, \mE, S, \bold{T})$ and let~$\U \subseteq \mE$ be a set of edges that the adversary can corrupt. Let $\mF$ be a network code for~$\mN$ and $t \geq 0$ be an integer. The channel representing the transfer from $S$ to $T \in \bold{T}$ is
\[ \Omega[\mN, \mA, \mF, S \longrightarrow T, \mU, t] \,:\, \alp^{\textup{deg}^+(S)} \to \alp^{\textup{deg}^{-}(T)}.\]
\end{definition}

We often write $\Omega$ to represent $\Omega[\mN, \mA, \mF, S \longrightarrow T, \mU, t]$. We now recall the definition of an unambiguous code.

\begin{definition}
An \textbf{outer} \textbf{code} for a network $\mN=(\mV, \mE, S, \bold{T})$ is a subset
$C \subseteq \alp^{\textup{deg}^{+}(S)}$ with $|C| \ge 1$. An \textbf{unambiguous} code $C$ for each channel $\Omega$ is a code such that for all~$x,y \in C$ with $x \neq y$ and for all $T \in \bold{T}$ we have
\begin{equation*}
    \Omega[\mN, \alp, \mF, \textup{out}(S) \longrightarrow \textup{in}(T), \mU,t](x) \cap \Omega[\mN, \alp, \mF, S \longrightarrow T, \mU, t](y) =\emptyset.
\end{equation*}
\end{definition}

The empty intersection guarantees that every element of $C$ can be recovered by every terminal uniquely, regardless of the action the adversary takes. We note that for any unambiguous code, any subcode is also unambiguous. Next, we define the notion of one-shot capacity of an adversarial network as in~\cite[Definition~3.18]{beemer2023network}. Let $\ad_{\mN}$ be the adversary for $\mN$ capable of corrupting up to $t$ edges of a proper subset $\mU \subsetneq \mE.$ 

\begin{definition}\label{oneshot} The \textbf{one-shot} capacity of an adversarial network $(\mathcal{N},\ad_{\mathcal{N}})$ over an alphabet $\alp$, denoted $C_1(\mN, \alp, \ad_{\mN})$, is the maximum $\alpha \in \R$ such that there exists an unambiguous code $C$ for $\Omega$ and a network code $\mathcal{F}$ with $\alpha = \log_{|\mathcal{A}|}(|C|),$ meaning, \[C_1(\mN, \alp, \ad_{\mN}) = \max \left\{\log_{|\alp|}{|C|}\,:\, C \hbox{ is an unambiguous code for each } \Omega \right\}.\]

\end{definition}

An upper bound on the one-shot capacity of an adversarial network is given below. Recall that an edge cut of a graph $G$ is a set of edges $\mE' \subseteq \mE$ such that $G \setminus \mE'$ is disconnected.  

\begin{theorem}[{Singleton Cut-Set Bound~\cite[Corollary 66]{ravagnani2018}}]\label{cutset}
Let $t \geq 0$ and let $\alp$ be an alphabet. Suppose that an adversary $\ad_{\mN}$ can corrupt up to $t$ edges from a subset $\mU \subseteq \mE$. We have that
\[\displaystyle C_1(\mN, \alp, \ad_{\mN}) \leq \min_{T \in \bT} \min_{\mE'}\left(|\mE'\setminus \mU| + \max\{0,|\mE' \cap \mU|- 2t\} \right),\] where $\mE' \subseteq \mE$ ranges over all edge cuts between the source $S$
and $T$.   
\end{theorem}

