\section{Some proofs}\label{sec:app}

 In this section, we provide some background for the convenience of the reader. We start with a definition and proposition on finer channels.

\begin{definition}\label{coarser} Let $\Omega_1$,$\Omega_2 : \mathcal{X} \dashrightarrow \mathcal{Y}$ be channels. We say that $\Omega_1$ is finer than $\Omega_2$ (or that $\Omega_2$ is coarser than $\Omega_1$) if $\Omega_1(x) \subseteq \Omega_2(x)$ for all $x \in \mathcal{X}$. In this case, we write~$\Omega_1 \leq \Omega_2$.
\end{definition}

\begin{proposition} \label{finer}\cite[Proposition 3.6]{beemer2023network} If $\Omega_1 , \Omega_2 : \mathcal{X} \dashrightarrow \mathcal{Y}$ are channels with $\Omega_1 \leq \Omega_2$, then $C_1(\Omega_1) \geq C_1(\Omega_2)$.
\end{proposition}

The \textit{concatenation} of channels was introduced in~\cite[Definitions~7 and~14]{ravagnani2018} respectively. Let $\Omega_1:\mathcal{X}_1 \dashrightarrow \mathcal{Y}_1$ and $\Omega_2:\mathcal{X}_2 \dashrightarrow \mathcal{Y}_2$
be channels, and assume that $\mathcal{Y}_1 \subseteq \mathcal{X}_2$. The \textbf{product} of $\Omega_1$ and $\Omega_2$
is the channel $\Omega_1 \times \Omega_2 : \mathcal{X}_1 \times \mathcal{X}_2 \dashrightarrow  \mathcal{Y}_1 \times \mathcal{Y}_2$
defined by   
$$(\Omega_1 \times \Omega_2)(x_1,x_2):= \Omega_1(x_1) \times 
\Omega_2(x_2),$$ $\mbox{ for all 
$(x_1,x_2) \in \mathcal{X}_1 \times \mathcal{X}_2$}$. The \textbf{concatenation} of the channels
$\Omega_1$ and $\Omega_2$ is the channel~$\Omega_1 \blacktriangleright \Omega_2 : \mathcal{X}_1 \dashrightarrow \mathcal{Y}_2$ defined by
$$(\Omega_1 \blacktriangleright \Omega_2)(x):= \bigcup_{y \in \Omega_1(x)} \Omega_2(y).$$

The following result provides insight into the capacity of the concatenation of channels. 
\begin{proposition}[\hspace{-0.1pt}{\cite[Proposition~3.9]{beemer2023network}}]
\label{doi}
Let $\Omega_1:\mathcal{X}_1 \dashrightarrow \mathcal{Y}_1$ and~$\Omega_2:\mathcal{X}_2 \dashrightarrow \mathcal{Y}_2$,
 with~$\mathcal{Y}_1 \subseteq \mathcal{X}_2$, be channels. Then,~$C_1(\Omega_1 \blacktriangleright \Omega_2) \le \min\{C_1(\Omega_1), \, 
C_1(\Omega_2)\}$. 
\end{proposition}

\begin{proposition}[\hspace{-0.1pt}{\cite[Proposition~12]{ravagnani2018}}]
\label{lwpord}
For a channel $\Omega: \mathcal{X} \dashrightarrow \mathcal{Y}$ and any $i\geq 1$, we have that
$$C_1(\Omega^i) \ge i \cdot C_1(\Omega).$$ 
\end{proposition}

\begin{corollary}[\hspace{-0.1pt}{\cite[Corollary 6.2  (Generalized Network Singleton Bound)]{beemer2023network}}] \label{corG} Let $\alp$ be an alphabet, $\mN$ a simple $2$-level network and $\mU_S$ be the set of edges connected to the source. Let an adversary $\ad$ be able to corrupt up to $t$ edges of~$\mN$. Then, the one-shot capacity of~$\mN$ satisfies 
    \begin{equation*}\mathrm{C}_1\left(\mathcal{N}, \ad \right) \leq \min _{P_1 \sqcup P_2=\{1, \ldots, n\}}\left(\sum_{i \in P_1} b_i+\max \left\{0, \sum_{i \in P_2} a_i-2 t\right\}\right)\end{equation*}
with $P_1$ and $P_2$ are two partitions of the set $\{0, \ldots, n\}$ and the minimum is taken over all possible $2$-partitions.
\end{corollary}




