    \includegraphics[width=\linewidth]{example.pdf}
    \caption{Scorch SDDMM and sparse attention examples}
    \label{fig:example}
  \end{minipage}
  \hfill
  \begin{minipage}[b]{0.34\linewidth}
    \includegraphics[width=\linewidth]{overview.pdf}
    \caption{\sys architecture}
    \label{fig:overview}
  \end{minipage}
