\node (t) at (1.1,0) {$X$};
\node (r) at (2.2,0) {$Y$.};
\draw [->] (t) -- (r);
\draw [->] (s) -- (t);
\draw [->] (s) edge [bend left=27] (r);
\end{tikzpicture}\\
