\title{Secure Parsing and Serializing with Separation Logic\\Applied to CBOR, CDDL, and COSE}
\renewcommand\shorttitle{Secure Parsing and Serializing with Separation Logic Applied to CBOR, CDDL, and COSE}

\author{Tahina Ramananandro}
\email{taramana@microsoft.com}
\author{Gabriel Ebner}
\email{gabrielebner@microsoft.com}
\author{Guido Mart\'inez}
\email{guimartinez@microsoft.com}
\author{Nikhil Swamy}
\email{nswamy@microsoft.com}
