\section{Classical and quantum CSPs}
\label{sec_classical_quantum_CSPs}
In this preliminary section, we formally describe classical and quantum assignments for constraint satisfaction problems. We adopt the language of
\textit{predicate satisfiability}, which yields the most natural description of specific types of CSPs that shall appear frequently (in particular, $d$-to-$1$ and $d$-to-$d$). Two alternative descriptions will sometimes be preferable: 
the language of \textit{non-local games}, providing a physical intuition of classical, quantum, and locally compatible quantum assignments as winning strategies for two-player cooperative games; and the language of \textit{homomorphisms between relational structures}, allowing for a more direct connection with categorical constructs such as the Pultr adjunction, as we shall see in Section~\ref{sec_pultr_functors}. 
%
The three, equivalent descriptions are given in Sections~\ref{subsec_CSP_predicates},~\ref{subsec_CSP_nonlocal_games}, and~\ref{subsec_CSP_homomorphisms}, respectively.





\subsection{Predicate satisfiability}
\label{subsec_CSP_predicates}

A CSP instance consists of a tuple $\Phi=(X,E,A,\pi,\phi)$ where 
\begin{itemize}
    \item $X$ is a finite set (whose elements are called \textit{variables});
    \item 
    $E$ is a multiset of \textit{constraint} tuples $\bx$ of variables, each having a finite length called \textit{arity} and denoted by $\ar(\bx)$;
    \item $A$ is a finite set (called the \textit{alphabet} or \textit{label set});
    \item $\pi$ is a positive probability distribution over $E$;
    \item $\phi$ is a collection of predicates $\phi_\bx:A^{\ar(\bx)}\to\{0,1\}$ for each $\bx\in E$.\footnote{We shall often identify the function $\phi_\bx$ with the set $\{\ba\in A^{\ar(\bx)}\suchThat\phi_\bx(\ba)=1\}$.}
\end{itemize}

A \textit{classical assignment} for a CSP instance $\Phi$ is a function $f:X\to A$.
The value of $f$ on a constraint $\bx$ is $\phi_\bx(f(\bx))$, where $f(\bx)$ is the entrywise application of $f$ to the entries of $\bx$.
%
The total value of $f$ is the weighted fraction of satisfied constraints; i.e., the quantity 
\begin{align*}
    \sat_f(\Phi)=\mathbb{E}_{\bx\sim\pi}\phi_\bx(f(\bx)).
\end{align*}
%
If $\sat_f(\Phi)=1$, we say that $f$ is a \textit{perfect} classical assignment.
%
The \textit{classical value} of $\Phi$, denoted by $\sat(\Phi)$, is the maximum of $\sat_f(\Phi)$ over all classical assignments $f:X\to A$.

Given a finite set $S$ and a finite-dimensional Hilbert space $\HH$, we let $\PVM_{\HH}(S)$ be the set of projection-valued measurements over $\HH$ whose outcomes are indexed by $S$. I.e., $\PVM_{\HH}(S)$ contains all sets $\{Q_s:s\in S\}$ 
where each $Q_s$ is a projector onto $\HH$ and, in addition, $\sum_{s\in S}Q_s$ is the identity projector $\id_\HH$.
%
A \textit{quantum assignment} over $\HH$ for a CSP instance $\Phi$ consists of a function $\mathfrak{Q}:X\to\PVM_\HH(A)$. For notational convenience, given a variable $x\in X$ and a label $a\in A$, we shall denote by $Q_{x,a}$ the $a$-th projector in the measurement $\mathfrak{Q}(x)$. The value of $\mathfrak{Q}$ on a constraint $\bx=(x_1,\dots,x_r)\in E$ of arity $r$ is the quantity
\begin{align*}
\frac{1}{\dim(\HH)}
    \sum_{\ba\in A^{r}}\phi_\bx(\ba)\,\tr(Q_{x_1,a_1}\cdot Q_{x_2,a_2}\cdot\ldots\cdot Q_{x_{r},a_{r}}).
\end{align*}
%
The total value of $\mathfrak{Q}$ is then the quantity
\begin{align}
\label{eqn_1527_232}
\qsat_{\mathfrak{Q}}(\Phi)=\frac{1}{\dim(\HH)}\mathbb{E}_{\bx\sim\pi}
    \sum_{\ba\in A^{\ar(\bx)}}\phi_\bx(\ba)\,\tr(Q_{x_1,a_1}\cdot Q_{x_2,a_2}\cdot \ldots\cdot Q_{x_{\ar(\bx)},a_{\ar(\bx)}}).
\end{align}
%
We say that $\mathfrak{Q}$ is a \textit{perfect} quantum assignment if $\qsat_{\mathfrak{Q}}(\Phi)=1$.
%

%
If all constraints of $\Phi$ have arity $1$ or $2$, the quantity in~\eqref{eqn_1527_232} is always real, and the assignment $\mathfrak{Q}$ is sometimes called a \textit{quantum noncommutative strategy} (see, for example,~\cite[\S~3.1]{mousavi2025quantum}).
%
%, and we can then define  the \textit{quantum value} of $\Phi$, denoted by $\qsat(\Phi)$, as the supremum of $\qsat_{\mathfrak{Q}}(\Phi)$ over all quantum assignments $\mathfrak{Q}$. This is sometimes known as the \textit{noncommutative value} of the CSP.
%
In the general case, in order to enforce that the traces of products of projectors in the expression above be real, one further requires that projectors corresponding to variables appearing in a common constraint should commute. We call these quantum assignments \textit{$1$-compatible}. 
%
More in general, as discussed in Section~\ref{subsec_classical_quantum_CSPs}, we consider quantum assignments enforcing commutativity between projectors corresponding to variables that are close in the metric over $X$ induced by the constraints in $E$. 
%
%
%
Enforcing this type of \textit{local compatibility} for quantum assignments of a CSP instance is needed in order to 
achieve quantum completeness of Pultr reductions, which is the focus of Section~\ref{sec_pultr_functors}.
%
%The physical intuition behind this requirement is best understood in the language of non-local games, see Section~\ref{subsec_CSP_nonlocal_games}.

We now formally define locally compatible quantum assignments.
Given two variables $x,x'\in X$, we let $\dist_\Phi(x,x')$ denote the distance between $x$ and $x'$ in the \textit{Gaifman graph} of $\Phi$---i.e., the undirected graph having vertex set $X$, where two vertices are adjacent if and only if they appear in a common constraint. For two operators $Q$ and $Q'$, let $[Q,Q']=QQ'-Q'Q$ be their commutator. %Let also $\N=\{1,2,\dots\}$ be the set of positive integers.
%
We say that a quantum assignment $\mathfrak{Q}$ is \textit{$k$-compatible} for some $k\in\N\cup\{0\}$ if $[Q_{x,a},Q_{x',a'}]=O$ for each pair $x,x'\in X$ such that $\dist_{\Phi}(x,x')\leq k$ and each pair $a,a'\in A$. Clearly, the $k$-compatibility requirement becomes progressively stronger as $k$ increases.
%Since the projectors in a PVM commute with each other, a $0$-compatible quantum strategy is just a quantum strategy. 
In the extreme case, if $\delta$ is the diameter of the Gaifman graph of $\Phi$, a $\delta$-compatible quantum assignment requires that the projectors in \textit{all} PVMs of the assignment should commute with each other and, thus, be simultaneously diagonalisable. Hence, $\delta$-compatible quantum assignments collapse to classical assignments.
%
Note that
projector commutativity is not transitive, so locally compatible quantum assignments do not automatically collapse to globally compatible, and thus classical, assignments.

The total value of a $k$-compatible quantum strategy is clearly real if $k\geq 1$, regardless of the arity of its constraints. Hence, the $k$-compatible quantum value of $\Phi$, denoted by $\qsat_k(\Phi)$, can be defined as the supremum of $\qsat_{\mathfrak{Q}}(\Phi)$ over all $k$-compatible quantum assignments $\mathfrak{Q}$.
%
The discussion above shows that the following chain of inequalities holds:
\begin{align*} 
    \qsat_1(\Phi)
    \geq
    \qsat_2(\Phi)
    \geq 
    \dots 
    \geq
    \qsat_\delta(\Phi)
    =
    \qsat_{\delta+1}(\Phi)
    =
    \dots
    =
    \sat(\Phi).
\end{align*}
In addition, in the unary or binary case, we have that $\qsat_0(\Phi)\geq \qsat_1(\Phi)$. Hence, the notion described above allows to smoothly decrease the value of a CSP from the quantum noncommutative to the classical one, by considering PVM assignments that ``look classical'' over progressively larger subinstances of $\Phi$. 
%

%\subsection{Label-cover games}
%\label{subsec_label_cover}
We now define a particular type of CSP instances that shall frequently appear in this work.
%
A \textit{label-cover} instance is a CSP instance $\Phi=(X,E,A,\pi,\phi)$ all of whose constraints are binary. Notice that, in this case, $(X,E)$ is a digraph (possibly with repeated edges). We say that $\Phi$ is \textit{bipartite} if
$E\subseteq X_1\times X_2$ for some decomposition $X=X_1\sqcup X_2$.
% 
Following~\cite{dinur2014analytical,dinur2015parallel},
we say that a bipartite label-cover instance $\Phi$ is \textit{projective} if there is a decomposition $A=A_1\sqcup A_2$ such that, for each $\bx\in E$, it holds that $(i)$ $\phi_\bx\subseteq A_1\times A_2$, and $(ii)$ for each $a_1\in A_1$ there exists precisely one value $a_2\in A_2$ for which $\phi_\bx(a_1,a_2)=1$.\footnote{Sometimes, in the literature on both classical and quantum CSPs/non-local games, the expression ``label-cover instances'' indicates what we call here ``projective label-cover instances''.}
%
Clearly, if $f:X\to A$ is an optimal classical assignment for $\Phi$, there is an optimal classical assignment $f'$ such that $f'(X_1)\subseteq A_1$ and $f'(X_2)\subseteq A_2$. Hence, we can assume without loss of generality that optimal classical assignments satisfy the latter condition. (We shall see that the same holds for optimal quantum assignments, see Proposition~\ref{prop_only_relevant_projectors}.)
%
We say that a projective label-cover instance is \textit{$d$-to-$1$} for some $d\in\N$ if for each $\bx\in E$ and each $a_2\in A_2$ there exist precisely $d$-many values $a_1\in A_1$ for which $\phi_\bx(a_1,a_2)=1$. 
%
Observe that, in this case, $|A_1|=d\cdot|A_2|$.
%

























\subsection{Non-local games}
\label{subsec_CSP_nonlocal_games}
%
The following two-player cooperative game can be associated with a CSP instance $\Phi=(X,E,A,\pi,\phi)$ (see for example~\cite{abramsky2017quantum}): 
\begin{itemize}
    \item The verifier sends Alice a constraint $\bx\in E$ sampled according to the probability distribution $\pi$, and Alice responds with a tuple $\ba\in A^{\ar(\bx)}$;
    \item the verifier sends Bob a variable $x\in X$ sampled uniformly at random, and Bob responds with a label $a\in A$.
\end{itemize}
%
Alice and Bob win the game if, whenever $x=x_i$ for some $i\in[\ar(\bx)]$, it holds that $a=a_i$. 
%
It is straightforward to see that a perfect classical (deterministic or randomised) strategy for Alice and Bob exists precisely when $\sat(\Phi)=1$. A \textit{quantum} strategy $\mathfrak{E}$ consists of a finite-dimensional Hilbert space $\HH$, a state $\psi\in\HH\otimes\HH$, and two collections of measurements---one for Alice and one for Bob---indexed by the verifier's questions and having as possible outcomes the admitted players' answers.
%
More in detail, there is a measurement $\{E_{\bx,\ba}\}_{\ba\in A^{\ar(\bx)}}\in\PVM_\HH(A^{\ar(\bx)})$ for each $\bx\in E$, and a measurement $\{{E'_{x,a}}\}_{a\in A}\in\PVM_\HH(A)$ for each $x\in X$. Upon receiving the verifier's questions, Alice and Bob select the corresponding PVMs and perform the corresponding measurement on their part of the state $\psi$; then, their answers to the verifier are the obtained outcomes.
Hence, in order for the strategy to be perfect, the following conditions must hold:
\begin{itemize}
    \item $\psi^*({E_{\bx,\ba}}
    \otimes {E'_{x,a}})\psi=0$ whenever $x$ appears in $\bx$ with index $i$ and $a\neq a_i$;
    \item $\psi^*({E_{\bx,\ba}}\otimes \id_\HH)\psi=0$ whenever $\phi_\bx(\ba)=0$.
\end{itemize}
%
The next result shows the connection between perfect quantum strategies and perfect quantum assignments.%\footnote{A similar results holds also for non-perfect quantum strategies, where the value is the winning probability of Alice and Bob. However, in this work we will only deal with perfect quantum strategies.}

\begin{thm}[\cite{abramsky2017quantum}]
\label{thm_abramsky_quantum_strategies_quantum_assignments}
    Let $\Phi$ be a $\CSP$ instance. Then 
    $\Phi$ has a perfect $1$-compatible quantum assignment if and only if the non-local game associated with $\Phi$ admits a perfect quantum strategy.
\end{thm}

We can easily modify the non-local game above to capture locally compatible quantum assignments. To that end, we add ``fake'' constraints to $\Phi$ that have no effect on classical strategies, but enforce commutativity of the projectors corresponding to the selected variables. Formally, we consider the CSP instance $\Phi^{(k)}=(X,E',A,\pi',\phi')$ where $E'$ is obtained from $E$ by adding a binary constraint $(x,x')$ for each two variables $x,x'$ such that $\dist_\Phi(x,x')\leq k$. The corresponding set of admitted labels is $\phi_{(x,x')}=A^2$; i.e., no restriction is posed on the value of the constraint. Finally, $\pi'$ assigns probability, say, $\frac{\pi(\bx)}{2}$ for each $\bx\in E$, and probability $\frac{1}{2\alpha}$ for each new binary constraint $(x,x')$, where $\alpha$ is the number of the new binary constraints. The following fact is immediate from Theorem~\ref{thm_abramsky_quantum_strategies_quantum_assignments}.

\begin{cor}
\label{cor_1239_2103}
Let $\Phi$ be a CSP instance, and take $k\in\N$. Then 
    $\Phi$ has a perfect $k$-compatible quantum assignment if and only if the non-local game associated with $\Phi^{(k)}$ admits a perfect quantum strategy.
\end{cor}








\subsection{Homomorphism problems}
\label{subsec_CSP_homomorphisms}
We end this preliminary section by giving an equivalent description of CSPs based on homomorphisms between relational structures.
%
A \emph{signature} $\rho$ is a finite set of relation symbols $R$, each with its \emph{arity} $\ar(R)\in\N$.
%
A \emph{relational structure} $\mathbf{S}$ with signature $\rho$ (in short, a $\rho$-structure) consists of a finite set $S$ and a relation $R({\mathbf{S}})\subseteq S^{\ar(R)}$ for each symbol $R\in\rho$. A \textit{homomorphism} $f:\mathbf{S}\to\T$ between two relational structures $\mathbf{S}$ and $\T$ on a common signature $\rho$ is a map from the domain $S$ of $\mathbf{S}$ to the domain $T$ of $\T$ that preserves all relations; i.e., $f(\bs)\in R({\T})$ for each symbol $R\in\rho$ and each tuple $\bs\in R({\mathbf{S}})$ (where $f(\bs)$ is the entrywise application of $f$ the the entries of $\bs$). We denote the existence of a homomorphism from $\mathbf{S}$ to $\T$ by the notation $\mathbf{S}\to\T$.
%

%
Given a CSP instance $\Phi=(X,E,A,\pi,\phi)$, we can associate with $\Phi$ two relational structures $\X$, $\A$ over a common signature $\rho$ as follows. 
%
The domains of $\X$ and of $\A$ are the variable set $X$ and the label set $A$, respectively. The signature $\rho$ contains an $r$-ary symbol for each distinct map $\phi_\bx:A^r\to\{0,1\}$; 
the interpretation $R(\X)$ of $R$ in $\X$ contains all tuples $\bx\in E$ such that $\phi_\bx$ corresponds to the symbol $R$, while
the interpretation of $R$ in $\A$ is the set $R(\A)=\{\ba\in A^r:\phi_\bx(\ba)=1\}$. 
%
%
Conversely, given two structures $\X$ and $\A$ on a common signature $\rho$, we can associate with them a CSP instance $\Phi=(X,E,A,\pi,\phi)$ such that $X$ and $A$ are the domains of $\X$ and $\A$, respectively; $E=\bigcup_{R\in\rho}R(\X)$; for $R\in\rho$ and $\bx\in R(\X)$, $\phi_\bx$ is the Boolean map defined by $\ba\mapsto 1$ for each $\ba\in R(\A)$ and $\ba\mapsto 0$ for each $\ba\in A^{\ar(R)}\setminus R(\A)$; and $\pi$ is any positive distribution over $E$. Note that, as far as \textit{perfect} (classical or quantum) assignments are concerned, the particular choice of $\pi$ is irrelevant.
%
Let $\X$ and $\A$ be the $\rho$-structures corresponding to a CSP instance $\Phi$. Clearly, it holds that $\sat(\Phi)=1$ if and only if $\X\to\A$. For $k\in\N$, we write $\X\leadsto^k\A$ if $\Phi$ admits a perfect $k$-compatible quantum assignment. (If $\X$ and $\A$ have only unary and binary relations, we also use the notation $\X\leadsto^0\A$ to indicate that $\Phi$ admits a perfect quantum assignment, with no local compatibility requirements.)
%
When $\Phi$ is the CSP instance corresponding to two structures $\X$ and $\A$, we denote $\dist_\Phi$ by $\dist_\X$.
%
\begin{example}
Let $\GG$ be an undirected graph, and view it as the relational structure having a single, binary relation containing, for each undirected edge $\{g,g'\}$ of $\GG$, the two tuples $(g,g')$ and $(g',g)$. Also, for $n\geq 2$, let $\K_n$ denote the $n$-clique.
Recall that the\textit{ classical chromatic number} of $\GG$ is the minimum $n$ such that $\GG\to\K_n$. The \textit{quantum chromatic number} of $\GG$ is defined as the minimum $n$ such that $\GG\leadsto^0\K_n$~\cite{CameronMNSW07}. 
\end{example}


The next proposition easily follows from a result proved in~\cite{abramsky2017quantum}.
%



%\LC{Define the quantum chromatic number}



\begin{prop}
\label{thm_quantum_assignments_as_projectors}
    Let $\X$ and $\Y$ be $\rho$-structures and let $k\in\N$. Then $\X\leadsto^k\Y$ if and only if
    there exists a finite-dimensional Hilbert space $\HH$ and
    a family of projectors $\{Q_{x,y}\}_{y\in Y}\in\PVM_\HH(Y)$ for each $x\in X$ such that
    \begin{enumerate}
    \item $Q_{x_1,y_1}\cdot Q_{x_2,y_2}\cdot\ldots\cdot Q_{x_{\ar(R)},y_{\ar(R)}}=O$ for each $R\in\rho$, $\bx\in R(\X)$, and $\by\in Y^{\ar(R)}\setminus R(\Y)$;
    \item $[Q_{x,y},Q_{x',y'}]=O$ for each $x,x'\in X$, $y,y'\in Y$ such that $\dist_\X(x,x')\leq k$.
\end{enumerate}
\end{prop}
%
\begin{proof}
    If $k=1$, the result is~\cite[Theorem~7]{abramsky2017quantum}. Suppose that $k\geq 2$, and let $\Phi$ be the CSP instance associated with $\X,\Y$. Let also $\Phi^{(k)}$ be the CSP instance obtained from $\Phi$ by adding binary constraints over variables at distance at most $k$ (as described in Section~\ref{subsec_CSP_nonlocal_games}), and let $\X^{(k)},\Y^{(k)}$ be the structures corresponding to $\Phi^{(k)}$. By definition, $\X\leadsto^k\Y$ is equivalent to $\Phi$ admitting a perfect $k$-compatible quantum assignment. By Corollary~\ref{cor_1239_2103}, the latter is equivalent to $\Phi^{(k)}$ admitting a perfect $1$-compatible quantum assignment---i.e., to $\X^{(k)}\leadsto^1\Y^{(k)}$. The result then follows by applying the proposition to the structures $\X^{(k)},\Y^{(k)}$, and noting that $\dist_{\X^{(k)}}(x,x')\leq 1$ $\Leftrightarrow$ $\dist_\X(x,x')\leq k$ for each $x,x'\in X$.
\end{proof}

\begin{rem}
We point out that Proposition~\ref{thm_quantum_assignments_as_projectors} also holds for $k=0$ if $\X$ and $\Y$ are graphs, as proved in~\cite[Corollary~2.2]{MancinskaR16}. In such case, a perfect quantum assignment corresponds to a perfect quantum strategy for a \textit{symmetric} version of the non-local game described in Section~\ref{subsec_CSP_nonlocal_games}, where both players receive a vertex as the verifier's question (such as the colouring game discussed in the Introduction). In particular, this means that the quantum chromatic number of a graph can be defined through the symmetric version of the game; for its formal description,
we refer the reader to~\cite{CameronMNSW07,MancinskaR16}.
\end{rem}


As a consequence,
we shall encode a perfect $k$-compatible quantum assignment for $\X$ and $\Y$ as a collection $\mathfrak{Q}=\{Q_{x,y}:x\in X,y\in Y\}$ of projectors onto some Hilbert space $\HH$ meeting the conditions of Proposition~\ref{thm_quantum_assignments_as_projectors}.
%
We will often make use of the following result.

\begin{prop}
\label{prop_compose_classic_quantum_homos}
    Let $\X,\X',\Y,\Y'$ be $\rho$-structures such that $\X\to\X'\leadsto^k\Y'\to\Y$ for some $k\in\N$. Then $\X\leadsto^k\Y$.
\end{prop}
%
\begin{proof}
    Let $f:\X\to\X'$ and $g:\Y'\to\Y$ be homomorphisms, and let $\mathfrak{Q}$ be a perfect $k$-compatible quantum assignment for $\X',\Y'$ over some Hilbert space $\HH$. Consider, for each $x\in X$ and $y\in Y$, the linear application
    \begin{align}
    \label{eqn_1244_1912}
        W_{x,y}
        =
        \sum_{y'\in g^{-1}(y)}Q_{f(x),y'}.
    \end{align}
    We claim that the set $\mathfrak{W}=\{W_{x,y}\suchThat x\in X,y\in Y\}$ yields a perfect $k$-compatible quantum assignment for $\X,\Y$ (over the same Hilbert space $\HH$).
%
First of all, the summands in~\eqref{eqn_1244_1912} are mutually orthogonal projectors and, thus, the linear applications in $\mathfrak{W}$ are projectors. The fact $\sum_{y\in Y}W_{x,y}=\id_\HH$ follows from the analogous property of $\mathfrak{Q}$. Hence, $\mathfrak{W}$ is a quantum assignment. 
%
Take now an $r$-ary symbol $R\in\rho$ and two tuples $\bx\in R(\X)$ and $\by\in Y^r\setminus R(\Y)$. Suppose, for the sake of contradiction, that
\begin{align*}
    O
    \neq
    \prod_{i\in [r]}W_{x_i,y_i}
    =
    \prod_{i\in [r]}\,\sum_{y'\in g^{-1}(y_i)}Q_{f(x_i),y'}.
\end{align*}
We deduce that there exist elements $y'_i\in g^{-1}(y_i)$ for each $i\in [r]$ such that
\begin{align}
\label{eqn_1912_1305}
    O\neq \prod_{i\in [r]}Q_{f(x_i),y'_i}.
\end{align}
%
Consider now the tuple $\by'=(y'_1,\dots,y'_r)$. Since $f$ is a homomorphism and $\bx\in R(\X)$, it holds that $f(\bx)\in R(\X')$. Since $\mathfrak{Q}$ is a perfect quantum assignment, we deduce from~\eqref{eqn_1912_1305} that $\by'\in R(\Y')$. Since $g$ is a homomorphism, we conclude that $\by=g(\by')\in R(\Y)$, a contradiction. This means that the assignment $\mathfrak{W}$ is perfect.
%
Finally, to show that $\mathfrak{W}$ is $k$-compatible, observe that $\dist_{\X'}(f(x),f(\tilde x))\leq \dist_\X(x,\tilde x)$ for each $x,\tilde x\in X$ since $f$ is a homomorphism. Hence, the $k$-compatibility of $\mathfrak{Q}$ implies that
\begin{align*}
    \Big[W_{x,y},W_{\tilde x,\tilde y}\Big]
    =
    \Big[\sum_{y'\in g^{-1}(y)}Q_{f(x),y'},\sum_{\tilde y'\in g^{-1}(\tilde y)}Q_{f(\tilde x),\tilde y'}\Big]
    =
    \sum_{y'\in g^{-1}(y)}\,\sum_{\tilde y'\in g^{-1}(\tilde y)}\Big[Q_{f(x),y'},Q_{f(\tilde x),\tilde y'}\Big]
    =
    O
\end{align*}
for each $x,\tilde x\in X$ with $\dist_\X(x,\tilde x)\leq k$ and each $y,\tilde y\in Y$.
%
Therefore, the assignment $\mathfrak{W}$ witnesses that $\X\leadsto^k\Y$, as claimed.
\end{proof}
%
\begin{rem}
    Following~\cite{ciardo_quantum_minion}, we might alternatively prove Proposition~\ref{prop_compose_classic_quantum_homos} by viewing a quantum assignment $\X\leadsto^k\Y$ as a classical assignment $\X^{(k)}\to\freeQ(\Y^{(k)})$, where $\X^{(k)}$ and $\Y^{(k)}$ are as in the proof of Proposition~\ref{thm_quantum_assignments_as_projectors} and $\freeQ$ denotes the \textit{free structure} generated by the \textit{quantum minion} $\Qminion$. (For the definitions, we refer the reader to~\cite{ciardo_quantum_minion}.) The proposition, then, easily follows by using the transitivity of classical homomorphisms. 
%
    We also point out that Proposition~\ref{prop_compose_classic_quantum_homos} cannot be strengthened to yield transitivity of perfect locally compatible quantum assignments, in the following sense.
    Suppose that $\X\leadsto^k\Y\leadsto^{k}\W$ is witnessed by two perfect $k$-compatible quantum assignments $\mathfrak{Q}=\{Q_{x,y}\}$ for $\X,\Y$ and $\mathfrak{Q}'=\{Q'_{y,w}\}$ for $\Y,\W$. Following~\cite{abramsky2017quantum}, one might define the perfect quantum assignment $\mathfrak{W}=\{W_{x,w}\}$ for $\X,\W$ by setting
    \begin{align*}
        W_{x,w}=\sum_{y\in Y}Q_{x,y}\otimes Q'_{y,w}.
    \end{align*}
    However, the $k$-compatibility of $\mathfrak{Q}$ and $\mathfrak{Q}'$ is not preserved in $\mathfrak{W}$, as the projectors in the latter assignment depend on \textit{all} projectors $Q'_{y,w}$ in $\mathfrak{Q}'$, rather than only those corresponding to vertices $y,y'\in Y$ having small distance.
\end{rem}



\section{Quantum adjunction of Pultr functors}
\label{sec_pultr_functors}
%
The goal of this section is to prove a quantum version of Theorem~\ref{thm_pultr_adjoints} on the adjunction of Pultr functors, which shall be needed in later sections to transfer pseudo-telepathy to the colouring game. We start by formally defining Pultr functors and Pultr templates.





\begin{defn}
\label{defn_pultr_template}
Let $\rho,\tau$ be two relational signatures. A $(\rho,\tau)$-\textit{Pultr template} $\mathfrak{T}$ consists of the following data: 
\begin{itemize}
    \item a $\rho$-structure $\A$;
    \item a $\rho$-structure $\B_{T}$ for each $T\in\tau$;
    \item a homomorphism $\epsilon_{i,T}:\A\to\B_{T}$ for each $T\in\tau$ and each $i\in [\ar(T)]$.
\end{itemize}
\end{defn}

We denote by $\mathbf{Str}(\rho)$ the set of all relational structures on signature $\rho$.

\begin{defn}
\label{defn_central_pultr_functor}
    Let $\mathfrak{T}$ be a $(\rho,\tau)$-Pultr template. The \textit{central Pultr functor} corresponding to $\mathfrak{T}$ is the map $\Gamma:\mathbf{Str}(\rho)\to\mathbf{Str}(\tau)$ defined as follows. For a $\rho$-structure $\X$, the domain of $\Gamma\X$ is the set of homomorphisms $h:\A\to\X$. For a symbol $T\in\tau$ of arity $t$, $T(\Gamma\X)$ contains all tuples $(\ell\circ\epsilon_{1,T},\dots,\ell\circ\epsilon_{t,T})$ for any homomorphism $\ell:\B_{T}\to\X$. 
\end{defn}



\begin{defn}
\label{defn_left_pultr_functor}
    Let $\mathfrak{T}$ be a $(\rho,\tau)$-Pultr template. The \textit{left Pultr functor} corresponding to $\mathfrak{T}$ is the map $\Lambda:\mathbf{Str}(\tau)\to\mathbf{Str}(\rho)$ defined as follows. For a $\tau$-structure $\X$, consider the $\rho$-structure $\mathbf{Z}$ given as the disjoint union of a copy $\A^{(x)}$ of $\A$ for each $x\in X$, and a copy $\B_T^{(\bx)}$ of $\B_T$ for each $T\in\tau$ and each $\bx\in T(\X)$. 
    Let $\sim$ be the coarsest equivalence relation over the vertices of $\mathbf{Z}$ that identifies the vertex $a^{(x_j)}$ of $\A^{(x_j)}$
    with the vertex $(\epsilon_{j,T}(a))^{(\bx)}$ of $\B_T^{(\bx)}$ for each $T\in\tau$, $\bx\in T(\X)$, $j\in [\ar(T)]$, and $a\in A$. We define $\Lambda\X$ as the quotient structure $\mathbf{Z}/\sim$.
\end{defn}
%
While the vertices of $\Lambda\X$ are formally equivalence classes of vertices of $\mathbf{Z}$, we will omit the equivalence class symbol for the sake of readability. For example, the expression ``the vertex $a^{(x)}$ of $\Lambda\X$'' should be understood as ``the equivalence class under $\sim$ of the vertex $a^{(x)}$ of $\mathbf{Z}$''.
%
