A relational structure $\X$ is connected if its Gaifman graph is connected. In that case, the diameter of $\X$ (in symbols, $\diam(\X)$) is the diameter of the Gaifman graph.
%
We say that a $(\rho,\tau)$-Pultr template $\mathfrak{T}$ is \textit{connected} if the following two conditions hold:
\begin{itemize}
    \item Each of the $\rho$-structures $\A$, $\{\B_{T}\}_{T\in\tau}$ is connected;
    \item for each $R\in\rho$, $T\in\tau$, and $\bb\in R(\B_{T})$ there exists some $\ba\in R(\A)$ and some $i\in[\ar(T)]$ such that $\epsilon_{i,T}(\ba)=\bb$.
\end{itemize}
%
We define the diameter $\diam(\mathfrak{T})$ of a connected $(\rho,\tau)$-Pultr template $\mathfrak{T}$ as the maximum among the diameters of $\A$ and of $\B_{T}$ for each $T\in\tau$.


\begin{example}
\label{ex_line_digraph_pultr}
Let $\rho$ be the signature containing a unique, binary symbol $R$, and consider the $(\rho,\rho)$-Pultr template $\mathfrak{T}$ such that $\A$ is a directed path of length $1$ with edge $(a_1,a_2)$; $\B_R$ is a directed path of length $2$ with edges $(b_1,b_2)$ and $(b_2,b_3)$; the homomorphisms $\epsilon_{1,R}$ and $\epsilon_{2,R}:\A\to\B_R$ are defined as follows:
    $\epsilon_{1,R}$ maps $a_1$ to $b_1$ and $a_2$ to $b_2$; $\epsilon_{2,R}$ maps $a_1$ to $b_2$ and $a_2$ to $b_3$.
Then, the left and central Pultr functors corresponding to $\mathfrak{T}$ are the functors $\Lambda''$ and $\Gamma''$ from Example~\ref{ex_some_pultr_functors}. Observe that the Pultr template $\mathfrak{T}$ is connected.
\end{example}




