\begin{thm*}
[Theorem~\ref{thm_adjunction_pultr_1} restated]
Let $\mathfrak{T}$ be a connected $(\rho,\tau)$-Pultr template, let $\X$ and $\Y$ be a $\tau$-structure and a $\rho$-structure, respectively, let $k\in\N$, let $k'=(k+1)\cdot\diam(\mathfrak{T})$, and suppose that $\Lambda\X\leadsto^{k'}\Y$. Then $\X\leadsto^{k}\Gamma\Y$.
\end{thm*}
\begin{proof}
    Let $\mathfrak{Q}=\{Q_{z,y}\suchThat z\in\Lambda\X,\,y\in Y\}$ be a perfect $k'$-compatible quantum assignment for the $\Lambda\X,\Y$ game. Given a vertex $x\in X$ and a map $h:A\to Y$ (not necessarily a homomorphism $\A\to\Y$), consider the linear application
    \begin{align}
    \label{eqn_1445_2911}
        W_{x,h}=\prod_{a\in A}Q_{a^{(x)},h(a)}.
    \end{align}
%
    Consider the set $\mathfrak{W}=\{W_{x,h}\suchThat x\in X, h:\A\to\Y\}$. We aim to show that $\mathfrak{W}$ is a quantum assignment witnessing that $\X\leadsto^k\Gamma\Y$.

    \begin{claim}
    \label{eqn_2911_1449}
     All linear applications in $\mathfrak{W}$ are projectors. 
    \end{claim}

    \begin{proof}
        For each $a,a'\in A$, $x\in X$, we have
        \begin{align*}
            \dist_{\Lambda\X}(a^{(x)},a'^{(x)})\leq \dist_{\A}(a,a')\leq\diam(\A)\leq\diam(\mathfrak{T})\leq k'.
        \end{align*}
        Since the strategy $\mathfrak{Q}$ is $k'$-compatible, we deduce that the projectors $Q_{a^{(x)},h(a)}$ and $Q_{a'^{(x)},h(a')}$ commute for each $h:\A\to \Y$. Hence, the product in~\eqref{eqn_1445_2911} is a projector.
    \end{proof}

    \begin{claim}
    \label{claim_2911_1529}
        If $h:A\to Y$ is not a homomorphism from $\A$ to $\Y$, $W_{x,h}=O$ for each $x\in X$.
    \end{claim}
    %
    \begin{proof}
        Since $h$ is not a homomorphism, there exists some symbol $R\in\rho$ of arity $r$ and some tuple $\ba\in R(\A)$ for which $h(\ba)\not\in R(\Y)$. By definition of $\Lambda\X$, we have $\ba^{(x)}=(a_1^{(x)},\dots,a_r^{(x)})\in R(\Lambda\X)$. Since $\mathfrak{Q}$ is a perfect strategy, it follows that
        \begin{align*}
            \prod_{i\in [r]}Q_{a_i^{(x)},h(a_i)}=O.
        \end{align*}
        Let $\tilde A\subseteq A$ be the set of all elements of $A$ that do not appear in the tuple $\ba$. Using the $\diam(\A)$-compatibility of $\mathfrak{Q}$, we find
        \begin{align*}
            W_{x,h}=
            \prod_{a\in A}Q_{a^{(x)},h(a)}
            =
            \Big(\prod_{a\in \tilde A}Q_{a^{(x)},h(a)}\Big)\cdot\Big(\prod_{i\in [r]}Q_{a_i^{(x)},h(a_i)}\Big)
            =
            O,
        \end{align*}
        as claimed.
    \end{proof}

    \begin{claim}
    \label{claim_1559_0803}
        $\mathfrak{W}$ is a quantum assignment for the $\X,\Gamma\Y$ game.
    \end{claim}

    \begin{proof}
        %Take two distinct homomorphisms $h,h':\A\to\Y$ and a vertex $x\in X$. We can rearrange the factors in the product $W_{x,h}W_{x,h'}$ as
%\begin{align*}
%    W_{x,h}W_{x,h'}
%    =
%     \Big(\prod_{a\in A}Q_{a^{(x)},h(a)}\Big)
%      \Big(\prod_{a'\in A}Q_{a'^{(x)},h'(a')}\Big)
%      =
%      \prod_{a\in A}Q_{a^{(x)},h(a)}Q_{a^{(x)},h'(a)}
%\end{align*}
%(where we are again using that $\mathfrak{Q}$ is $\diam(\A)$-compatible).
%
%From $h\neq h'$, we deduce that there exists some $a\in A$ such that $h(a)\neq h'(a)$. Since $\mathfrak{Q}$ is a quantum assignment, it follows that the expression above gives the zero projector, as required.
%
%Furthermore, we have
For each vertex $x\in X$, we have
\begin{align*}
    \sum_{h:\A\to\Y}W_{x,h}
    =
    \sum_{h:\A\to\Y}\prod_{a\in A}Q_{a^{(x)},h(a)}
    =
    \sum_{h:A\to Y}\prod_{a\in A}Q_{a^{(x)},h(a)}
    =
    \prod_{a\in A}\sum_{y\in Y}Q_{a^{(x)},y}
    =\prod_{a\in A}\id_\HH
    =\id_\HH,
\end{align*}
where the second equality holds because of Claim~\ref{claim_2911_1529}. It follows that $\mathfrak{W}$ is a quantum assignment, as claimed.
\end{proof}

\begin{claim}
\label{claim_1655_2911}
    The quantum assignment $\mathfrak{W}$ is perfect.
\end{claim}

\begin{proof}
    Take a symbol $T\in\tau$ of arity $t$, a tuple $\bx=(x_1,\dots,x_{t})\in T(\X)$, and a tuple $\bh=(h_1,\dots,h_{t})$ of homomorphisms $h_i:\A\to\Y$ such that $\bh\not\in T(\Gamma\Y)$.
 The claim would follow if we manage to show that 
\begin{align}
    \label{eqn_1652_2111}
    \prod_{i\in [t]}W_{x_i,h_i}=O.
\end{align}
%

Suppose, for the sake of contradiction, that~\eqref{eqn_1652_2111} is false.
%
Consider the $\rho$-structure $\B_{T}$. We aim to define a homomorphism $\ell:\B_T\to\Y$. 
%
Using the fact that the Pultr template $\mathfrak{T}$ is connected, we proceed as follows. Take $b\in B_T$. Since $\B_T$ is connected, there must exist some symbol $R\in\rho$ of arity $r$, some tuple $\bb\in R(\B_T)$, and some index $j\in [r]$ such that $b=b_j$. Using the second property of connected Pultr templates, we deduce that $\bb=\epsilon_{i,T}(\ba)$ for some $\ba\in R(\A)$ and some $i\in [t]$. Recalling that $h_i$ is a map from $A$ to $Y$, we define
\begin{align}
\label{eqn_1611_0803}
    \ell(b)=h_i(a_j).
\end{align}

\begin{subclaim}
    The map $\ell:B_T\to Y$ is well defined.
\end{subclaim}
\begin{proof}
    Suppose that there exist $\tilde R\in\rho$ of arity $\tilde r$, $\tilde\bb\in \tilde R(\B_T)$, $\tilde j\in [\tilde r]$, $\tilde\ba\in \tilde R(\A)$, and $\tilde i\in [t]$ such that $b=\tilde b_{\tilde j}$ and $\tilde\bb=\epsilon_{\tilde i,T}(\tilde\ba)$. Observe that
    \begin{align}
    \label{eqn_1604_2911}
        a_j^{(x_i)}
        =
        [\epsilon_{i,T}(a_j)]^{(\bx)}
        =
        b_j^{(\bx)}
        =
        b^{(\bx)}
        =
        \tilde b_{\tilde j}^{(\bx)}
        =
        [\epsilon_{\tilde i,T}(\tilde a_{\tilde j})]^{(\bx)}
        =
        \tilde a_{\tilde j}^{(x_{\tilde i})}.
    \end{align}
%
    Furthermore, given any two elements $\alpha,\alpha'\in A$ and any two indices $\iota,\iota'\in [t]$, we have
    \begin{align*}
        \dist_{\Lambda\X}(\alpha^{(x_\iota)},\alpha'^{(x_{\iota'})})
        =
        \dist_{\Lambda\X}([\epsilon_{\iota,T}(\alpha)]^{(\bx)},[\epsilon_{\iota',T}(\alpha')]^{(\bx)})
        \leq 
        \diam(\B_T)
        \leq \diam(\mathfrak{T})
        \leq k'.
    \end{align*}
    As a consequence, the terms in the product 
    \begin{align*}
        \prod_{i\in[t]}W_{x_i,h_i}=
        \prod_{i\in[t]}\prod_{a\in A}Q_{a^{(x_i)},h_i(a)}
    \end{align*}
    can be rearranged in a way that the two projectors $Q_{a_j^{(x_i)},h_i(a_j)}$ and $Q_{\tilde a_{\tilde j}^{(x_{\tilde i})},h_{\tilde i}(\tilde a_{\tilde j})}$ appear consecutively. As we are assuming that the product above is nonzero, we deduce from~\eqref{eqn_1604_2911} and from the fact that $\mathfrak{Q}$ is a perfect quantum assignment that $h_i(a_j)=h_{\tilde i}(\tilde a_{\tilde j})$. This means that the function $\ell:B_T\to Y$ is well defined, as claimed. 
\end{proof}

\begin{subclaim}
\label{claim_1925_2911}
    The map $\ell$ is a homomorphism from $\B_T$ to $\Y$.
\end{subclaim}
\begin{proof}
    Take a symbol $R\in\rho$ and a tuple $\bb\in R(\B_T)$. Using the connectivity of $\mathfrak{T}$, we find some $\ba\in R(\A)$ and some $i\in [t]$ such that $\bb=\epsilon_{i,T}(\ba)$.
    %
    It then follows from the description of $\ell$ that $\ell(\bb)=h_i(\ba)$. Since 
    $h_i$ is a homomorphism from $\A$ to $\Y$, it preserves $R$. Therefore, we have that $h_i(\ba)\in R(\Y)$, thus proving the claim.
\end{proof}

\begin{subclaim}
\label{claim_1924_2911}
    The equality $\ell\circ\epsilon_{i,T}=h_i$ holds for each $i\in [t]$.
\end{subclaim}
\begin{proof}
    Take $a\in A$, and call $b=\epsilon_{i,T}(a)$. Since the $\rho$-structure $\A$ is connected, there exists $R\in\rho$ of arity $r$, $\ba\in R(\A)$, and $j\in[r]$ such that $a=a_j$. Define $\bb=\epsilon_{i,T}(\ba)$.
    Since $\epsilon_{i,T}$ is a homomorphism, $\bb\in R(\B_T)$. Note also that $b=b_j$. By definition of $\ell$, we have that $\ell(b)=h_i(a_j)$. Therefore,
    \begin{align*}
        h_i(a)
        =
        h_i(a_j)
        =
        \ell(b)
        =
        \ell(b_j)
        =
        \ell(\epsilon_{i,T}(a_j))
        =
        \ell\circ\epsilon_{i,T}(a),
    \end{align*}
    so the maps $\ell\circ\epsilon_{i,T}$ and $h_i$ coincide.
\end{proof}
%
Using Claim~\ref{claim_1924_2911}, we find
\begin{align*}
    \bh
    =
    (h_1,\dots,h_t)
    =
    (\ell\circ\epsilon_{1,T},\dots,\ell\circ\epsilon_{t,T}).
\end{align*}
Since, by Claim~\ref{claim_1925_2911}, $\ell$ is a homomorphism $\B_T\to\Y$, it follows from Definition~\ref{defn_central_pultr_functor} that $\bh\in T(\Gamma\Y)$, contradicting our assumption. This concludes the proof of Claim~\ref{claim_1655_2911}.
\end{proof}

\begin{claim}
    The quantum assignment $\mathfrak{W}$ is $k$-compatible.
\end{claim}

\begin{proof}
    Take two vertices $x,x'\in X$ such that $\dist_\X(x,x')=d\leq k$. We need to show that
    \begin{align}
        \label{1930_2911}
        \Big[W_{x,h},W_{x',h'}\Big]=O
    \end{align}
    for each $h,h':\A\to\Y$. The fact that $\dist_\X(x,x')=d$ means that there exist
    \begin{itemize}
        \item symbols $T_1,\dots,T_d\in\tau$;
        \item vertices $x_0=x,x_1,\dots,x_d=x'\in X$;
        \item tuples $\bx^{(i)}\in T_i(\X)$ for each $i\in [d]$;
        \item indices $\alpha_i,\omega_i\in[\ar(T_i)]$ for each $i\in[d]$
    \end{itemize}
    such that
        $x_{i-1}=x^{(i)}_{\alpha_i}$ and $x_i=x^{(i)}_{\omega_i}$
    for each $i\in [d]$. Take $a,a'\in A$. Using the triangle inequality, we obtain
    \begin{align}
    \label{eqn_1953_2911}
    \notag
        \dist_{\Lambda\X}(a^{(x)},a'^{(x')})
        &\leq
        \dist_{\Lambda\X}(a^{(x)},a^{(x')})+
        \dist_{\Lambda\X}(a^{(x')},a'^{(x')})\\
        &\leq \sum_{i\in [d]}\dist_{\Lambda\X}(a^{(x_{i-1})},a^{(x_i)})+
        \dist_{\Lambda\X}(a^{(x')},a'^{(x')}).
    \end{align}
    For each $i\in [d]$, we have
    \begin{align*}
        a^{(x_{i-1})}
        &=
        a^{(x^{(i)}_{\alpha_i})}
        =
        [\epsilon_{\alpha_i,T_i}(a)]^{\bx^{(i)}}\quad\quad\mbox{and}\quad\quad
        a^{(x_{i})}
        =
        a^{(x^{(i)}_{\omega_i})}
        =
        [\epsilon_{\omega_i,T_i}(a)]^{\bx^{(i)}}.
    \end{align*}
    Hence,



    \begin{align*}
        \dist_{\Lambda\X}(a^{(x_{i-1})},a^{(x_i)})
        &=
        \dist_{\Lambda\X}([\epsilon_{\alpha_i,T_i}(a)]^{\bx^{(i)}},[\epsilon_{\omega_i,T_i}(a)]^{\bx^{(i)}})
        \leq 
        \dist_{\B_T}(\epsilon_{\alpha_i,T_i}(a),\epsilon_{\omega_i,T_i}(a))\\
        &\leq
        \diam(\B_T)
        \leq
        \diam(\mathfrak{T}).
    \end{align*}
    Also, reasoning as in the proof of Claim~\ref{eqn_2911_1449}, we have
    \begin{align*}
        \dist_{\Lambda\X}(a^{(x')},a'^{(x')})
        \leq
        \dist_\A(a,a')
        \leq
        \diam(\A)
        \leq\diam(\mathfrak{T}).
    \end{align*}
    As a consequence,~\eqref{eqn_1953_2911} yields
    \begin{align*}
        \dist_{\Lambda\X}(a^{(x)},a'^{(x')})
        &\leq (d+1)\diam(\mathfrak{T})\leq (k+1)\diam(\mathfrak{T})=k'.
    \end{align*}
    We can then leverage the $k'$-compatibility of $\mathfrak{Q}$ to conclude that the projectors $Q_{a^{(x)},y}$ and $Q_{a'^{(x')},y'}$ commute for each $y,y'\in Y$ and, thus, 
\begin{align*}
    \Big[W_{x,h},W_{x',h'}\Big]
    =
    \Big[\prod_{a\in A}Q_{a^{(x)},h(a)},\prod_{a'\in A}Q_{a'^{(x')},h'(a')}\Big]
    =
    O,
\end{align*}
as claimed.
\end{proof}
    In summary, we have shown that $\mathfrak{W}$ yields a perfect $k$-compatible quantum assignment for the $\X,\Gamma\Y$ game, which means that $\X\leadsto^k\Gamma\Y$. 
\end{proof}



