We now turn to prove the converse direction of the quantum Pultr adjunction.
%
We say that a $(\rho,\tau)$-Pultr template $\mathfrak{T}$ is \textit{faithful} if the following two properties hold for each $T\in\tau$:
\begin{itemize}
    \item $B_{T}=\bigsqcup_{i\in [\ar(T)]}\Imm(\epsilon_{i,T})$; 
    \item $\epsilon_{i,T}$ yields an isomorphism\footnote{I.e., a bijective homomorphism whose inverse map is a homomorphism.} from $\A$ to the substructure of $\B_T$ induced by $\Imm(\epsilon_{i,T})$ for each $i\in[\ar(T)]$.
\end{itemize}

\begin{example}
Fix a digraph $\GG$, and let $n$ be the number of its vertices. 
Let $\rho$ be the signature containing a unique, binary symbol $R$, and consider the $(\rho,\rho)$-Pultr template $\mathfrak{T}$ such that $\A$ consists of $n$ isolated vertices, $\B_R$ is the direct product $\GG\times\K_2$ (where $\K_2$ is the graph consisting of a single, undirected edge), and $\epsilon_{1,R},\epsilon_{2,R}$ are the two natural injections of $\A$ into $\B_R$.
%
As described in~\cite[\S2]{foniok2013adjoint}, the left and central Pultr functors corresponding to $\mathfrak{T}$ are the functors $\Lambda'$ and $\Gamma'$ from Example~\ref{ex_some_pultr_functors}. Observe that the Pultr template $\mathfrak{T}$ is faithful.
\end{example}


\begin{thm*}
[Theorem~\ref{thm_quantum_adjunction_faithful} restated]
    Let $\mathfrak{T}$ be a faithful $(\rho,\tau)$-Pultr template, let $\X$ and $\Y$ be a $\tau$-structure and a $\rho$-structure, respectively, let $k\in\N$, and suppose that $\X\leadsto^{k}\Gamma\Y$. Then $\Lambda\X\leadsto^{k}\Y$.
\end{thm*}
%
\begin{proof}
    Fix a perfect $k$-compatible quantum assignment $\mathfrak{Q}=\{Q_{x,f}:x\in X,f:\A\to\Y\}$ for the $\X,\Gamma\Y$ game. For $a\in A$, $x\in X$, and $y\in Y$, consider the linear application
    \begin{align}
    \label{eqn_1615_2211_a}
        W_{a^{(x)},y}
        =
        \sum_{\substack{f:\A\to\Y\\f(a)=y}}Q_{x,f}.
    \end{align}
    Also, for $T\in\tau$ of arity $t$, $\bx\in T(\X)$, $b\in B_{T}$, and $y\in Y$, consider the linear application
    \begin{align}
    \label{eqn_1615_2211_b}
        W_{b^{(\bx)},y}
        =
        \sum_{\substack{\ell:\B_{T}\to\Y\\\ell(b)=y}}\;\prod_{i\in [t]}Q_{x_i,\ell\circ\epsilon_{i,T}}.
    \end{align}
    We aim to show that the set 
    \begin{align}
    \label{eqn_1727_2211}
    \mathfrak{W}=\{W_{a^{(x)},y}\suchThat a\in A, x\in X, y\in Y\}\cup \{W_{b^{(\bx)},y}\suchThat  T\in\tau, \bx\in T(\X), b\in B_{T}, y\in Y\}
    \end{align}
    is a perfect $k$-compatible quantum assignment for the $\Lambda\X,\Y$ game.
%
    Before starting off with the analysis of $\mathfrak{W}$, it shall be useful to prove the next two facts.


    \begin{claim}
    \label{claim_1628_2211}
        Fix a symbol $T\in\tau$ of arity $t$, a tuple $\bx\in T(\X)$, and a function $\ell:B_{T}\to Y$. If 
        \begin{align}
            \label{16_09_2211}
            \prod_{i\in [t]}Q_{x_i,\ell\circ\epsilon_{i,T}}\neq O,
        \end{align}
        then $\ell$ is a homomorphism from $\B_{T}$ to $\Y$.
    \end{claim}
    %
    \begin{proof}
    %Henceforth, for the sake of readability, we shall often remove the index $R'$ from $\B_{R'}$ and $\epsilon_{i,R'}$ when it is clear from the context.
    %
    Using that the quantum assignment $\mathfrak{Q}$ is $k$-compatible (and thus, in particular, $1$-compatible), from the fact that $\bx\in T(\X)$ we deduce that the tuple $(\ell\circ\epsilon_{1,T},\dots,\ell\circ\epsilon_{t,T})$ belongs to the relation $T(\Gamma\Y)$. Hence, there exists some homomorphism $\tilde\ell:\B_T\to\Y$ such that $\tilde\ell\circ\epsilon_{i,T}=\ell\circ\epsilon_{i,T}$ for each $i\in [t]$. We now use the fact that the Pultr Template $\mathfrak{T}$ is faithful---specifically, that the union of $\Imm(\epsilon_{i,T})$ over $i\in [t]$ is the whole set $B_T$. We deduce that $\ell=\tilde\ell$, which concludes the proof of the claim.
    \end{proof}

    \begin{claim}
    \label{claim_1248_2311}
        Fix a symbol $T\in\tau$ of arity $t$, a tuple $\bx\in T(\X)$, and two distinct homomorphisms $\ell,\ell':\B_{T}\to \Y$. It holds that
        \begin{align*}
        \Big(\prod_{i\in [t]}Q_{x_i,\ell\circ\epsilon_{i,T}}\Big)\cdot \Big(\prod_{i\in [t]}Q_{x_i,\ell'\circ\epsilon_{i,T}}\Big)=O.
    \end{align*}
    \end{claim}
    %
    \begin{proof}
        Since $\mathfrak{T}$ is faithful, there exists some $j\in[t]$ such that $\ell\circ\epsilon_{j,T}\neq\ell'\circ\epsilon_{j,T}$, which means that $Q_{x_j,\ell\circ\epsilon_{j,T}}\cdot Q_{x_j,\ell'\circ\epsilon_{j,T}}=O$. The $1$-compatibility of $\mathfrak{Q}$ allows rearranging at wish the projectors $Q_{x_i,\ell\circ\epsilon_{i,T}}$ and $Q_{x_i,\ell'\circ\epsilon_{i,T}}$ appearing in the product on the left-hand side of~\eqref{claim_1248_2311} and, thus, the claim follows.
    \end{proof}

    \begin{claim}
    \label{claim_1308_2311}
        The linear applications defined in~\eqref{eqn_1615_2211_a} and~\eqref{eqn_1615_2211_b} respect the equivalence relation $\sim$ of Definition~\ref{defn_left_pultr_functor}.
    \end{claim}

\begin{proof}
    Recall that $\sim$ identifies vertices $v=a^{(x_j)}$ and $w=[\epsilon_{j}(a)]^{(\bx)}$ for each $T\in\tau$, $\bx\in T(\X)$, $j\in [\ar(T)]$, and $a\in A$. Thus, we need to show that the equality 
    \begin{align}
    \label{eqn_1723_2211}
        W_{v,y}
        =
        W_{w,y}
    \end{align}
    holds for $v$ and $w$ as above, for any $y\in Y$. Observe that
    \begin{align}
    \label{eqn_1704_2211}
        W_{w,y}
        =
        \sum_{\substack{\ell:\B_T\to\Y\\\ell(\epsilon_{j,T}(a))=y}}\;\prod_{i\in [t]}Q_{x_i,\ell\circ\epsilon_{i,T}}.
    \end{align}
    For each $i\in [t]$, let $\B_i$ be the substructure of $\B_T$ induced by $\Imm(\epsilon_{i,T})$; since $\mathfrak{T}$ is faithful, $\B_T$ is the disjoint union of the $\rho$-structures $\B_i$'s. 
    Consider the two sets
    \begin{align*}
        \mathcal{L}&=\{\ell:\B_T\to\Y\mbox{ s.t. } \ell(\epsilon_{j,T}(a))=y\},\\ 
        \mathcal{\hat{L}}&=\{(\ell_1,\dots,\ell_{t})\mbox{ s.t. }\ell_i:\B_i\to\Y\;\forall i\in [t],\; \ell_j(\epsilon_{j,T}(a))=y\}.
