\begin{claim} The quantum assignment $\mathfrak{W}$ is perfect.
\end{claim}
\begin{proof}
Fix a symbol $R\in\rho$ of arity $r$ and a tuple $\by\in Y^r\setminus R(\Y)$. Recall from Definition~\ref{defn_left_pultr_functor} that the elements of $R(\Lambda\X)$ can be of two types, based on whether they correspond to $(i)$ elements of $R(\A)$, or $(ii)$ elements of $R(\B_{T})$ for some $T\in\tau$.
%
In the first case, we have $\ba^{(x)}=(a_1^{(x)},\dots,a_{r}^{(x)})\in R(\Lambda\X)$ for some $\ba\in R(\A)$ and $x\in X$. Observe that
\begin{align*}
    \prod_{j\in [r]}W_{a_j^{(x)},y_j}
    =
    \prod_{j\in [r]}\sum_{\substack{f:\A\to\Y\\f(a_j)=y_j}}Q_{x,f}.
\end{align*}
Distributing the product over the sums in the expression above, and recalling that $\{Q_{x,f}\}_{f:\A\to\Y}$ is a PVM and, thus, its members are mutually orthogonal projectors, we obtain
\begin{align*}
    \prod_{j\in [r]}W_{a_j^{(x)},y_j}
    =
    \sum_{\substack{f:\A\to\Y\\f(\ba)=\by}}Q_{x,f}=O,
\end{align*}
since $\ba\in R(\A)$ and $\by\not\in R(\Y)$. This means that the assignment $\mathfrak{W}$ is perfect for tuples $\ba^{(x)}\in R(\Lambda\X)$ of type $(i)$.

Consider now a tuple of type $(ii)$---i.e., a tuple $\bb^{(\bx)}\in R(\Lambda\X)$ for some $T\in\tau$ of arity $t$, $\bx\in T(\X)$, and $\bb\in R(\B_{T})$. For $\ell:\B_{T}\to\Y$, define $Q_{\bx,\ell}=\prod_{i\in [t]}Q_{x_i,\ell\circ\epsilon_{i,T}}$. We know from Claims~\ref{claim_1248_2311} and~\ref{eqn_1348_2311} that the family $\{Q_{\bx,\ell}\}_{\ell:\B_{T}\to\Y}$ contains mutually orthogonal projectors. Hence, we can proceed in the same way as in the previous case:
\begin{align*}
    \prod_{j\in [r]}W_{b_j^{(\bx)},y_j}
    =
    \prod_{j\in [r]}\;\sum_{\substack{\ell:\B_{T}\to\Y\\\ell(b_j)=y_j}}Q_{\bx,\ell}
    =
    \sum_{\substack{\ell:\B_{T}\to\Y\\\ell(\bb)=\by}}Q_{\bx,\ell}=O,
\end{align*}
since $\bb\in R(\B_{T})$ and $\by\not\in R(\Y)$. Thus, $\mathfrak{W}$ is perfect for tuples of type $(ii)$, too.
\end{proof}

\begin{claim} The quantum assignment $\mathfrak{W}$ is $k$-compatible.
\end{claim}
\begin{proof}
    Take four vertices $a^{(x)},\tilde a^{(\tilde x)},b^{(\bx)},\tilde b^{(\tilde\bx)}$ of $\Lambda\X$, where $x,\tilde x\in X$, $a,\tilde a\in A$, $\bx,\tilde\bx\in T(\X)$ for some symbol $T\in\tau$ or arity $t$, and $b,\tilde b\in B_{T}$. Take also two indices $i,j\in [t]$. It is easy to check from Definition~\ref{defn_left_pultr_functor} that
    \begin{align*}
        \dist_\X(x,\tilde x)&\leq \dist_{\Lambda\X}(a^{(x)},\tilde a^{(\tilde x)}),\\
        \dist_\X(x_i,\tilde x_j)&\leq \dist_{\Lambda\X}(b^{(\bx)},\tilde b^{(\tilde\bx)}),\\
        \dist_\X(x,\tilde x_j)&\leq\dist_{\Lambda\X}(a^{(x)},\tilde b^{(\tilde \bx)}),\;\;\mbox{and}\\
        \dist_{\X}(x_i,\tilde x)&\leq\dist_{\Lambda\X}(b^{(\bx)},\tilde a^{(\tilde x)}).
    \end{align*}
    Therefore, if $\dist_{\Lambda\X}(a^{(x)},\tilde a^{(\tilde x)})\leq k$ (resp. $\dist_{\Lambda\X}(b^{(\bx)},\tilde b^{(\tilde\bx)})\leq k$, $\dist_{\Lambda\X}(a^{(x)},\tilde a^{(\tilde x)})\leq k$, $\dist_{\Lambda\X}(b^{(\bx)},\tilde a^{(\tilde x)})\leq k$), the $k$-compatibility of the assignment $\mathfrak{Q}$ implies that the projectors $Q_{x,f}$, $Q_{\tilde x,\tilde f}$, $Q_{x_i,\ell\circ\epsilon_{i,T}}$, and $Q_{\tilde x_{\tilde j},\tilde \ell\circ\epsilon_{j,T}}$ appearing in the correponding definitions~\eqref{eqn_1615_2211_a} and~\eqref{eqn_1615_2211_b} commute with each other. As consequence, for each $y,y'\in Y$, we have $[W_{a^{(x)},y},W_{\tilde a^{(\tilde x)},y'}]=O$ (resp. $[W_{b^{(\bx)},y},W_{\tilde b^{( \tilde \bx)},y'}]=O$, $[W_{a^{(x)},y},W_{\tilde b^{( \tilde \bx)},y'}]=O$, $[W_{b^{(\bx)},y},W_{\tilde a^{( \tilde x)},y'}]=O$). This shows that the assignment $\mathfrak{W}$ is $k$-compatible, thus concluding the proof of the claim.
\end{proof}
In summary, we have proved that the set $\mathfrak{W}$ defined in~\eqref{eqn_1727_2211} yields a perfect $k$-compatible quantum assignment for the $\Lambda\X,\Y$ game, thus showing that $\Lambda\X\leadsto^k\Y$.
\end{proof}

In the classical setting, the adjunction between $\Gamma$ and $\Lambda$ straightforwardly implies that $\Gamma$ and $\Lambda$ are both functors between the thin categories $\mathbf{Str}(\rho)$ and $\mathbf{Str}(\tau)$, in that they satisfy the implications $\X\to\Y\;\Rightarrow\;\Gamma\X\to\Gamma\Y$ for each pair of $\rho$-structures $\X,\Y$, and $\X'\to\Y'\;\Rightarrow\;\Lambda\X'\to\Lambda\Y'$ for each pair of $\tau$-structures $\X',\Y'$. 
%
The adjunction relation of Theorems~\ref{thm_adjunction_pultr_1} and~\ref{thm_quantum_adjunction_faithful} allows establishing analogous results for locally compatible quantum strategies, provided that the Pultr template is connected or faithful, respectively. These functoriality properties shall be useful in the next section.

\begin{cor}
\label{cor_gamma_quantum_functor}
    Let $\mathfrak{T}$ be a connected $(\rho,\tau)$-Pultr template, let $\X$ and $\Y$ be $\rho$-structures, let $k\in\N$, let $k'=(k+1)\cdot\diam(\mathfrak{T})$, and suppose that $\X\leadsto^{k'}\Y$. Then $\Gamma\X\leadsto^{k}\Gamma\Y$.
\end{cor}
%
\begin{proof}
    Applying Theorem~\ref{thm_pultr_adjoints} to $\Gamma\X\to\Gamma\X$, we find $\Lambda\Gamma\X\to\X$. Composing the latter homomorphism with the quantum homomorphism $\X\leadsto^{k'}\Y$ via Proposition~\ref{prop_compose_classic_quantum_homos} yields $\Lambda\Gamma\X\leadsto^{k'}\Y$. We can then apply Theorem~\ref{thm_adjunction_pultr_1} to conclude that $\Gamma\X\leadsto^k\Gamma\Y$, as claimed.
\end{proof}

\begin{cor}
\label{cor_left_pultr_functor}
    Let $\mathfrak{T}$ be a faithful $(\rho,\tau)$-Pultr template, let $\X$ and $\Y$ be $\tau$-structures, let $k\in\N$, and suppose that $\X\leadsto^{k}\Y$. Then $\Lambda\X\leadsto^{k}\Lambda\Y$.
\end{cor}
%
\begin{proof}
 From $\Lambda\Y\to\Lambda\Y$, we obtain $\Y\to\Gamma\Lambda\Y$ via Theorem~\ref{thm_pultr_adjoints}. Composing the latter homomorphism with the quantum homomorphism $\X\leadsto^{k}\Y$ via Proposition~\ref{prop_compose_classic_quantum_homos} yields $\X\leadsto^{k}\Gamma\Lambda\Y$. We can then apply Theorem~\ref{thm_quantum_adjunction_faithful} to conclude that $\Lambda\X\leadsto^k\Lambda\Y$, as claimed.   
\end{proof}

\begin{rem}
\label{rem_pultr_preserves_H}
We conclude this section by noting that the proofs of Theorems~\ref{thm_adjunction_pultr_1} and~\ref{thm_quantum_adjunction_faithful} show that Pultr reductions preserve the Hilbert space $\HH$ witnessing perfect (locally compatible) quantum assignments. As we shall see later, together with a result from~\cite{simul_banakh}, this implies that the dimension of the shared quantum system witnessing perfect quantum assignments in Conjecture~\ref{conj_d_to_1_khot_quantum} must be unbounded, see Remark~\ref{rem_higher_consistency_gap}.
\end{rem}






\section{The quantum chromatic gap via $d$-to-$1$ games}
\label{sec_reductions}

The goal of this section is to prove that all links in a chain of reductions from $d$-to-$1$ games to $3$ vs. $\mathcal{O}(1)$ colouring preserve quantum completeness and, thus, can be used to transfer pseudo-telepathy. We divide the task into three phases, described in Sections~\ref{subsec_preprocessing},~\ref{subsec_GS_reduction}, and~\ref{subsec_line_digraph}, respectively. The results are then combined in Section~\ref{subsect_putting_all_together}, thus yielding a proof of the main Theorem~\ref{thm_main}. 

\subsection{From $d$-to-$1$ games to $d$-to-$d$ games} 
\label{subsec_preprocessing}
As we shall see in the next section, the known reductions from label cover to graph colouring based on a Markov chain having specific spectral properties require that the constraints in the input label-cover instance be $d$-to-$d$ rather than $d$-to-$1$. Hence, 
the first step is to reduce $d$-to-$1$ instances to $d$-to-$d$ instances. To that end, we make use of a sequence of transformations from~\cite{Dinur09:sicomp}.

Take $m,d\in\N$, and let $A$ be an alphabet set of size $md$. We say that a set $S\subseteq A^2$ is \textit{$d$-to-$d$} if the Boolean $md\times md$ matrix encoding $S$ can be written as $P_\mu(I_m\otimes J_d)P_\nu$ for two permutations $\mu,\nu$ of $[md]$, where $I$ and $J$ are the identity and all-one matrices, respectively, and $P_\mu$ and $P_\nu$ are the permutation matrices associated with $\mu$ and $\nu$, respectively.
%
We say that a label-cover instance $\Phi=(X,E,A,\pi,\phi)$ is \textit{$d$-to-$d$} if $|A|=md$ for some $m\in\N$, and for each $\bx\in E$ the set $\phi_\bx$ is $d$-to-$d$.
%


In order for the reduction in Section~\ref{subsec_GS_reduction} to go through, 
we shall need a slightly different notion of classical satisfiability 
for label-cover instances that does not make use of weights. Exactly the same notion is used in various approximation hardness results based on the UGC or $d$-to-$1$ games Conjecture, see in particular~\cite{khot2008vertex,Dinur09:sicomp}.
%
Given an integer $t\in\N$, 
%
we denote by ${A\choose \leq t}$ the set of subsets of the alphabet $A$ of size at most $t$.
%
A \textit{$t$-assignment} for a label-cover instance $\Phi$ is a function $f:X\to{A\choose \leq t}$. We say that $f$ satisfies a constraint $\bx=(x_1,x_2)\in E$ if there exist $a\in f(x_1)$, $b\in f(x_2)$ such that $\phi_\bx(a,b)=1$. 
We define
\begin{align*}
    \isat_t(\Phi)
    =
    \frac{1}{|X|}\cdot \max_{S\subseteq X}\Big\{|S|\suchThat\exists\mbox{ $t$-assignment for $\Phi$ satisfying all constraints induced by $S$}\Big\}.
\end{align*}
%


Recall that, following~\cite{Khot02stoc}, we have defined label cover in Section~\ref{subsec_CSP_predicates} as a \textit{weighted} CSP, where edges carry a probability distribution $\pi$ that appears in the definition of $\sat(\Phi)$. 
%
Since the probability distribution $\pi$ does not appear in the definition of $\isat_t(\Phi)$ (and, as discussed in Section~\ref{sec_classical_quantum_CSPs}, it also does not appear in the definition of perfect quantum assignments), we shall
now consider \textit{unweighted} label-cover instances, where $\pi$ is assumed to be, say, the uniform distribution over $E$.
We denote an unweighted label-cover instance simply by $\Phi=(X,E,A,\phi)$. 

The next result shows that, assuming Conjecture~\ref{conj_d_to_1_khot_quantum}, there exist $d$-to-$d$ instances admitting a perfect locally compatible quantum assignment but arbitrarily small $\isat_t$ value. Its proof is deferred to Appendix~\ref{app_dinur_reductions}.

\begin{prop}
\label{prop_d_to_d_after_dinur}
    Suppose Conjecture~\ref{conj_d_to_1_khot_quantum} holds for some $d\geq 2$. 
Then for each $\epsilon>0$ and each $k,t\in\N$ there exists a $d$-to-$d$ instance $\Phi$ (on some alphabet size $n$) such that $\Phi$ admits a perfect $k$-compatible quantum assignment but
$\isat_t(\Phi)<\epsilon$.
\end{prop}











