\fi

We now present a reduction described in~\cite{Dinur09:sicomp} (in the case $d=2$) and in~\cite{GS20:icalp} (in the general case $d\geq 2$).
%
The starting point is the following, spectral-graph-theoretic result.

\begin{thm}[\cite{Dinur09:sicomp,GS20:icalp}]
\label{thm_transistion_matrix}
For each $2\leq d\in\N$ there exists a Markov chain on state set $\Omega=[2d]^d$ whose transition matrix $T=(t_{ij})$ has the following properties:
    \begin{itemize}
        \item $T$ is symmetric, i.e., the transition probabilities $t_{\bx,\by}$ and $t_{\by,\bx}$ are equal for each $\bx,\by\in\Omega$;
        \item the eigenvalue $1$ has multiplicity one in the spectrum of $T$, and all other eigenvalues have modulus strictly smaller than $1$;
        \item for $\bx=(x_1,\dots,x_d),\by=(y_1,\dots,y_d)\in\Omega$, $t_{\bx,\by}=0$ when $\{x_1,\dots,x_d\}\cap\{y_1,\dots,y_d\}\neq\emptyset$.
    \end{itemize}
\end{thm}

Let $\Phi=(X,E,[n],\phi)$ be an (unweighted) $d$-to-$d$ instance with alphabet $[n]$, where $n=md$ for some $m\in\N$.
%
Recall that, for each $\bx\in E$, the corresponding set of admitted labellings $\phi_\bx$ is $d$-to-$d$, meaning that there exists two permutations $\mu,\nu\in\Sym_{n}$ such that $\phi_\bx$ is encoded by the matrix $P_\mu(I_m\otimes J_d)P_\nu$. We shall call $\mu,\nu$ the permutations associated with $\bx$. 
%
On input $\Phi$, the reduction returns a digraph $\eta\Phi$ defined as follows. The vertex set is $\{(x,z):x\in X,\,z\in[2d]^n\}$.
%
The edge set contains those pairs $((x,z),(x',z'))$ of vertices for which
\begin{itemize}
    \item[$(i)$] 
    $(x,x')$ forms an edge in $E$;
    \item [$(ii)$] for each $i\in [m]$, the $(\alpha(i),\beta(i))$-th entry of the transition matrix $T$ of Theorem~\ref{thm_transistion_matrix} is nonzero, where $\mu,\nu$ are the permutations associated with the edge $(x,x')$ and
    \begin{equation}
        \label{eqn_1248_2411}
         \begin{aligned}
        \alpha(i)&=(z\circ\mu(di-d+1),z\circ\mu(di-d+2),\dots,z\circ\mu(di))\in [2d]^d,\\
        \beta(i)&=(z'\circ\nu(di-d+1),z'\circ\nu(di-d+2),\dots,z'\circ\nu(di))\in [2d]^d.
    \end{aligned}
    \end{equation}
\end{itemize}

The following soundness result was proved in~\cite{Dinur09:sicomp} for the case $d=2$, and in~\cite{GS20:icalp} for the case $d\geq 3$.

\begin{thm}[\cite{Dinur09:sicomp,GS20:icalp}]
\label{thm_soundess_third_reduction}
For each $\epsilon>0$ there exist $\epsilon'>0$, $t\in\N$ such that, given a $d$-to-$d$ instance $\Phi$, there are no independent sets of relative size $\epsilon$ in $\eta\Phi$ whenever $\isat_t(\Phi)<\epsilon'$. 
\end{thm}

We shall now prove that $\eta$ is quantum-complete.

\begin{thm}
\label{thm_quantum_completeness_dinur}
    Let $\Phi$ be a $d$-to-$d$ instance admitting a perfect $k$-compatible quantum assignment for some $k\in\N$. Then $\eta\Phi\leadsto^k\K_{2d}$.
\end{thm}


To establish Theorem~\ref{thm_quantum_completeness_dinur}, we use the results of Section~\ref{sec_pultr_functors}.
%
First of all, it shall be useful to see $\eta$ as the left Pultr functor associated with a suitable
Pultr template.
%
Let $\rho$ be the signature containing a unique, binary symbol $R$, and let $\tau$ be the signature containing a binary symbol $T_{\mu,\nu}$ for each choice of $\mu,\nu\in\Sym_n$.
%
Consider the $(\rho,\tau)$-Pultr template $\mathfrak{T}$ described as follows:
\begin{itemize}
    \item $\A$ is the union of $[2d]^n$ isolated vertices.
    \item For each symbol $T_{\mu,\nu}\in\tau$, $\B_{T_{\mu,\nu}}$ is a bipartite digraph with domain $B_1\sqcup B_2$, where $|B_1|=|B_2|=[2d]^n$. The edges of $\B_{T_{\mu,\nu}}$ (i.e., the elements of $R(\B_{T_{\mu,\nu}})$) are defined as follows. Given $z\in B_1$ and $z'\in B_2$, the pair $(z,z')$ forms an edge if and only if for each $i\in [m]$, the $(\alpha(i),\beta(i))$-th entry of the transition matrix $T$ is nonzero, with $\alpha(i)$ and $\beta(i)$ as in~\eqref{eqn_1248_2411}.
    \item For each symbol $T_{\mu,\nu}\in\tau$ and each $i\in [2]$, the homomorphism $\epsilon_{i,T_{\mu,\nu}}:\A\to\B_{T_{\mu,\nu}}$ sends $\A$ to the first or the second part of the domain of $\B_{T_{\mu,\nu}}$, depending on whether $i=1$ or $i=2$.
\end{itemize}

Let $\Lambda_\mathfrak{T}$ be the left Pultr functor corresponding to $\mathfrak{T}$. 
%
Given a $d$-to-$d$ instance $\Phi=(X,E,[n],\phi)$, let $\X_\Phi$ 
and $\dGames$ be the corresponding relational structures, as described in Section~\ref{subsec_CSP_homomorphisms}.
To spell this out,  $\X_\Phi$ 
is the $\tau$-structure having domain $X$ such that, for each $\mu,\nu\in\Sym_n$, 
\begin{align*}
T_{\mu,\nu}(\X_\Phi)=\{\bx\in E\suchThat \mu,\nu\mbox{ are the permutations associated with }\phi_\bx\}. 
\end{align*}
Moreover, $\dGames$ is the $\tau$-structure having domain $[n]$ and whose relations are defined as follows. Fix the matrix $H=[h_{ij}]=I_{m}\otimes J_d$.
For $\mu,\nu\in\Sym_n$, we let ${T_{\mu,\nu}}({\dGames})=\{(a,b)\in [n]^2:h_{\mu^{-1}(a),\nu^{-1}(b)}=1\}$. 
%
It is then straightforward to check that 
\begin{align}
\label{eqn_1349_1812}
\eta\Phi=\Lambda_{\mathfrak{T}}\X_\Phi.
\end{align}
%
%
%
The proof of the next fact uses the same ideas as in~\cite{Dinur09:sicomp,GS20:icalp}, though stated in the language of Pultr functors as needed in our setting.

%It shall be convenient to view $\Phi$ as an instance of $\CSP(\dGames)$, where $\dGames$ is the structure encoding $d$-to-$d$ Games, defined as follows. Fix the matrix $H=(h_{ij})=I_{m}\otimes J_d$, where $I$ is the identity matrix and $J$ is the all-one matrix.
%Let $\Sym_n$ be the set of permutations of $[n]$.
%For $\mu,\nu\in\Sym_n$, consider the set ${R_{\mu,\nu}}({\dGames})=\{(a,b)\in [n]^2:h_{\mu^{-1}(a),\nu^{-1}(b)}=1\}$. 
%
%The relations of $\dGames$ are precisely the sets ${R_{\mu,\nu}}({\dGames})$, for each choice of permutations $\mu,\nu\in\Sym_n$.
%



\begin{prop}
\label{prop_simple_lambda_dinur}
    $\Lambda_{\mathfrak{T}}\dGames\to\K_{2d}$.
\end{prop}
\begin{proof}

Take a vertex $a^{(x)}$ of $\Lambda_{\mathfrak{T}}\dGames$ where
    $a\in [2d]^n$ and $x\in [n]$, and define 
        $\xi(a^{(x)})=a(x)$.
    Also, for $\mu,\nu\in\Sym_n$, take a vertex $z^{(\bx)}$ of $\Lambda_{\mathfrak{T}}\dGames$, where $z\in\B_{T_{\mu,\nu}}$ and $\bx=(x_1,x_2)\in T_{\mu,\nu}(\dGames)$. Recall that the domain of $\B_{T_{\mu,\nu}}$ is split into two disjoint parts $B_1$ and $B_2$, each of size $[2d]^n$.    Let $\xi(z^{(\bx)})=z(x_1)$ if $z\in B_1$, and $\xi(z^{(\bx)})=z(x_2)$ if $z\in B_2$.
%
    We claim that the map $\xi$ yields the required homomorphism from $\Lambda_{\mathfrak{T}}\dGames$ to $\K_{2d}$.

    First of all, we need to make sure that $\xi$ respects the equivalence relation of Definition~\ref{defn_left_pultr_functor} and is thus well defined. Take $\mu,\nu\in\Sym_n$, $\bx\in T_{\mu,\nu}(\dGames)$, $j\in [2]$, and $a\in A=[2d]^n$. The two vertices $a^{(x_j)}$ and $[\epsilon_{j}(a)]^{(\bx)}$ are identified in $\Lambda_{\mathfrak{T}}\dGames$, so we need to prove that
    \begin{align}
    \label{eqn_1119_2411}
        \xi(a^{(x_j)})
        =
        \xi([\epsilon_{j}(a)]^{(\bx)}).
    \end{align}
    (We are dropping the index $T_{\mu,\nu}$ from $\epsilon_{j,T_{\mu,\nu}}$ to improve readability.)
    It follows from the definition of $\xi$ and $\epsilon_j$ that $\xi([\epsilon_{j}(a)]^{(\bx)})=a(x_1)$ if $j=1$, and $\xi([\epsilon_{j}(a)]^{(\bx)})=a(x_2)$ if $j=2$. Hence, $\xi([\epsilon_{j}(a)]^{(\bx)})=a(x_j)$. Since $\xi(a^{(x_j)})=a(x_j)$,~\eqref{eqn_1119_2411} follows.

    We now show that $\xi$ preserves the edge relation and is thus a homomorphism from $\Lambda_{\mathfrak{T}}\dGames$ to $\K_{2d}$. $\A$ has no edges, so we only need to consider the edges of $\Lambda_{\mathfrak{T}}\dGames$ coming from $\B_{T_{\mu,\nu}}$. Take $\bx\in T_{\mu,\nu}(\dGames)$ and $(z,z')\in R(\B_{T_{\mu,\nu}})$, so $(z^{(\bx)},z'^{(\bx)})\in R(\Lambda_{\mathfrak{T}}\dGames)$. (Recall that $R$ denotes the unique, binary symbol of the signature $\rho$.)
    %
    We have $\xi(z^{(\bx)},z'^{(\bx)})=(z(x_1),z'(x_2))$. Since $(z,z')$ forms an edge of $\B_{T_{\mu,\nu}}$, the $(\alpha,\beta)$-th entry of the transition matrix $T$ used to describe the Pultr template $\mathfrak{T}$ is nonzero for each $i\in [m]$, where $\alpha$ and $\beta$ are as in~\eqref{eqn_1248_2411}. It then follows from the third property of $T$ that $z(x_1)\neq z'(x_2)$, which means that $(z(x_1),z'(x_2))\in R(\K_{2d})$, as needed.
\end{proof}


%
\begin{proof}[Proof of Theorem~\ref{thm_quantum_completeness_dinur}]
Let $\Phi$ be an instance of $d$-to-$d$ games, and let $\X_\Phi$ be the corresponding $\tau$-structure as defined above, so that the equation~\eqref{eqn_1349_1812} holds.
%
Recall from Section~\ref{subsec_CSP_homomorphisms} that 
$\Phi$ admitting a perfect $k$-compatible quantum assignment is equivalent to $\X_\Phi\leadsto^k\dGames$.
%
Observe that the Pultr template $\mathfrak{T}$ is faithful. 
%
Using Corollary~\ref{cor_left_pultr_functor}, we obtain $\Lambda_{\mathfrak{T}}\X_\Phi\leadsto^k\Lambda_{\mathfrak{T}}\dGames$. Composing this with the homomorphism from Proposition~\ref{prop_simple_lambda_dinur} via Proposition~\ref{prop_compose_classic_quantum_homos}, we conclude that $\eta\Phi=\Lambda_{\mathfrak{T}}\X_\Phi\leadsto^k\K_{2d}$, as required.
\end{proof}

\subsection{The line-digraph reduction}
\label{subsec_line_digraph}

The results of Sections~\ref{subsec_preprocessing} and~\ref{subsec_GS_reduction} yield a $2d$ vs. $\mathcal{O}(1)$ quantum chromatic gap, conditional to the pseudo-telepathy of $d$-to-$1$ games. The next task is to reduce the completeness parameter from $2d$ to $3$. To that end, we make use of a standard graph-theoretical reduction, which we now define (recall also Example~\ref{ex_some_pultr_functors}). 

\begin{defn}
Let $\X$ be a digraph having vertex set $X$ and edge set $R(\X)$.
%
The \emph{line digraph} of $\X$ is the digraph $\delta\X$ whose vertex set is $R(\X)$ and whose edge set is $$\{((x,y),(y,z))\suchThat (x,y),(y,z)\in R(\X)\}.$$
\end{defn}

The line-digraph reduction is known to change the chromatic number of digraphs in a controlled way, as described next.
%
For $n\in\N$, let $\alpha(n)=2^n$ and $\beta(n)={n\choose \floor{n/2}}$. Observe that $\alpha(n)\geq \beta(n)$ for each $n$.   
\begin{thm}[\cite{HarnerE72,poljak1981arc}]
\label{prop_chromatic_number_line_digraph}
Let $\X$ be a digraph and let $n\in\N$.
If $\delta\X\to\K_n$, then $\X\to\K_{\alpha(n)}$;
if $\X\to\K_{\beta(n)}$, then $\delta\X\to\K_n$.
\end{thm}



\begin{thm}
\label{thm_quantum_completeness_arc_digraph}
    Let $\X$ and $\Y$ be digraphs and let $k\in\N$. If $\X\leadsto^{2k+2}\Y$, then $\delta\X\leadsto^{k}\delta\Y$.
\end{thm}
%
\begin{proof}
Recall from Example~\ref{ex_line_digraph_pultr} that $\rho$ is the central Pultr functor corresponding to a connected Pultr template $\mathfrak{T}$. In particular, notice that $\diam(\mathfrak{T})=2$. Hence, the result immediately follows from Corollary~\ref{cor_gamma_quantum_functor}.
\end{proof}

\subsection{Putting all together}
\label{subsect_putting_all_together}
%\LC{metti k giu in qsat}
Combining the results of Subsections~\ref{subsec_preprocessing},~\ref{subsec_GS_reduction}, and~\ref{subsec_line_digraph}, we can now conclude the proof of the first main result of this paper.

\begin{thm*}
[Theorem~\ref{thm_main} restated]
Suppose that Conjecture~\ref{conj_d_to_1_khot_quantum} holds for some $d\geq 2$. Then, for any $c\in\N$, there exists a graph with quantum chromatic number $3$ and classical chromatic number larger than $c$.
\end{thm*}
%
\begin{proof}
Take an integer $d\geq 2$ such that Conjecture~\ref{conj_d_to_1_khot_quantum} holds for $d$.
Recall the functions $\alpha$ and $\beta$ defined in Section~\ref{subsec_line_digraph}.
For $i\in \N$, we denote by $\alpha^{(i)}$ (resp. $\beta^{(i)}$) the function obtained by iterating $\alpha$ (resp. $\beta$) $i$-many times.
%
Observe that $\beta(n)>n$ whenever $n\geq 4$. Hence, there exists some $j\in\N$ such that $\beta^{(j)}(4)\geq 2d$. Let $i=j+2$, and define $k'=3\cdot 2^i-2$. 
%
Assume, without loss of generality, that $c\geq 2$.
%
Define $\epsilon=\frac{1}{\alpha^{(i)}(c)}$, and choose $\epsilon'>0$, $t\in\N$ witnessing the truth of Theorem~\ref{thm_soundess_third_reduction} applied to $\epsilon$. Using Proposition~\ref{prop_d_to_d_after_dinur}, find a $d$-to-$d$ instance $\Phi$ such that 
$\Phi$ admits a perfect $k'$-compatible quantum assignment
but $\isat_t(\Phi)<\epsilon'$.
%
Consider the digraph $\delta^{(i)}\eta\Phi$, where $\delta^{(i)}$ denotes the $i$-fold application of the line-digraph operator $\delta$ of Section~\ref{subsec_line_digraph} and $\eta$ is the reduction from Section~\ref{subsec_GS_reduction}. Let also $\GG$ be the undirected graph obtained by replacing each directed edge of $\delta^{(i)}\eta\Phi$ by an undirected edge. We claim that $\GG$ has quantum chromatic number $3$ and classical chromatic number larger than $c$, which would conclude the proof.

\emph{(Classical) soundness}.\quad Theorem~\ref{thm_soundess_third_reduction} implies that $\eta\Phi$ has no independent sets of relative size $\epsilon$. This means that the classical chromatic number of $\eta\Phi$ is larger than $\frac{1}{\epsilon}=\alpha^{(i)}(c)$; hence, $\eta\Phi\not\to\K_{\alpha^{(i)}(c)}$. By repeatedly applying (the contrapositive of the first part of) Theorem~\ref{prop_chromatic_number_line_digraph}, we deduce that $\delta^{(i)}\eta\Phi\not\to\K_c$. Since the classical chromatic number of a digraph is equal to that of the corresponding undirected graph, we obtain $\GG\not\to\K_c$.
%

\emph{(Quantum) completeness}.\quad Theorem~\ref{thm_quantum_completeness_dinur} guarantees that $\eta\Phi\leadsto^{k'}\K_{2d}$. Since $\K_{2d}\to\K_{\beta^{(j)}(4)}$, Proposition~\ref{prop_compose_classic_quantum_homos} ensures that $\eta\Phi\leadsto^{k'}\K_{\beta^{(j)}(4)}$. Consider now the function $f:\N\to\N$ given by $n\mapsto 2n+2$, and observe that its $i$-fold iteration applied to the input $1$ is $f^{(i)}(1)=3\cdot 2^i-2=k'$. Hence, a repeated application of Theorem~\ref{thm_quantum_completeness_arc_digraph} yields
\begin{align}
    \label{eqn_1933_1912}
    \delta^{(i)}\eta\Phi\leadsto^1\delta^{(i)}\K_{\beta^{(j)}(4)}.
\end{align}
%
Starting from the identity homomorphism $\K_{\beta^{(j)}(4)}\to\K_{\beta^{(j)}(4)}$, a repeated application of (the second part of) Theorem~\ref{prop_chromatic_number_line_digraph} yields $\delta^{(j)}\K_{\beta^{(j)}(4)}\to\K_4$. Then, the functoriality of $\delta$ ensures that
\begin{align}
    \label{eqn_1933_1912_b}\delta^{(i)}\K_{\beta^{(j)}(4)}
    =
    \delta^{(2)}\delta^{(j)}(\K_{\beta^{(j)}(4)})\to\delta^{(2)}\K_4\to\K_3,
\end{align}
where the last homomorphism comes from the fact that $\delta^{(2)}\K_4$ is classically $3$-colourable---as was shown in~\cite{zhu1998survey} (see also~\cite{poljak1991coloring}). Combinining~\eqref{eqn_1933_1912} and~\eqref{eqn_1933_1912_b} via Proposition~\ref{prop_compose_classic_quantum_homos}, we obtain $\delta^{(i)}\eta\Phi\leadsto^1\K_3$, which implies that $\delta^{(i)}\eta\Phi\leadsto^0\K_3$.
%
Like in the classical case, making the edges of a digraph undirected does not affect the quantum chromatic number. Hence, we deduce that $\GG\leadsto^0\K_3$. Finally, as noted in~\cite{MancinskaR16}, a graph has quantum chromatic number $2$ precisely when it is bipartite. Since $\GG\not\to\K_c$ and $c\geq 2$, $\GG$ is not bipartite.
%
It follows that the quantum chromatic number of $\GG$ is exactly $3$, which concludes the proof.
\end{proof}

\begin{rem}
\label{rem_higher_consistency_gap}
    We point out that the proof of Theorem~\ref{thm_main} can be easily modified to enforce local compatibility of the perfect quantum assignment witnessing that the graph is quantum $3$-colourable. More precisely, conditional to Conjecture~\ref{conj_d_to_1_khot_quantum}, for each $k\in\N$ there exist graphs $\GG$ having arbitrarily large classical chromatic number and such that $\GG\leadsto^k\K_3$. To prove this, one simply needs to set $k'=3\cdot 2^{i+k}-2$ instead of $k'=3\cdot 2^{i}-2$ in the proof of Theorem~\ref{thm_main}. This choice guarantees that~\eqref{eqn_1933_1912} can be replaced by the stronger
    \begin{align*} \delta^{(i)}\eta\Phi\leadsto^k\delta^{(i)}\K_{\beta^{(j)}(4)},
\end{align*}
which implies that $\GG\leadsto^k\K_3$.

This fact, together with an upper bound on the quantum chromatic gap in terms of the number of shared qubits in the quantum strategy recently proved in~\cite{simul_banakh}, has the interesting consequence that the Hilbert spaces necessary for the validity of Conjecture~\ref{conj_d_to_1_khot_quantum} cannot have bounded dimension.
%
More precisely, it was shown in~\cite[Theorem~29]{simul_banakh} that, for each graph $\GG$ and each $n\in\N$, if $\GG\leadsto^1\K_n$ on a Hilbert space of dimension $p$, then $\GG\to\K_{n\cdot \alpha_p}$ with $\alpha_p=(2+\mathcal{o}(1))^{p-1}$. 
%
Now, all reductions from $d$-to-$1$ games to $3$ vs. $\mathcal{O}(1)$ colouring described in Section~\ref{sec_reductions}  preserve the Hilbert space $\HH$ witnessing perfect quantum assignments, as discussed in Remarks~\ref{rem_pultr_preserves_H} and~\ref{rem_appendix_reductions_preserve_H}. It follows that, in Conjecture~\ref{conj_d_to_1_khot_quantum}, the dimension of the Hilbert spaces witnessing the presence of a perfect quantum assignment for the classically $\epsilon$-unsatisfiable instance $\Phi$ must approach infinity as  $\epsilon$ approaches $0$.
\end{rem}



\section{The quantum  chromatic gap via $3$XOR games}
\label{sec_quantum_chromatic_gap_3xor}
%
The Mermin--Peres ``magic square'' construction gives a well-known example of a pseudo-telepathic system of Boolean equations. The classical value of the system is strictly smaller than $1$; however, by sharing a pair of entangled Bell states and measuring it via PVMs arising from combinations of Pauli matrices, the corresponding non-local game can be won with probability $1$ by two cooperating non-communicating players~\cite{mermin1990simple,mermin1993hidden,peres1990incompatible}.
%
The Mermin--Peres system is an instance of $3$XOR, i.e., the CSP expressing systems of Boolean equations involving three variables each. Furthermore, the  Mermin--Peres system is \textit{$2$-regular}, in that every variable appears in at most (in fact, precisely) $2$ equations, and two distinct equations share at most one variable.
%
Systems of linear equations can be naturally interpreted as instances of ``many-to-$1$'' games: For every partial assignment to some equation, there exists precisely one consistent assignment to each of the variables appearing in the equation.
%
% 
Hence, a naive approach to proving Conjecture~\ref{conj_d_to_1_khot_quantum}---and, thus, establishing Theorem~\ref{thm_main} unconditionally---could be to consider a parallel-repetition version of the Mermin--Peres magic square game. In that way, the classical value of the game is decreased while preserving the existence of a perfect quantum assignment (which is obtained by simply taking the tensor product of PVMs corresponding to one iteration of the game). 
%

Unfortunately, it is not hard to see that this approach cannot work: Increasing the number of repetitions of the game generates label-cover instances that are $d$-to-$1$ for increasingly large $d$. On the other end, in order to prove Theorem~\ref{thm_main} by transferring pseudo-telepathy from the instances in Conjecture~\ref{conj_d_to_1_khot_quantum}, one would need to reduce the soundness parameter $\epsilon$ to zero while leaving $d$ \textit{fixed}.
%
Therefore, we consider a stronger version of repetition for $3$XOR games. It shall be convenient to present it in the form of a non-local game. Let $S$ be a system of linear equations over the Boolean field $\F_2$, and fix an integer $n\in\N$. Alice receives from the verifier a list $\bu=(u_1,\dots,u_n)$ of equations from $S$, and replies with an assignment $\vartheta:\widetilde\bu\to\F_2$, where $\tilde\bu$ is the set of all variables appearing in the equations from $\bu$. Similarly, Bob receives from the verifier a list $\bw=(w_1,\dots,w_n)$ of equations from $S$ and replies with an assignment $\vartheta':\widetilde\bw\to\F_2$. Alice and Bob win the game if $\vartheta$ respects the equations in $\bu$, $\vartheta'$ respects the equations in $\bw$, and the replies are consistent, in the sense that 
\begin{align}
\label{eqn_0801_1029}
\vartheta|_{\widetilde\bu\cap\widetilde{\bw}}=\vartheta'|_{\widetilde\bu\cap\widetilde{\bw}}. 
\end{align}
We denote this game by $\mathcal{G}(S,n)$.
Note that the last requirement would not be enforced in a standard parallel repetition of $3$XOR, where Alice's and Bob's replies need not be consistent across different iterations of the game. 
%

%The variables of the corresponding label-cover instance are $k$-tuples of equations from $S$, and the alphabet contains all possible $3k$-tuples of values from $\F_2$. The binary constraints are pairs $(\bu,\bw)$ of variables with $\widetilde u\cap\widetilde\bw\neq\emptyset$. An assignment $\bu\mapsto\vartheta$, $\bw\mapsto\vartheta'$ satisfies the constraint if~\eqref{eqn_0801_1029} holds.

Let $s(\bu)$ denote the set of assignments $\vartheta:\widetilde\bu\to\F_2$ such that $\vartheta$ satisfies all equations in $\bu$.
Using Proposition~\ref{thm_quantum_assignments_as_projectors}, we have that a perfect quantum strategy $\mathfrak{Q}$ for the $\mathcal{G}(S,n)$ game is given by projectors $Q_{\bu,\vartheta}$ onto a Hilbert space $\HH$ for each $n$-tuple $\bu$ of equations and each $\vartheta\in s(\bu)$, such that
\begin{itemize}
    \item $\sum_{\vartheta\in s(\bu)}Q_{\bu,\vartheta}=\id_\HH$ for each $\bu$, and
    \item $Q_{\bu,\vartheta}\cdot Q_{\bw,\vartheta'}=O$ whenever $\vartheta|_{\widetilde\bu\cap\widetilde{\bw}}\neq\vartheta'|_{\widetilde\bu\cap\widetilde{\bw}}$.
\end{itemize}
We shall further require that the strategy is $1$-compatible; i.e., 
\begin{itemize}
    \item $[Q_{\bu,\vartheta},Q_{\bw,\vartheta'}]=O$ whenever $\tilde\bu\cap\tilde\bw\neq \emptyset$. 
\end{itemize}

As usual, we let $\sat(S)$ denote the maximum fraction of equations simultaneously satisfiable by a classical assignment. 
%
Moreover, as a generalisation of the regularity property of the Mermin--Peres construction, a system of linear equations is said to be \textit{regular} for some $p\in\N$ (which we consider as a fixed constant) if $(i)$ every variable appears in at most $p$ equations, and $(ii)$ two distinct equations share at most one variable. The main result of this section is the following.

\begin{thm*}
[Theorem~\ref{thm_equations_to_colouring} restated]
    Suppose that there exists some $0<s^*<1$ such that, for each $n\in\N$, there exists a regular instance $S$ of $3$XOR for which $\sat(S)<s^*$ but $\mathcal{G}(S,n)$ admits a perfect $1$-compatible quantum assignment. Then, for each $c\in\N$, there exists a graph with quantum chromatic number at most $4$ and classical chromatic number larger than $c$.
\end{thm*}






\subsection{Description of the reduction}
\label{subsec_description_rho_one}
%
We now outline the reduction used in~\cite{Khot17:stoc-independent,Khot18:focs-pseudorandom,Dinur18:stoc-non-optimality,Dinur18:stoc-towards} to establish the $2$-to-$2$ Games Theorem with imperfect completeness. We shall mostly follow the presentation in~\cite[ch.~3]{minzer2022monotonicity}.
%

Let $S$ be a regular instance of $3$XOR. 
%
The final reduction $\rho$
is the composition of two reductions $\rho_1$ and $\rho_2$:
%
The first takes $S$ as input and returns a label-cover instance $\rho_1 S $ all of whose constraints are either $1$-to-$1$ or $2$-to-$2$; the second takes  $\rho_1 S$ as input and returns a $2$-to-$2$ instance $\rho S=\rho_2 \rho_1 S$.
%

Fix positive integers $n\in\N$ and $2\leq\ell\in\N$, which we consider fixed parameters of the reduction.
For any equation $u$ in $S$, we let its \textit{right-hand side} be the number $b\in\F_2$ such that $u$ is the equation $x+y+z=b$. 
%
Consider the set $\mathcal{U}$ containing all $n$-tuples $\bu=(u_1,\dots,u_n)$ of equations in $S$ that are \textit{legitimate}, i.e., $(i)$ all equations $u_1,\dots,u_n$ are distinct and do not share any variable, and $(ii)$ if two distinct variables $x_1,x_2$ appear in two distinct equations of $\bu$, there is no equation in $S$ in which both $x_1$ and $x_2$ appear.
%
Let $X$ be the set of variables appearing in the system $S$.
We shall consider the set $\F_2^X$, which we view as a $|X|$-dimensional vector space over the Boolean field $\F_2$. Given a set $X'\subseteq X$, the vector space $\F_2^{X'}$ is canonically identified with a subspace of $\F_2^X$ (where the identification simply consists in padding each vector $v\in\F_2^{X'}$ with $(|X|-|X'|)$-many zero entries).
%
For $x\in X$, we let $v_x$ be the one-hot encoding of $x$; i.e, the vector of $\F_2^X$ whose $x$-th entry is $1$ and all other entries are $0$.
%
%Let $X_U$ denote the set of variables appearing in the constraints of $U$. 
Also, for each $i\in [n]$, we consider the vector $v_{u_i}=v_x+v_y+v_z\in\F_2^{X}$, where $x$, $y$, and $z$ are the variables in $u_i$.
%
Denote the space $\Span(v_{u_1},\dots,v_{u_n})$ by $H_\bu$. For a space $X'\subseteq X$, we say that a linear function $\psi:\F_2^{X'}\to\F_2$ \emph{respects} $\bu$ if $\psi(v_{u_i})=b_i$ for each $i\in [n]$ for which $v_{u_i}\in\F_2^{X'}$, where $b_i$ is the right-hand side of $u_i$. Fix a tuple $\bu\in\mathcal{U}$, and let $\tilde \bu$ denote the set of variables appearing in the equations of $\bu$, as usual. 
%
Consider the set $\mathcal{L}_\bu$ containing all vector subspaces $L\subseteq\F_2^{\tilde \bu}$ such that $\dim(L)=\ell$ and $L\cap H_\bu=\{\bzero\}$.
%
%
The next property of $\mathcal{L}_\bu$ shall be crucial for establishing quantum completeness of $\rho_1$.
\begin{lem}[\cite{Khot17:stoc-independent}]
\label{lem_extension_side_conditions}
    Choose $\bu,\bw\in\mathcal{U}$ and $L\in\mathcal{L}_\bu$. Then any linear function on $L\oplus H_\bu$ that respects $\bu$ admits a unique linear extension to $L\oplus H_\bu\oplus H_{\bw}$ that respects $\bw$.
\end{lem}

We let $\rho_1 S$ be the unweighted label-cover instance $(V,E,A,\phi)$ defined as follows.
%
The variable set $V$ is the set
$\{
    L\oplus H_\bu:\bu\in\mathcal{U},L\in\mathcal{L}_\bu
    \}$.
%
The alphabet $A$ is the set $[2^\ell]$.
%
Since each of the $2^\ell$-many linear functions $L\to\F_2$ can be uniquely extended to a linear function on $L\oplus H_\bu$ that respects $\bu$, the elements of $[2^\ell]$ are naturally identified with linear functions $L\oplus H_\bu\to\F_2$ respecting $\bu$.
%
Given a pair $e=(L\oplus H_\bu,L'\oplus H_{\bw})$ of variables, we let $e\in E$ if and only if 
$
    \dim(L\oplus H_\bu\oplus H_{\bw})
    =
    \dim(L'\oplus H_\bu\oplus H_{\bw})
    =
    \dim(L\oplus L'\oplus H_\bu\oplus H_{\bw})
$
(in which case the constraint is $1$-to-$1$), or 
$
    \dim(L\oplus H_\bu\oplus H_{\bw})
    =
    \dim(L'\oplus H_\bu\oplus H_{\bw})
    =
    \dim(L\oplus L'\oplus H_\bu\oplus H_{\bw})-1
$
(in which case, the constraint is $2$-to-$2$). In both cases, the set $\phi_e$ of admitted labellings is defined as follows. Given a linear function $\psi:L\oplus H_\bu\to\F_2$ (i.e., an element of the alphabet),
let $\psi^{(\bw)}$ be its unique linear extension to $L\oplus H_\bu\oplus H_{\bw}$ respecting $\bw$, as per Lemma~\ref{lem_extension_side_conditions}; similarly, given $\psi':L'\oplus H_{\bw}\to\F_2$, let $\psi'^{(\bu)}$ be its unique linear extension to $L'\oplus H_\bu\oplus H_{\bw}$ respecting $\bu$. The pair $(\psi,\psi')$ belongs to $\phi_e$ if and only if $\psi^{(\bw)}$ and $\psi'^{(\bu)}$ agree on the shared space $(L\oplus H_\bu\oplus H_{\bw})\cap (L'\oplus H_\bu\oplus H_{\bw})$. It is not hard to show that the resulting constraints are $1$-to-$1$ or $2$-to-$2$ according to which of the two conditions above holds.

It was shown in~\cite{Khot17:stoc-independent} that the label-cover instance $\rho_1 S$ described above satisfies a specific \textit{transitivity property}. This is used in order to perform the second step $\rho_2$ of the reduction, which discards all $1$-to-$1$ constraints of $\rho_1 S$ and assigns a suitable weight $\pi$ to the $2$-to-$2$ constraints, so that the composition $\rho S=\rho_2 \rho_1 S$ is a (weighted) $2$-to-$2$ instance. 
%
The details of $\rho_2$ are not relevant to the current analysis, so we do not include them here. It is sufficient for our purposes to note that $(i)$ the domains of $\rho_1 S$ and $\rho_2\rho_1 S$ coincide, and $(ii)$ while some of the constraints are discarded in the second step of the reduction, no new constraint is introduced. Both these facts follow from the description in~\cite[ch.~3]{minzer2022monotonicity}.
%

















\subsection{Quantum completeness of $\rho$}
%
The reduction $\rho$ is easily seen to preserve perfect \textit{classical} completeness, in the sense that $\rho S$ admits a perfect classical assignment whenever $S$ does. In fact, $\rho$ also preserves imperfect classical completeness, in that almost satisfiable $3$XOR instances are mapped to almost satisfiable $2$-to-$2$ instances. This is crucial for the purpose of~\cite{Khot17:stoc-independent,Khot18:focs-pseudorandom,Dinur18:stoc-non-optimality,Dinur18:stoc-towards}, as H\aa stad's NP-hardness of approximating $3$XOR games~\cite{haastad2001some} only holds in the imperfect completeness regime (otherwise, the problem trivially becomes tractable). Our goal is now to show that $\rho$ preserves \textit{quantum} completeness, and can thus be used to transfer pseudo-telepathy from $3$XOR to $2$-to-$2$ games. Since $3$XOR games are pseudo-telepathic despite being tractable in the exact version, we prove perfect quantum completeness.




\begin{thm}
\label{thm_quantum_completeness_rho_minzer}
Let $S$ be a regular $3$XOR instance. If $\mathcal{G}(S,n)$ admits a perfect $1$-compatible quantum assignment, the same holds for the $2$-to-$2$ instance $\rho S$.
\end{thm}
%
\begin{proof}
    Let $\mathfrak{Q}=\{Q_{\bu,\vartheta}\}$ be a perfect $1$-compatible quantum assignment for $S$ over a Hilbert space $\HH$. Let $X$ be the set of variables appearing in $S$. 
    Given a function $\xi:X'\to\F_2$ for some $X'\subseteq X$, we denote by $\widehat{\xi}:\F_2^{X'}\to\F_2$ the corresponding linear function defined by $\widehat{\xi}(v_x)=\xi(x)$ for each $x\in X'$ and extended by linearity. (Note that the set $\{v_x\}_{x\in X'}$ forms a basis for ${\F_2}^{X'}$ since $v_x$ is the one-hot encoding of $x$.)
    %
    Recall that $\mathcal{U}$ denotes the set of all legitimate $n$-tuples of equations of $S$.

    We first prove quantum completeness for the first part $\rho_1$ of the reduction $\rho$.
    Take a variable $L\oplus H_\bu$ of $\rho_1 S$;
    i.e., $\bu\in\mathcal{U}$ and $L\in\mathcal{L}_\bu$. Take also a label $\psi\in A$, which corresponds to a linear map $\psi:L\oplus H_\bu\to\F_2$ that respects $\bu$. Consider the linear application
    \begin{align}
    \label{eqn_0801_1740}
        W_{L\oplus H_\bu,\psi}
        =
        \sum_{\substack{\vartheta\in s(\bu)\\\widehat\vartheta|_{L\oplus H_\bu}=\psi}}Q_{\bu,\vartheta}.
    \end{align}

We claim that the set $\mathfrak{W}=\{W_{L\oplus H_\bu,\psi}\}$ is a $1$-compatible perfect quantum assignment for $\rho_1 S$ over $\HH$.

First of all, since each family $\{Q_{\bu,\vartheta}\suchThat\vartheta\in s(\bu)\}$ is a PVM, the linear applications in~\eqref{eqn_0801_1740} are projectors. Take now two different labels $\psi\neq\psi':L\oplus H_\bu\to\F_2$. If $\vartheta,\vartheta'\in s(\bu)$ are such that $\widehat\vartheta|_{L\oplus H_\bu}=\psi$ and $\widehat\vartheta'|_{L\oplus H_\bu}=\psi'$, it must hold that $\vartheta\neq\vartheta'$, which means that $Q_{\bu,\vartheta}\cdot Q_{\bu,\vartheta'}=O$. It follows that $W_{L\oplus H_\bu,\psi}\cdot W_{L\oplus H_\bu,\psi'}=O$; i.e., the projectors in $\mathfrak{W}$ corresponding to the same variable are mutually orthogonal. Furthermore, we have
\begin{align*}
    \sum_{\psi\in A}W_{L\oplus H_\bu,\psi}
        =
    \sum_{\psi\in A}\sum_{\substack{\vartheta\in s(\bu)\\\widehat\vartheta|_{L\oplus H_\bu}=\psi}}Q_{\bu,\vartheta}
    =
    \sum_{\substack{\vartheta:\tilde \bu\to\F_2\\\widehat\vartheta\mbox{ respects }\bu}}Q_{\bu,\vartheta}
    =
    \sum_{\vartheta\in s(\bu)}Q_{\bu,\vartheta}
    =\id_\HH.
\end{align*}
This shows that each set $\{W_{L\oplus H_\bu,\psi}\suchThat \psi\in A\}$ is a PVM and, thus, $\mathfrak{W}$ is a quantum assignment. 

Consider now a pair $e=(L\oplus H_\bu,L'\oplus H_\bw)\in E$
(where $E$ is the edge set of $\rho_1 S$), and take a pair $(\psi,\psi')$ of labels, with $\psi:L\oplus H_\bu\to\F_2$ and $\psi':L'\oplus H_\bw\to\F_2$. Recall the definition of the linear maps $\psi^{(\bw)}:L\oplus H_\bu\oplus H_\bw\to\F_2$ and $\psi'^{(\bu)}:L'\oplus H_\bu\oplus H_\bw\to\F_2$ given in Section~\ref{subsec_description_rho_one}. Suppose that $(\psi,\psi')\not\in\phi_e$, which means that 
\begin{align}
\label{eqn_1851_0801}
    \psi^{(\bw)}|_{(L\oplus H_\bu\oplus H_\bw)\cap(L'\oplus H_\bu\oplus H_\bw)}\neq\psi'^{(\bu)}|_{(L\oplus H_\bu\oplus H_\bw)\cap(L'\oplus H_\bu\oplus H_\bw)}.
\end{align}


Consider two linear functions $\vartheta\in s(\bu),\vartheta'\in s(\bw)$ such that $\widehat{\vartheta}|_{L\oplus H_\bu}=\psi$ and $\widehat{\vartheta'}|_{L'\oplus H_\bw}=\psi'$. Suppose, for the sake of contradiction, that
\begin{align*}
    Q_{\bu,\vartheta}\cdot Q_{\bw,\vartheta'}\neq O.
\end{align*}
Since the quantum assignment $\mathfrak{Q}$ is perfect, it follows that $\vartheta|_{\widetilde\bu\cap\widetilde{\bw}}=\vartheta'|_{\widetilde\bu\cap\widetilde{\bw}}$. Hence, there exists a well defined linear map $\xi:\tilde\bu\cup\tilde\bw\to\F_2$ extending both $\vartheta$ and $\vartheta'$. Note that $\widehat\xi$ respects both $\bu$ and $\bw$. Hence, by Lemma~\ref{lem_extension_side_conditions} on the unicity of extension, it must hold that $\widehat\xi|_{L\oplus H_\bu\oplus H_\bw}=\psi^{(\bw)}$ and $\widehat\xi|_{L'\oplus H_\bu\oplus H_\bw}=\psi'^{(\bu)}$. But this means that the functions $\psi^{(\bw)}$ and $\psi'^{(\bu)}$ agree on the intersection of their domains, which contradicts~\eqref{eqn_1851_0801}. Hence, the product $Q_{\bu,\vartheta}\cdot Q_{\bw,\vartheta'}$ is zero.
We deduce that
\begin{align*}
    W_{L\oplus H_\bu,\psi}\cdot W_{L'\oplus H_\bw,\psi'}&=\Big(\sum_{\substack{\vartheta\in s(\bu)\\\widehat\vartheta|_{L\oplus H_\bu}=\psi}}Q_{\bu,\vartheta}\Big)\Big(\sum_{\substack{\vartheta'\in s(\bw)\\\widehat\vartheta'|_{L'\oplus H_\bw}=\psi'}}Q_{\bw,\vartheta'}\Big)\\
    &=
    \sum_{\substack{\vartheta\in s(\bu)\\\widehat\vartheta|_{L\oplus H_\bu}=\psi}}\;\sum_{\substack{\vartheta'\in s(\bw)\\\widehat\vartheta'|_{L'\oplus H_\bw}=\psi'}}Q_{\bu,\vartheta}\cdot Q_{\bw,\vartheta'}=O,
\end{align*}
as needed. We conclude that the quantum assignment $\mathfrak{W}$ is perfect. 

We are left to establish $1$-compatibility. Like above, take an edge $e=(L\oplus H_\bu,L'\oplus H_\bw)\in E$ and two labels $\psi:L\oplus H_\bu\to\F_2$ and $\psi':L'\oplus H_\bw\to\F_2$. 
%
Suppose, for the sake of contradiction, that $\tilde\bu\cap\tilde\bw=\emptyset$. It follows that $\F_2^{\tilde\bu}\cap\F_2^{\tilde\bw}=\{\bzero\}$. Recall that $L\oplus H_\bu\subseteq\F_2^{\tilde\bu}$ and $L'\oplus H_\bw\subseteq\F_2^{\tilde\bw}$. Moreover, from $L'\in\mathcal{L}_\bw$, we deduce that $L'\cap H_\bw=\{\bzero\}$. As a consequence, 
the two spaces $L'$ and $L\oplus H_\bu\oplus H_\bw$ are linearly independent, which means that 
\begin{align*}
\dim(L\oplus L'\oplus H_\bu\oplus H_\bw)=\ell+\dim(L\oplus H_\bu\oplus H_\bw).
\end{align*}
Since $\ell\geq 2$, this would imply that $e\not\in E$, a contradiction. Hence, the two sets $\tilde\bu$ and $\tilde \bw$ are not disjoint. Since the assignment $\mathfrak{Q}$ is $1$-compatible, this means that $[Q_{\bu,\vartheta},Q_{\bw,\vartheta'}]=O$ for each $\vartheta\in s(\bu)$, $\vartheta'\in s(\bw)$. Using the linearity of the commutator, we deduce that $[W_{L\oplus H_\bu,\psi},W_{L'\oplus H_\bw,\psi'}]=O$, as needed.

We now need to extend quantum completeness to the second part $\rho_2$ of the reduction $\rho$. Recall from the description in Section~\ref{subsec_description_rho_one} that $\rho_2$ simply discards some of the constraints of $\rho_1(S)$. Hence, it is immediate to see that the same assignment $\mathfrak{W}$ is also a perfect $1$-compatible quantum assignment for $\rho S=\rho_2\rho_1 S$, and the proof is concluded.
\end{proof}

\subsection{Classical soundness of $\rho$}
\label{subsec_classical_soundness_rho}
The core of the sequence of works~\cite{Khot17:stoc-independent,Khot18:focs-pseudorandom,Dinur18:stoc-non-optimality,Dinur18:stoc-towards} is a proof of the classical soundness of $\rho$, established via an advanced analysis of the expansion properties of the Grassmann graphs encoding the geometry of the linear spaces $L\oplus H_\bu$ involved in the reduction.
%
\begin{thm}[\cite{Khot18:focs-pseudorandom}]
\label{thm_soundess_first_reduction}
For each $0<s^*<1$ and each $\delta>0$, there exist parameters $n,\ell\in\N$ such that the corresponding reduction $\rho$ satisfies the following: 
%
If the $3$XOR instance $S$ is such that $\sat(S)< s^*$, the $2$-to-$2$ instance $\rho S$ 
is such that $\sat(\rho S)< \delta$.
%
%Fix a soundness parameter $s<1$. There exists a function $f=\mathcal{o}(1)$ such that, for each $\epsilon>0$, the reduction $\rho$ satisfies the following condition for a suitable choice of the parameters $\ell,p\in\N$: Given an instance $\X$ of $\CSP(\ThreeLin)$ such that $\val(\X)\leq s+\epsilon$, the instance $\rho(\X)$ fo $\CSP(\TwoGames)$ satisfies $\val(\rho(\X))\leq f(\epsilon)$. 
\end{thm}

In order to link $\rho$ with the reductions of Section~\ref{sec_reductions} and, thus, use it for transferring pseudo-telepathy all the way to the colouring game, we need a different classical soundness than the one in Theorem~\ref{thm_soundess_first_reduction}, involving the $\isat$ value as opposed to the $\sat$ value (cf.~Section~\ref{subsec_preprocessing}). There exist multiple ways to circumvent this technical issue. One way is to slightly modify the reduction $\rho$ by making the constraints of $\rho S$ be $2$-to-$1$ instead of $2$-to-$2$, as is done in~\cite{Dinur18:stoc-towards} (see also~\cite[Remark~3.4.11]{minzer2022monotonicity}). This involves considering two different types of vertices for $\rho_1 S$ corresponding to $\ell$-dimensional and $(\ell-1)$-dimensional subspaces of $H_\bu$, respectively, and suitably modifying the constraints and the weights in $\rho_2$. As a result, we would obtain a weighted $2$-to-$1$ instance admitting a perfect quantum assignment and arbitrarily small classical $\sat$ value, which is ready to be plugged in the chain of reductions from Sections~\ref{subsec_preprocessing} and~\ref{subsec_GS_reduction}. 

A second fix, which does not involve modifying the reduction $\rho$, is to apply the general framework of Crescenzi, Silvestri, and Trevisan~\cite{crescenzi2001weighted} based on the construction of mixing sets, which allows reducing weighted to unweighted instances of a large class of combinatorial problems including  CSPs without unary constraints---and suitably adapting the argument of~\cite[Claim~24]{crescenzi2001weighted} to capture soundness expressed in terms of $\isat$.

However, we can avoid both complications by making use of a recent result from~\cite{DawarM25}, showing through a probabilistic argument that the two soundness requirements for $\rho S$ are in fact equivalent. (The $\isat$ value is called ``irregular value'' in~\cite{DawarM25}.)

%\LC{in the arxiv version it is for arbitrary 2-to-2 games}DONE
\begin{lem}[\cite{DawarM25}]
\label{lem_classical_soundness_minzer_isat}
    %Let $S$ be a regular instance of $3$XOR and let $\rho$ be the reduction from Section~\ref{subsec_description_rho_one}. If $\isat_t(\rho S)\geq \epsilon$ for some $t\in\N$ and $\epsilon>0$, then $\sat(\rho S)\geq \delta$ for some $\delta=\Omega(\frac{\epsilon^2}{t^2})$.
    Let $\Phi$ be a (weighted) $2$-to-$2$ instance with $\isat_t(\Phi)=\epsilon$ for some $t\in\N$ and $\epsilon>0$. Then $\sat(\Phi)=\Omega(\frac{\epsilon^2}{t^2})$.
\end{lem}


\subsection{Proving Theorem~\ref{thm_equations_to_colouring}}
We now have the right forms of classical soundness and quantum completeness for $\rho$ that are necessary to link the reduction with that of Section~\ref{subsec_GS_reduction}, thus transferring pseudo-telepathy from the strong version of $3$XOR games repetition to the colouring game. 


%
\begin{proof}[Proof of Theorem~\ref{thm_equations_to_colouring}]
    We follow the same structure as the proof of Theorem~\ref{thm_main}.
%
    Take a number $0<s^*<1$ as in the statement of the theorem, and choose an integer $c\in\N$. We aim to find a graph having quantum chromatic number at most $4$ and classical chromatic number at least $c+1$. Let $\epsilon=\frac{1}{c}$, and choose $\epsilon'>0$, $t\in\N$ such that Theorem~\ref{thm_soundess_third_reduction} holds. Take $\delta=\Omega(\frac{\epsilon'^2}{t^2})$ witnessing Lemma~\ref{lem_classical_soundness_minzer_isat}. Choose integers $n,\ell\in\N$ such that Theorem~\ref{thm_soundess_first_reduction} applied to $s^*$ and $\delta$ holds. Finally, take a regular $3$XOR instance $S$ such that $\sat(S)<s^*$ but $\mathcal{G}(S,n)$ admits a perfect $1$-compatible quantum assignment, as per the statement of Theorem~\ref{thm_equations_to_colouring}.

    Let $\rho$ be the reduction of Section~\ref{subsec_description_rho_one} with parameters $n$ and $\ell$, and let $\eta$ be the reduction from Section~\ref{subsec_GS_reduction}.
    By Theorem~\ref{thm_quantum_completeness_rho_minzer}, the $2$-to-$2$ instance $\rho S$ admits a perfect $1$-compatible quantum assignment. Therefore, we deduce from Theorem~\ref{thm_quantum_completeness_dinur} that $\eta\rho S\leadsto^1\K_4$ (and, thus, $\eta\rho S\leadsto^0\K_4$).
    %
    However, Theorem~\ref{thm_soundess_first_reduction} implies that $\sat(\rho S)<\delta$; by Lemma~\ref{lem_classical_soundness_minzer_isat}, it follows that $\isat_t(\rho S)<\epsilon'$. Hence, Theorem~\ref{thm_soundess_third_reduction} implies that $\eta\rho S$ has no independent sets of relative size $\epsilon$---i.e., the classical chromatic number of $\eta\rho S$ is larger than $\frac{1}{\epsilon}=c$.

    To conclude, we simply need to symmetrise the digraph $\eta\rho S$ by turning each directed edge into an undirected edge. As noted in the proof of Theorem~\ref{thm_main}, this leaves the quantum and classical chromatic numbers unaffected. Hence, the resulting undirected graph has the required properties.
\end{proof}

\begin{rem}
\label{rem_proving_conj}
   We observe that the reduction discussed in this section not only is quantum complete, but it also preserves the Hilbert space witnessing the existence of perfect quantum assignments---just like the reduction we used to prove Theorem~\ref{thm_main}, see~Remark~\ref{rem_higher_consistency_gap}. Furthermore, it is clear from the proof of Theorem~\ref{thm_equations_to_colouring} that the resulting graph of arbitrarily large classical chromatic number is
   quantum $4$-colourable via 
   a $1$-compatible assignment. Hence, the same argument as in~Remark~\ref{rem_higher_consistency_gap}, based on~\cite[Theorem~29]{simul_banakh}, implies that the dimension of the Hilbert spaces in the perfect quantum strategies for the $3$XOR games $\mathcal{G}(S,n)$ in the hypothesis of Theorem~\ref{thm_equations_to_colouring} must tend to infinity as the number $n$ of repetitions of the game grows. 
%\end{rem}

