\section{The Dinur--Mossel--Regev reduction is quantum complete}
\label{app_dinur_reductions}

In this appendix, we prove the following result.

\begin{prop*}
[Proposition~\ref{prop_d_to_d_after_dinur} restated]
Suppose Conjecture~\ref{conj_d_to_1_khot_quantum} holds for some $d\geq 2$. 
Then for each $\epsilon>0$ and each $k,t\in\N$ there exists a $d$-to-$d$ instance $\Phi$ (on some alphabet size $n$) such that $\Phi$ admits a perfect $k$-compatible quantum assignment but
$\isat_t(\Phi)<\epsilon$.
\end{prop*}


We first need to introduce some new notation. 
%
Given a (weighted) label-cover instance $\Phi=(X,E,A,\pi,\phi)$ and a vertex $x\in X$, we define the $x$'th marginal of the probability distribution $\pi$ as 
\begin{align*}
\pi_x=\sum_{\substack{\bx\in E\\x_1=x}}\pi(\bx). 
\end{align*}
%
Moreover, given a classical assignment $f$ for $\Phi$, we let $\sat_{f,x}(\Phi)$ denote the value of $f$ restricted to constraints incident to $x$; formally,
%
\begin{align*}
    \sat_{f,x}(\Phi)=
    %\sum_{\substack{w\in V\\(v,w)\in E}}\pi(v,w)\,\phi(v,w,f(v),f(vw)).
    \sum_{\substack{\bx\in E\\x_1=x}}\pi(\bx)\,\phi_{\bx}(f(\bx)).
\end{align*}





We now show that a chain of simple transformations from $d$-to-$1$ games to $d$-to-$d$ games
given
in~\cite{Dinur09:sicomp} preserves the presence of perfect locally compatible quantum assignments. (See also~\cite{khot2008vertex}, where a similar chain of transformations is used to prove that a strong form of the Unique Games Conjecture follows from the standard form of~\cite{Khot02stoc}.)


\begin{lem}
\label{lem_dinur_uno}
    Fix a constant $h\in\N$. There is an (efficient) procedure that, given as input a bipartite label-cover instance $\Phi$ on variable set $X_1\sqcup X_2$, outputs a bipartite label-cover instance $\Phi'$ on variable set $X_1'\sqcup X_2$ satisfying the following:
    \begin{enumerate}
        \item If $\Phi$ admits a perfect $k$-compatible quantum assignment then $\Phi'$ admits a perfect $k$-compatible quantum assignment;
        \item for any $\delta,\epsilon>0$, if there exists a classical assignment $f'$ for $\Phi'$ for which a $\delta$-fraction of the variables $x'\in X_1'$ satisfy $\sat_{f',x'}(\Phi')\geq \frac{\epsilon}{|X_1'|}$, then $\sat(\Phi)\geq (1-\frac{1}{h})\delta\epsilon$.
        \item $\pi'_{x'}$ is constant over $x'\in X_1'$.
    \end{enumerate}
\end{lem}
%
\begin{proof}
    Let $\Phi=(X_1\sqcup X_2,E,A,\pi,\phi)$ be the given bipartite label-cover instance. Following~\cite{Dinur09:sicomp}, we consider the bipartite label-cover instance $\Phi'=(X_1'\sqcup X_2,E',A,\pi',\phi')$ defined as follows. 
    For each $x\in X_1$, set $\alpha_x=\floor{h\cdot|X_1|\cdot\pi_x}$.
    The set $X_1'$ contains $\alpha_x$ copies of each $x\in X_1$, denoted by $x^{(1)},\dots,x^{(\alpha_x)}$. For each $x\in X_1$, $y\in X_2$, and $i\in [\alpha_x]$, we add the edge $(x^{(i)},y)$ in $E'$ if and only if $(x,y)\in E$. In such case, we let $\pi'(x^{(i)},y)=\frac{\pi(x,y)}{|X_1'|\pi_x}$ and $\phi'_{(x^{(i)},y)}=\phi_{(x,y)}$. Observe that

\begin{align*}
    \pi'_{x^{(i)}}=\sum_{\substack{\bx\in E\\x_1=x}}\frac{\pi(\bx)}{|X_1'|\pi_x}
    =
    \frac{1}{|X_1'|},
\end{align*}
%
so condition $\textit{3.}$ is satisfied. Moreover, condition $\textit{2.}$ was proved in~\cite[Lemma~A.4]{Dinur09:sicomp}.

To prove that condition $\textit{1.}$ holds as well,
suppose that $\Phi$ admits a perfect $k$-compatible quantum assignment $\mathfrak{Q}=\{Q_{x,a}:x\in X_1\sqcup X_2,a\in A\}$. Consider the set $\mathfrak{W}=\{W_{ x',a}:x'\in X_1'\sqcup X_2,a\in A\}$ defined as follows. If $x'\in X_1'$ and, thus, $x'=x^{(i)}$ for some $x\in X_1$ and $i\in [\alpha_x]$, we let $W_{x',a}=Q_{x,a}$; if $x'\in X_2$, we let $W_{x',a}=Q_{x,a}$. It is straightforward to check that $\mathfrak{W}$ is a perfect quantum assignment for $\Phi'$.
To show that $\mathfrak{W}$ is $k$-compatible, assign to each vertex $y\in X_1'$ the vertex $\bar y\in X_1$ such that $y=\bar y^{(i)}$ for some $i\in[\alpha_{\bar y}]$, and let $\bar{y}=y$ for each $y\in X_2$. It is clear that $\dist_{\Phi'}(y_1,y_2)=\dist_\Phi(\bar y_1,\bar y_2)$ for each pair of vertices $y_1,y_2\in X_1'\sqcup X_2$ such that $\bar y_1\neq \bar y_2$. Hence, using the $k$-compatibility of $\mathfrak{Q}$, we find that for each  $a_1,a_2\in A$ and each $y_1,y_2\in X_1'\sqcup X_2$ with
$\dist_{\Phi'}(y_1,y_2)\leq k$ it holds that
\begin{align*}
[W_{y_1,a_1},W_{y_2,a_2}]=[Q_{\bar y_1,a_1},Q_{\bar y_2,a_2}]=O
\end{align*}
whenever
$\bar y_1\neq \bar y_2$. Furthermore, if $\bar y_1= \bar y_2$, we obtain
\begin{align*}
[W_{y_1,a_1},W_{y_2,a_2}]=[Q_{\bar y_1,a_1},Q_{\bar y_2,a_2}]= O
\end{align*}
as the projectors $Q_{\bar y_1,a_1}$ and $Q_{\bar y_2,a_2}$ are orthogonal in this case.
It follows that $\mathfrak{W}$ is $k$-compatible, as required. 
\end{proof}

We say that a bipartite label-cover instance on bipartition $X_1\sqcup X_2$ is \textit{left regular} if each vertex in $X_1$ has the same number of incident edges.



\begin{lem}
\label{lem_dinur_due}
    Fix two constants $\ell,m\in\N$. There is an (efficient) procedure that, given as input a $d$-to-$1$ instance $\Phi$ on variable set $X_1\sqcup 
    X_2$ such that $\pi_x$ is constant over $x\in X_1$, outputs a left-regular unweighted $d$-to-$1$ instance $\Phi'$ satisfying the following:
    \begin{enumerate}
    \item If $\Phi$ admits a perfect $k$-compatible quantum assignment then $\Phi'$ admits a perfect $k$-compatible quantum assignment;
    \item for any $\delta>0$ and any $0<\epsilon<\frac{1}{d\ell^2}$, if $\sat(\Phi')>\delta+\frac{1}{\ell}+(1-\delta)d\ell^2\epsilon$, then there exists a classical assignment $f$ for $\Phi$ such that $\delta$-fraction of the variables $x\in X_1$ satisfy $\sat_{f,x}(\Phi)>\frac{1}{|X_1|}(\epsilon-\frac{1}{m})$.
    \end{enumerate}
\end{lem}

\begin{proof}
    Let $\Phi=(X_1\sqcup X_2,E,A,\pi,\phi)$ be the given (weighted) $d$-to-$1$ instance, where $X_1\sqcup X_2$ is the bipartition of the vertex set.
    %
    Let $\alpha=m\cdot|X_2|$.
    We construct a bipartite multigraph $\tilde G$ on vertex set $X_1\sqcup X_2$ and edge set $\tilde E$ defined as follows. 
    For each $x\in X_1$, choose an edge $\bar\bx\in E$ such that $\bar x_1=x$.
    For each edge $\bx\in E$ such that $x_1=x$ and $\bx\neq\bar\bx$, $\tilde E$ contains $\floor{\alpha\cdot\pi(\bx)}$ copies of $\bx$. Moreover, $\tilde E$ contains 
    \begin{align*}
        \alpha-\sum_{\substack{\bx\in E\setminus\{\bar\bx\}\\x_1=x}}\floor{\alpha\cdot\pi(\bx)}
    \end{align*}
    copies of the edge $\bar\bx$.
%
Observe that all vertices of $X_1$ have degree $\alpha$ in $\tilde G$. Thus, for $x\in X_1$, we let $\by^{(x)}=(y^{(x)}_1,\dots,y^{(x)}_\alpha)$ be the list of neighbours of $x$ in $\tilde G$, counted with the correct multiplicity.

Following~\cite{Dinur09:sicomp}, we define the unweighted $d$-to-$1$ instance $\Phi'=(X_1'\sqcup X_2,E',A,\phi')$ as follows.
    The set $X_1'$ contains a variable $(x,\bi)$ for each $x\in X_1$ and each $\ell$-tuple $\bi=(i_1,\dots,i_\ell)\in [\alpha]^\ell$.
%
For $x\in X_1$, $\bi\in [\alpha]^\ell$, and $j\in[\ell]$, we add to $E'$ the edge $\bx'=((x,\bi),y^{(x)}_{i_j})$. The set of admitted labellings for $\bx'$ is $\phi'_{\bx'}=\phi_{(x,y^{(x)}_{i_j})}$---in particular, $\Phi'$ is a $d$-to-$1$ instance.
%

The fact that $\Phi'$ satisfies condition $\textit{2.}$ was proved in~\cite[Lemmas~A.5--A.7]{Dinur09:sicomp}.
%
To prove condition $\textit{1.}$,
suppose that $\Phi$ admits a perfect $k$-compatible quantum assignment $\mathfrak{Q}=\{Q_{x,a}:\, x\in X_1\sqcup X_2, a\in A\}$.
%
%Recalling the definition of $d$-to-$1$ instances in Section~\ref{sec_label_cover_games}, decompose the alphabet $A$ as
%$A=A_1\sqcup A_2$. 
It is straightforward to check that the set $\mathfrak{W}=\{W_{x',a}:\, x'\in X_1'\sqcup X_2, a\in A\}$ defined by $W_{(x,\bi),a}=Q_{x,a}$ for each $(x,\bi)\in X_1'$, $a\in A$ and $W_{x,a}=Q_{x,a}$ for each $x\in X_2$, $a\in A$ yields a perfect $k$-compatible quantum assignment for $\Phi'$, as needed.
\end{proof}

%We say that a $k$-compatible quantum strategy $\mathfrak{Q}$ for a CSP instance $\Phi$ is \textit{optimal} if $\qsat_{\mathfrak{Q}}(\Phi)=\qsat^k(\Phi)$.
%
Before proceeding with the last step of the transformation from $d$-to-$1$ to $d$-to-$d$ games, 
we need to prove the following technical fact, stating that the PVMs in an optimal quantum strategy for a bipartite label-cover instance can be assumed, without loss of generality, to project onto the trivial space $\{\bzero\}$ unless the corresponding variable and label are in matching parts of the bipartition of the instance.
%\LC{Check this proof}DONE
\begin{prop}
\label{prop_only_relevant_projectors}
    Let $\Phi=(X_1\sqcup X_2,E,A,\pi,\phi)$ be a bipartite label-cover instance and let $A=A_1\sqcup A_2$ be a decomposition of $A$ such that $\phi_\bx\subseteq A_1\times A_2$ for each $\bx\in E$.
    Given any $k$-compatible quantum assignment $\mathfrak{Q}$ for $\Phi$, there exists a $k$-compatible quantum assignment $\mathfrak{W}=\{W_{x,a}:\, x\in X_1\sqcup X_2, a\in A\}$ for $\Phi$ such that
    \begin{itemize}
        \item $\qsat_{\mathfrak{W}}(\Phi)\geq \qsat_{\mathfrak{Q}}(\Phi)$;
        \item $W_{x,a}=O$ whenever $x\in X_i$ and $a\in A_j$ for $i\neq j\in [2]$.
    \end{itemize}
\end{prop}
%
\begin{proof}
Take a $k$-compatible quantum assignment $\mathfrak{Q}=\{Q_{x,a}:\, x\in X_1\sqcup X_2, a\in A\}$, and 
consider the set 
    \begin{align*}
        S_{\mathfrak{Q}}
        =
        \{(x,a)\suchThat x\in X_i,\,a\in A_j,\, i\neq j,\, \mbox{and } Q_{x,a}\neq O\}.
    \end{align*}
If $S_{\mathfrak{Q}}=\emptyset$, there is nothing to prove. Otherwise, choose $(\tilde x,\tilde a)\in S_{\mathfrak{Q}}$ and fix a label $\hat a\in A_i$. Define the following linear applications: $W_{\tilde x,\tilde a}=O$, $W_{\tilde x,\hat a}=Q_{\tilde x,\tilde a}+Q_{\tilde x,\hat a}$, and $W_{x,a}=Q_{x,a}$ for all other choices of $x\in X_1\sqcup X_2$ and $a\in A$. Consider now the set $\mathfrak{W}=\{W_{x,a}:\, x\in X_1\sqcup X_2, a\in A\}$.
%

It is straightforward to check that $\mathfrak{W}$ is a $k$-compatible quantum assignment for $\Phi$.
%
Furthermore, for each $\bx\in E$ and each $\ba\in A^2$, consider the linear application $M_{\bx,\ba}=W_{x_1,a_1}W_{x_2,a_2}-Q_{x_1,a_1}Q_{x_2,a_2}$.
%
We have
\begin{align}
\label{eqn_2612_1746}
    \qsat_{\mathfrak{W}}(\Phi)-\qsat_{\mathfrak{Q}}(\Phi)
    =
    \frac{1}{\dim(\HH)}\mathbb{E}_{\bx\sim\pi}
    \sum_{\ba\in \phi_\bx}\tr(M_{\bx,\ba}).
\end{align}
We claim that $\tr(M_{\bx,\ba})\geq 0$ for each $\bx\in E$ and each $\ba\in\phi_\bx$. Suppose for concreteness that $i=1$ and $j=2$, so $\tilde x\in X_1$, $\tilde a\in A_2$, and $\hat a\in A_1$ (the other case is analogous).
%
If $x_1\neq \tilde x$ or $a_1\not\in\{\tilde a,\hat a\}$, then $M_{\bx,\ba}=O$ and the claim is true, so we can assume that $x_1=\tilde x$ and $a_1\in\{\tilde a,\hat a\}$. 
%
Since $\ba\in\phi_\bx\subseteq A_1\times A_2$, it must hold that $a_1\in A_1$, so $a_1\neq\tilde a$. The only remaining case is when $x_1=\tilde x$ and $a_1=\hat a$. We obtain
\begin{align*}
    M_{\bx,\ba}
    =
    W_{\tilde x,\hat a}W_{x_2,a_2}-Q_{\tilde x,\hat a}Q_{x_2,a_2}
    =
    (Q_{\tilde x,\tilde a}+Q_{\tilde x,\hat a})Q_{x_2,a_2}-Q_{\tilde x,\hat a}Q_{x_2,a_2}
    =
    Q_{\tilde x,\tilde a}Q_{x_2,a_2}.
\end{align*}
Since the trace of the product of two positive semidefinite matrices is nonnegative, it follows that $\tr(M_{\bx,\ba})\geq 0$, as required. As a consequence,~\eqref{eqn_2612_1746} implies that $\qsat_{\mathfrak{W}}(\Phi)\geq\qsat_{\mathfrak{Q}}(\Phi)$.

Observe now that $|S_{\mathfrak{W}}|=|S_{\mathfrak{Q}}|-1$. Hence, after repeating the process for a finite number of times, we end up with a $k$-compatible quantum assignment satisfying the conditions of the proposition.
\end{proof}

