\begin{lem}
\label{lem_dinur_tre}
There is an (efficient) procedure that, given as input an unweighted left-regular $d$-to-$1$ instance $\Phi$, outputs an
unweighted $d$-to-$d$ instance $\Phi'$ satisfying the following:
    \begin{enumerate}
        \item If $\Phi$ admits a perfect $2k$-compatible quantum assignment then $\Phi'$ admits a perfect $k$-compatible quantum assignment;
        \item for any $\epsilon>0$ and any $t\in\N$, if $\isat_t(\Phi')\geq\epsilon$, then $\sat(\Phi)\geq\frac{\epsilon}{t^2}$.
    \end{enumerate}
\end{lem}
%
\begin{proof}
Let $\Phi=(X_1\sqcup X_2,E,A,\phi)$ be the given $d$-to-$1$ instance. 
Recall from the definition of $d$-to-$1$ games in Section~\ref{subsec_CSP_predicates} that the alphabet $A$ can be decomposed as $A=A_1\sqcup A_2$ in a way that $\phi_\bx\subseteq A_1\times A_2$ for each $\bx\in E$.
%
Following~\cite{Dinur09:sicomp}, we consider the unweighted label-cover instance $\Phi'=(X_1,E',A_1,\phi')$ defined as follows. For each pair $(x,y)$, $(x',y)$ of edges in $E$ sharing a variable in $X_2$, we add the edge $(x,x')$ in $E'$. The corresponding set of admitted labellings is
    \begin{align*}
        \phi'_{(x,x')}=\{(a,a')\in A_1^2\suchThat\exists b\in A_2:\,(a,b)\in\phi_{(x,y)},\,(a',b)\in\phi_{(x',y)}\}.
    \end{align*}
%
It is easy to check that all constraints of $\Phi'$ are $d$-to-$d$, and it was shown in~\cite[Lemma~A.9]{Dinur09:sicomp} that condition $2.$ holds.


We now show that condition $1.$ holds, too. 
%
Take a perfect $2k$-compatible quantum assignment $\mathfrak{Q}=\{Q_{x,a}:\, x\in X_1\sqcup X_2, a\in A\}$ for $\Phi$ over some Hilbert space $\HH$.
%
Using Proposition~\ref{prop_only_relevant_projectors}, we can assume without loss of generality that $Q_{x,a}=O$ whenever $x\in X_i$ and $a\in A_j$ for $i\neq j\in [2]$.
%
We define $W_{x,a}=Q_{x,a}$ for each $x\in X_1$ and each $a\in A_1$. Note that 
    \begin{align*}
        \sum_{a\in A_1}W_{x,a}
        =
        \sum_{a\in A_1}Q_{x,a}
        =
        \sum_{a\in A}Q_{x,a}
        =
        \id_\HH,
    \end{align*}
    where the second equality comes from the second condition in Proposition~\ref{prop_only_relevant_projectors}.
    %and $W_{x,a}W_{x,a'}=Q_{x,a}Q_{x,a'}=O$ whenever $a\neq a'$. 
    Hence, the set $\mathfrak{W}=\{W_{x,a}\suchThat x\in X_1,a\in A_1\}$ is a quantum assignment for $\Phi'$. 

    Consider now an edge $(x,x')\in E'$, and let $y$ be the corresponding vertex of $X_2$ such that $(x,y)$ and $(x',y)$ are both in $E$. Take
    a pair $(a,a')\in A_1^2\setminus \phi'_{(x,x')}$, which means that, for each $b\in A_2$, either $(a,b)\not\in\phi_{(x,y)}$ or $(a',b)\not\in\phi_{(x',y)}$. 
    %
    %
    Since the quantum assignment $\mathfrak{Q}$ is perfect, for each $b\in A_2$ it holds that 
    \begin{align*}
        Q_{x,a}\cdot Q_{y,b}\neq O
        \quad\Rightarrow \quad
        (a,b)\in\phi_{(x,y)}
        \quad\Rightarrow \quad
        (a',b)\not\in\phi_{(x',y)}
        \quad\Rightarrow \quad
        Q_{x',a'}\cdot Q_{y,b}= O,
    \end{align*}
    which means that 
    \begin{align*}
    Q_{x,a}\cdot Q_{y,b}\cdot Q_{x',a'}\cdot Q_{y,b}=O.
    \end{align*}
    Since that the vertices $x'$ and $y$ are adjacent in $\Phi$, the corresponding projectors of $\mathfrak{Q}$ commute, so we obtain
    \begin{align*}
        Q_{x,a}\cdot Q_{x',a'}\cdot Q_{y,b}=O
    \end{align*}
    for each $b\in A_2$. Taking the sum over $A_2$ (and using again the second condition of Proposition~\ref{prop_only_relevant_projectors}), we find
    \begin{align*}
        O&=\sum_{b\in A_2}Q_{x,a}\cdot Q_{x',a'}\cdot Q_{y,b}
        =
        Q_{x,a}\cdot Q_{x',a'}\cdot \sum_{b\in A_2}Q_{y,b}
        =
        Q_{x,a}\cdot Q_{x',a'}\cdot \id_\HH\\
        &=
        Q_{x,a}\cdot Q_{x',a'}
        =
        W_{x,a}\cdot W_{x',a'},
    \end{align*}
    whence we deduce that the quantum assignment $\mathfrak{W}$ is perfect.
%

Finally, it is clear from the definition of $\Phi'$ that $\dist_{\Phi'}(x,x')=\frac{1}{2}\cdot\dist_{\Phi}(x,x')$ for each pair of vertices $x,x'\in X_1$. Hence, the $k$-compatibility of $\mathfrak{W}$ follows directly from the $2k$-compatibility of $\mathfrak{Q}$, thus concluding the proof.
\end{proof}

\begin{proof}[Proof of Proposition~\ref{prop_d_to_d_after_dinur}]

Fix $d,\epsilon, k,t$ as in the statement of the proposition, and consider the parameters $\delta=\frac{\epsilon}{3t^2}$, $\epsilon'=\frac{\epsilon}{3d\ceil{1/\delta}^2t^2}$, $\epsilon''=\frac{\epsilon'}{2}$, and $\epsilon'''=\frac{\delta\epsilon''}{2}$.

Using Conjecture~\ref{conj_d_to_1_khot_quantum}, let $\Phi$ be a $d$-to-$1$ instance such that 
$\Phi$ admits a perfect $2k$-compatible quantum assignment
but $\sat(\Phi)<\epsilon'''$. 
%
We now consecutively apply to $\Phi$ the three transformations of Lemmas~\ref{lem_dinur_uno},~\ref{lem_dinur_due}, and~\ref{lem_dinur_tre}.
%
Note that the transformation in Lemma~\ref{lem_dinur_uno} does not change the constraints in the input label-cover instance. Hence, it maps $d$-to-$1$ instances to $d$-to-$1$ instances. Let $\Phi'$ be the result of applying Lemma~\ref{lem_dinur_uno} to $\Phi$ with parameter $h=2$; let $\Phi''$ be the result of applying Lemma~\ref{lem_dinur_due} to $\Phi'$ with parameters $\ell=\ceil{1/\delta}$ and $m=\ceil{2/\epsilon'}$; and let $\Phi'''$ be the result of applying Lemma~\ref{lem_dinur_tre} to $\Phi''$. We claim that the resulting $d$-to-$d$ instance $\Phi'''$ meets the requirements of the proposition. First, the quantum completeness of the transformations implies that $\Phi$, $\Phi'$, and $\Phi''$ admit perfect $2k$-compatible quantum assignments and, thus, $\Phi'''$ admits a perfect $k$-compatible quantum assignment.



%\begin{align}
%\label{eqn_chain_quantum_sat_1540_1122}
%    \qsat_{2k}(\Phi)=1\;\Rightarrow\;\qsat_{2k}(\Phi')=1\;\Rightarrow\;\qsat_{2k}(\Phi'')=1\;\Rightarrow\;\qsat_{k}(\Phi''')=1,
%\end{align}
%as needed.

Observe now that $(1-\frac{1}{h})\delta\epsilon''=\epsilon'''>\sat(\Phi)$.
Hence, part $\textit{2.}$ of Lemma~\ref{lem_dinur_uno} (with parameters $\delta,\epsilon''$) implies that there is no assignment $f'$ for $\Phi'$ for which a $\delta$-fraction of the variables $x'\in X_1'$ satisfy $\sat_{f',x'}(\Phi')\geq\frac{\epsilon''}{|X_1'|}$, where $X_1'$ is the left-part of the variable set of $\Phi'$. Next, note that the parameter choice guarantees that $0<\epsilon'<\frac{1}{d\ell^2}$ and $\epsilon'-\frac{1}{m}\geq \epsilon''$. Hence, part $\textit{2.}$ of Lemma~\ref{lem_dinur_due} (with parameters $\delta,\epsilon'$) guarantees that $\sat(\Phi'')\leq \delta+\frac{1}{\ell}+(1-\delta)d\ell^2\epsilon'$. Finally, observe that
\begin{align*}
    \delta+\frac{1}{\ell}+(1-\delta)d\ell^2\epsilon'
    <
    \delta+\frac{1}{\ell}+d\ell^2\epsilon'
    \leq
    \frac{\epsilon}{3t^2}+\frac{\epsilon}{3t^2}+\frac{\epsilon}{3t^2}=\frac{\epsilon}{t^2}.
\end{align*}
Therefore, part $\textit{2.}$ of Lemma~\ref{lem_dinur_tre} implies that $\isat_t(\Phi''')<\epsilon$, thus concluding the proof of the proposition.
\end{proof}

\begin{rem}
\label{rem_appendix_reductions_preserve_H}
We point out that the Hilbert space associated with quantum assignments is preserved throughout the transformations occurring in the proof of Proposition~\ref{prop_d_to_d_after_dinur}. Indeed, the proofs of Lemmas~\ref{lem_dinur_uno},~\ref{lem_dinur_due}, and~\ref{lem_dinur_tre} and Proposition~\ref{prop_only_relevant_projectors} show how to transfer perfect locally compatible quantum assignments for a given $d$-to-$1$ instance over a Hilbert space $\HH$ to perfect locally compatible quantum assignments for the resulting $d$-to-$d$ instance over the \textit{same} space $\HH$.
\end{rem}


